(window.GIM_TS=window.GIM_TS||{})["Yevamot.3"]={"from":72,"a":[["\u0003דרכי חד גבך\u0004 \u0005[דרך אחת שלי אצלך]\u0006 \u0003הוא,\u0004 כלומר, שהרי זו טענה ודאית וברורה שהיתה לו שם דרך, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003מי איכא למימר הכי\u0004 \u0005[האם יש\u0006 מקום \u0005לומר כך]?\u0006 הרי הוא עצמו אינו יודע מהי התביעה שהוא תובע, שהרי אינו יודע בנו של מי הוא, ולכן אין לו טענת ודאי.","\u0003ו\u0004מצד שני, \u0003ר' ירמיה אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003אנא דאמרי\u0004 \u0005[אני שאומר אני\u0006 את דברי\u0005],\u0006 יכול להיות ש\u0003אפילו ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 יכול אני לאומרם. ומדוע: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 \u0003אלא משום ש\u0004\u0003אמר ליה\u0004 \u0005[ש\u0006יכול בעל השדות \u0005לומר לו]\u0006 \u0003אי שתקת\u0004 \u0005[אם תשתוק] —\u0006 \u0003שתקת\u0004 \u0005[תשתוק],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — מהדרנא שטרא למרייהו\u0004 \u0005[אחזיר את השטרות לבעליהם]\u0006 \u0003ולא מצית\u0004 \u0005[תוכל]\u0006 \u0003לאשתעויי דינא בהדייהו\u0004 \u0005[לדבר בדין איתם],\u0006 \u0003אבל הכא מי איכא למימר הכי\u0004 \u0005[כאן האם יש\u0006 מקום \u0005לומר כך]?\u0006 שהרי כאן גם אם יחזירו את הדברים למצב הראשון, לפני שהיבם מת, עוד יהיה לספק מקום לתביעה, ולכן יתכן שאף חכמים יודו לו בזה.","ועוד בעיה באותו נושא: \u0003ספק ויבם שבאו לחלוק בנכסי סבא,\u0004 אביו של היבם, שהוא סבו של הספק. \u0003ספק אמר: האי גברא בר מיתנא\u0004 \u0005[אדם זה,\u0006 אני, \u0005בן\u0006 של \u0005המת]\u0006 \u0003הוא\u0004 וכיון שאבי היה אחד מבני הסב, הרי אני יורש את חלקו של אבי בנכסים \u0003ופלגא דידי\u0004 \u0005[ומחצית\u0006 הנכסים, כלומר, חלקו של המת, \u0005שלי]\u0006 \u0003הוא,\u0004 ואילו \u0003יבם אמר: את, בראי דידי את, ולית לך ולא מידי\u0004 \u0005[אתה, בני שלי אתה ואין לך ולא כלום\u0006 בנכסים\u0005],\u0006","\u0003הוי\u0004 \u0005[הרי]\u0006 ה\u0003יבם ודאי,\u0004 שהרי הוא ודאי בנו של הסב, \u0003וספק\u0004 אין לו אלא טענת \u0003ספק, ו\u0004כלל הוא: \u0003אין ספק מוציא מידי ודאי,\u0004 שטענה מספק איננה יכולה לבטל טענה של ודאי.","מקרה נוסף: \u0003ספק ובני יבם שבאו לחלוק בנכסי סבא. ספק אמר: ההוא גברא בר מיתנא\u0004 \u0005[אדם זה,\u0006 אני, \u0005בן המת]\u0006 \u0003הוא, ופלגא דידי\u0004 \u0005[ומחצית\u0006 הנכסים \u0005שלי]\u0006 \u0003הוא,\u0004 שהרי אני יורש את נכסי הסב מכח אבי, שהוא בנו. \u0003ובני יבם אמרי: אחונא את ומנתא אית לך בהדן\u0004 \u0005[אחינו אתה וחלק יש לך אתנו].\u0006","ומעתה \u0003פלגא דקמודי להו\u0004 \u0005[מחצית\u0006 מנכסי הסב \u0005שהוא מודה להם]\u0006 — \u0003שקלי\u0004 \u0005[\u0006הם \u0005לוקחים],\u0006 שכיון שהוא טוען שהוא יורש מכח בנו האחר של הסב, ולכן אין לו תביעה על מחצית הנכסים של היבם. \u0003תילתא דקא מודו ליה\u0004 \u0005[השליש שהם מודים לו]\u0006 שהרי שני האחרים אומרים שהוא אחד מאחיהם, ולכן על כל פנים מגיע לו שליש — \u0003שקל\u0004 \u0005[\u0006הוא \u0005לוקח],\u0006 משום שהם מודים לו. \u0003פש להו דנקא\u0004 \u0005[נשארה להם\u0006 איפוא \u0005שישית],\u0006 שלגביה ישנם חילוקי דעות — \u0003הוי\u0004 \u0005[הרי\u0006 זה\u0005]\u0006 \u0003ממון המוטל בספק וחולקין.\u0004","ומקרה נוסף: אם באו \u0003סבא ויבם\u0004 לחלוק \u0003בנכסי ספק,\u0004 שמת אותו ספק, והסב טוען שהספק הוא בנו של בנו המת, והוא שיורש אותו מכוחו, והיבם טוען שבנו שלו הוא, והוא שיורש אותו. \u0003או\u0004 שהיו \u0003סבא וספק\u0004 באים שניהם לחלוק \u0003בנכסי יבם\u0004 שלא היו לו בנים, הסב אומר שאין הספק בנו של היבם ומכיון שכך הוא יורשו, שהאב קודם לכל יוצאי ירכו בירושה (בבא בתרא קטו, א), והספק טוען שהוא בנו והוא שיורשו —","\u0003הוי\u0004 \u0005[הרי\u0006 זה\u0005]\u0006 \u0003ממון המוטל בספק וחולקין.\u0004","\u0003שומרת יבם\u0004 (אשה שמת בעלה וממתינה לייבום) \u0003שנפלו לה נכסים\u0004 בירושה מקרוביה — \u0003מודים בית שמאי ובית הלל שמוכרת\u0004 אותם או \u0003נותנת\u0004 אותם לכתחילה (אף שחלקו בית הלל בארוסה סתם), מפני שאינה נחשבת כנשואה לו והנכסים לגמרי ברשותה \u0003ו\u0004מה שעשתה — \u0003קיים.\u0004","אם \u0003מתה\u0004 שומרת יבם, \u0003מה יעשה בכתובתה\u0004 שמגיעה לה מן המת, \u0003ו\u0004כן \u0003בנכסים הנכנסים ויוצאין עמה,\u0004 אותם נכסים שהביאה כנכסי מלוג מבית אביה, שאינם שייכים לבעל אלא הם יוצאים איתה לכשהיא מתגרשת או מתאלמנת? \u0003בית שמאי אומרים: יחלוקו\u0004 באלה \u0003יורשי הבעל, עם יורשי האב. ובית הלל אומרים:\u0004 ה\u0003נכסים\u0004 ישארו כולם \u0003בחזקתן.\u0004 כיצד? \u0003כתובה\u0004 תישאר \u0003בחזקת יורשי הבעל,\u0004 מאחר שאת הכתובה היה הבעל צריך לתת מנכסיו, וכיון שיש ספק למי כסף זה שייך, נשאיר את הכתובה בחזקת יורשיו של הבעל, ו\u0003נכסים הנכנסים ויוצאין עמה,\u0004 כיון שחזקתם שהם של בית אביה — יהיו \u0003בחזקת יורשי האב.\u0004","אם היבם \u0003כנסה,\u0004 את אשת אחיו המת — \u0003הרי היא כאשתו לכל דבר\u0004 ודין היבמה כדין אשה סתם. \u0003ובלבד,\u0004 כלומר, בפרט אחד דינה שונה מאשה אחרת, \u0003שתהא כתובתה על נכסי בעלה הראשון,\u0004 ולא מנכסיו של היבם.","שואלים: \u0003מאי שנא רישא דלא פליגי\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 המקרה שב\u0005ראש\u0006 המשנה \u0005שלא נחלקו]\u0006 בית הלל ובית שמאי, שבחייה של השומרת יבם הכל מודים שנכסים שקיבלה בירושה הם בודאי שלה, ויכולה לעשות בהם מה שרוצה, \u0003ומאי שנא סיפא דפליגי\u0004 \u0005[ו\u0006ב\u0005מה שונה הסוף ש\u0006הם \u0005חלוקים]\u0006 שבית שמאי אומרים שאם מתה יש חלק ליורשי הבעל בנכסים הללו?","\u0003אמר עולא,\u0004 יש לחלק: \u0003רישא\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 מדובר ש\u0003נפלה\u0004 לייבום \u0003כשהיא ארוסה\u0004 לבעלה הראשון, והנכסים נפלו לה בירושה כשהיתה שומרת יבם. והואיל ואם היה ארוסה חי לא היה זוכה בנכסיה אלה — כל שכן שלא יזכה בהם היבם. \u0003וסיפא\u0004 \u0005[ו\u0006ב\u0005סוף]\u0006 המשנה מדובר ש\u0003נפלה\u0004 לייבום \u0003כשהיא נשואה\u0004 (לאחר שהיתה נשואה), שמכיון שאם היה בעלה חי היו עוברים הנכסים הללו לרשות הבעל, עכשיו שנפלו כשהיא שומרת יבם, חולקים בהם גם יורשי הבעל.","ומעירים: \u0003וקסבר\u0004 \u0005[וסבור]\u0006 \u0003עולא\u0004 כי \u0003זיקת ארוסה,\u0004 זיקת ייבום באשה שהיתה רק ארוסה לאח המת של היבם, \u0003עושה\u0004 אותה שתיחשב \u0003ספק ארוסה,\u0004"],["\u0003זיקת נשואה עושה\u0004 אותה שתיחשב \u0003ספק נשואה.\u0004","ומסבירים: \u0003זיקת ארוסה עושה ספק ארוסה,\u0004 מדוע ספק — \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003ודאי ארוסה,\u0004 וכי בארוסה \u0003מודים בית הלל שמוכרת ונותנת\u0004 לכתחילה \u0003וקיים?\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שנחלקו בכך: \u0003נפלו לה\u0004 לאשה \u0003נכסים\u0004 בירושה \u0003משנתארסה, בית שמאי אומרים: תמכור\u0004 אם תרצה, \u0003ובית הלל אומרים: לא תמכור. אלו ואלו מודים שאם מכרה ונתנה — קיים. אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003זיקת ארוסה עושה\u0004 רק \u0003ספק ארוסה.\u0004","וכמו כן \u0003זיקת נשואה עושה ספק נשואה. דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003ודאי נשואה\u0004 היא, וכי \u0003בית שמאי אומרים\u0004 בזה \u0003יחלוקו יורשי הבעל עם יורשי האב?\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אם \u0003נפלו לה נכסים משנשאת — אלו ואלו,\u0004 גם בית הלל וגם בית שמאי, \u0003מודים, שאם מכרה ונתנה\u0004 לאחרים — \u0003שהבעל מוציא מיד הלקוחות.\u0004 משמע שהכל בחזקת הבעל. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003זיקת נשואה עושה ספק נשואה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה\u0004 לעולא: לשיטתך שמדובר פה בספק ארוסה וספק נשואה לגבי זיקה, \u0003אדמפלגי\u0004 \u0005[עד\u0006 ש\u0005הם חולקים]\u0006 \u0003בגופה,\u0004 כלומר, בגופם של אותם נכסים \u0003ו\u0004בחלוקתם \u0003לאחר מיתה\u0004 של היבמה, \u0003לפלגו\u0004 \u0005[שיחלקו]\u0006 בית שמאי ובית הלל בנושא קרוב יותר, בדברים שנוגעים \u0003בחייה, ול\u0004ענין \u0003פירות,\u0004 שהשאלה תהיה: מי אוכל פירות הנכסים הללו, האשה או היבם, שלדעת בית שמאי יחלוקו ולדעת בית הלל הנכסים בחזקתה, שהרי לדעתך היא היא המחלוקת!","\u0003אלא אמר רבה: אידי ואידי\u0004 \u0005[זה וזה]\u0006 גם ראשה וגם סופה של משנתנו, מדובר בהם ש\u0003נפלה\u0004 לייבום \u0003כשהיא נשואה, וזיקת נשואה עושה\u0004 אותה שתיחשב \u0003ספק נשואה.\u0004 וכך יש להסביר: \u0003רישא\u0004 \u0005[ראשית\u0006 המשנה\u0005]\u0006 מדברת במקרה \u0003דאיהי קיימא\u0004 \u0005[שהיא קיימת,\u0006 חיה\u0005] —\u0006 \u0003הוה לה איהי\u0004 \u0005[הרי היא],\u0006 יש לה טענת \u0003ודאי\u0004 שהנכסים שייכים לה, שהרי הקרן ודאי שייך לה, \u0003ואינהו\u0004 \u0005[והם],\u0006 כל האחרים הבאים לתבוע, יש להם רק טענת \u0003ספק,\u0004 שהרי אמרנו שהיא ספק נשואה, \u0003ו\u0004כלל הוא: \u0003אין ספק מוציא מידי ודאי.\u0004","ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סופה\u0006 של המשנה\u0005]\u0006 מדובר ש\u0003מתה,\u0004 ואם כן \u0003הללו,\u0004 יורשי האב, \u0003באין לירש, והללו,\u0004 יורשי הבעל, \u0003באין לירש,\u0004 ומכיון שיש כאן ספק — לדעת בית שמאי \u0003יחלוקו,\u0004 ולבית הלל נכסים בחזקתה. וכשהיא חיה, אף בית שמאי מודים שנכסים בחזקתה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 לרבה: \u0003ו\u0004האם \u0003ל\u0004דעת \u0003בית שמאי אין ספק מוציא מידי ודאי? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נפל הבית\u0004 בבת אחת \u0003עליו\u0004 על אדם אחד \u0003ועל אביו,\u0004 או \u0003עליו ועל מורישיו,\u0004 כלומר, אנשים שהוא היורש אותם, \u0003והיו עליו\u0004 חובות של \u0003כתובת אשה ו\u0004גם של \u0003בעל חוב\u0004 אחר ולא היו לו נכסים כדי לשלם מהם גם את חובותיו וגם את כתובת אשתו, ולמורישים יש נכסים.","\u0003יורשי האב אומרים: הבן מת ראשון\u0004 ולא ירש איפוא מאומה, \u0003ואחר כך מת האב,\u0004 ולכן אנו, יורשי האב, זוכים בירושה ואין לבעלי חובותיו של הבן כל זכות בנכסים, \u0003ובעל חוב אומר:\u0004 לא כן, אלא \u0003האב מת ראשון,\u0004 ועם מותו ירש הבן את נכסיו, \u0003ואחר כך מת הבן,\u0004 ובעלי החובות יכולים איפוא לדבריהם לתבוע את חובם מנכסיו —","\u0003בית שמאי אומרים: יחלוקו, ובית הלל אומרים: נכסים בחזקתן\u0004 של יורשי האב, ובעלי החוב שבאים בטענה צריכים להביא ראיה.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003יורשי האב\u0004 הם \u0003ודאי, ובעל חוב\u0004 בא בטענת \u0003ספק, ו\u0004לדעת בית שמאי האומרים שיחלוקו, \u0003קאתי\u0004 \u0005[בא]\u0006 ה\u0003ספק ומוציא\u0004 חצי הנכסים \u0003מידי\u0004 ה\u0003ודאי!\u0004","ומשיבים: שם אין בית שמאי רואים את דרישת בעלי החובות כטענת ספק, כי \u0003קסברי\u0004 \u0005[סבורים]\u0006 \u0003בית שמאי: שטר העומד לגבות — כגבוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 כלומר, כיון שיש בידם שטר חוב, הרי זה כאילו כבר גבו אותו והוא בחזקתם, ולכן אף את טענתם צריך לראות כטענת ודאי, שיש להם חזקה בנכסים לא פחות מזו של היורשים.","\u0003ומנא תימרא\u0004 \u0005[ומניין אתה אומר]\u0006 שזו דעת בית שמאי, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 נשים שקינאו להן בעליהן שלא ייסתרו עם אחר, ונסתרו, והן איפוא ספק סוטות, והיו צריכים להביאן למקדש שייבדקו על ידי שתיית המים המרים, ו\u0003מתו בעליהן עד שלא שתו\u0004 (כלומר, לפני שהנשים שתו) — \u0003בית שמאי אומרים: נוטלות כתובתן\u0004 כשאר נשים, \u0003ואינן שותות\u0004 מן המים המרים, שהרי אין להן בעל שבשבילו יצטרכו להיבדק. \u0003ובית הלל אומרים:\u0004 הכלל הוא: \u0003או שותות או לא נוטלות כתובתן.\u0004","ותוהים: \u0003או שותות?!\u0004 כיצד יכולות הן לשתות? הלא \u0003\"והביא האיש את אשתו\"\u0004 (במדבר ה, טו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003וליכא\u0004 \u0005[ואין\u0006 כאן מצב שכזה\u0005],\u0006 שהרי האיש מת! \u0003אלא\u0004 צריך להבין את דבריהם כך: \u0003מתוך שלא שותות — לא נוטלות כתובתן,\u0004 שמא זנו.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 בסוטה ש\u0003ספק הוא, ספק זנאי\u0004 \u0005[זנתה]\u0006 \u0003ספק לא זנאי\u0004 \u0005[זנתה],\u0006 \u0003ו\u0004בכל זאת לדעת בית שמאי \u0003קאתי\u0004 \u0005[בא]\u0006 \u0003ספק\u0004 של תביעת האשה את כתובתה \u0003ומוציא מידי ודאי\u0004 של היורשים! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי לדעת בית שמאי \u0003שטר העומד לגבות כגבוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006, וכיון ששטר הכתובה נחשב כגבוי, הרי גם לאותן הנשים יש טענה, שהיא כטענת ודאי.","ושואלים: \u0003ואביי\u0004 שהקשה על רבה מענין \"נפל הבית עליו\" וכו', \u0003לותביה מהא\u0004 \u0005[שיקשה לו מזו]\u0006 מענין סוטה. שהרי לשיטתו היה יכול להוכיח מכאן שספק מוציא מידי ודאי לדעת בית שמאי! ומשיבים: אביי סבר שמדין סוטה אין להקשות, כי \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003כתובת אשה שאני\u0004 \u0005[שונה]\u0006 בדין, \u0003משום חינא\u0004 \u0005[חן],\u0006 שעשו חכמים חיזוק לכתובת אשה יותר מבשטרות חוב אחרים, משום שרצו שיהיה חן האנשים על הנשים, ותיקנו שיהיה לשטר הכתובה תוקף מרובה.","ושואלים שוב על אביי, ולפי הבנתו: \u0003ולותביה\u0004 \u0005[ושיקשה לו]\u0006 מדין \u0003כתובה דמתניתין\u0004 \u0005[ש\u0006ב\u0005משנתנו],\u0006 שלכאורה גם ממשנתנו יוצא שלדעת בית שמאי יורשי האשה חולקים לא רק בנכסיה אלא גם בכתובתה, והרי טענת היורשים לגבי כתובתה של אשה זו אינה אלא טענת ספק, משמע שטענת ספק שלהם בכתובה מוציאה מידי ודאי של יורשי הבעל!","ומשיבים: \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 בית שמאי בזה. ומה שאמרו \"יחלוקו\" הכוונה היא בנכסים שנפלו לה בירושה, ולא לגבי כתובתה. ותוהים: \u0003ולא?!\u0004 וכי לא נחלקו בכך? \u0003והא קתני\u0004 \u0005[והרי שנה\u0006 במשנה\u0005]:\u0006 \u0003מתה\u0004 אשה זו, \u0003מה יעשה בכתובתה ובנכסים הנכנסים ויוצאין עמה\u0004 — \u0003בית שמאי אומרים: יחלוקו יורשי הבעל עם יורשי האב, ובית הלל אומרים: נכסים בחזקתן.\u0004 משמע שבית שמאי סבורים שאף בכתובה יש חלוקה!","ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006 התנא\u0005],\u0006 זו היתה הכוונה: \u0003מתה, מה יעשה בכתובתה, ושבקה\u0004 \u0005[והניחה,\u0006 עזב את הבעיה הזו\u0005]\u0006 ולא פתרה. ואילו בענין \u0003נכסים הנכנסים והיוצאים עמה,\u0004 בזה — \u0003בית שמאי אומרים: יחלוקו יורשי הבעל עם יורשי האב, ובית הלל אומרים: נכסים בחזקתן.\u0004","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 שאין בית שמאי חולקים בכתובה, ואין הטעם משום ששטר העומד להיגבות הריהו כגבוי כבר, וראיה לדבר — \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 : \u0003יחלוקו יורשי הבעל עם יורשי האב.\u0004 משמע שיורשי הבעל באים ולוקחים דבר מאת יורשי האב, שלהם יש לכאורה זכות ראשונה, הרי שמדובר כאן בירושת נכסי מלוג שהם מבית אביה, \u0003ולא קתני\u0004 \u0005[שנה]\u0006 ש\u0003יורשי האב\u0004 חולקים \u0003עם יורשי הבעל,\u0004 שדבר זה ניתן להיאמר לגבי הכתובה שהאשה מקבלת מבעלה, משמע שהמחלוקת היתה רק ביחס לנכסים ולא לגבי הכתובה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אביי אמר\u0004 שאפשר לתרץ את המשנה לא כעולא ולא כרבה, אלא באופן אחר: \u0003רישא\u0004 \u0005[\u0006ב\u0005ראשיתה]\u0006 של המשנה מדובר ש\u0003נפלו לה\u0004 הנכסים בירושה \u0003כשהיא שומרת יבם,\u0004 ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סופה]\u0006 מדובר ש\u0003נפלו לה\u0004 הנכסים \u0003כשהיא תחתיו\u0004 של ה\u0003בעל\u0004 הראשון, ומכאן ההבדל."],["\u0003וקסבר\u0004 \u0005[וסבור]\u0006 \u0003אביי\u0004 שבאשה נשואה \u0003ידו\u0004 של הבעל \u0003כידה\u0004 ממש. כלומר, זכותו של הבעל בנכסים שיורשת שווה לזכותה בהם. לכן משמת וזקוקה ליבם, ידו של היבם בהם אינו כידה ולכן לבית הלל הנכסים בחזקתה, ולדעת בית שמאי, בנשואה, ידו של הבעל עדיפה מידה, ומשמת, יד היבם כידה ויחלוקו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי דנפלי\u0004 \u0005[אם שנפלו]\u0006 \u0003לה\u0004 הנכסים בירושה \u0003כשהיא תחתיו\u0004 של ה\u0003בעל\u0004 הראשון — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003ידו עדיפא מידה,\u0004 שכיון שנפלו לה כשהיתה נשואה, יש לבעל בהם זכות יתירה, ואם מתה הרי הם שלו, בין לעצמו ובין ליורשיו. ואפילו בית הלל מודים שיש ליורשי הבעל בנכסים.","\u0003אלא, אידי ואידי\u0004 \u0005[זה וזה,\u0006 שני החלקים במשנה, \u0005מדברים]\u0006 באופן ש\u0003נפלו לה\u0004 הנכסים \u0003כשהיא שומרת יבם,\u0004 וההבדל הוא: \u0003רישא\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 מדובר ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003בה\u0004 היבם \u0003מאמר,\u0004 ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סופה]\u0006 מדובר באופן \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003בה\u0004 היבם \u0003מאמר\u0004, שכיון שעשה בה מאמר, יש לו לשיטת בית שמאי (לעיל יבמות כט, א) קנין בה וזכה בנכסיה, ולשיטת בית הלל אין לו קנין.","ומסבירים: \u0003וקסבר\u0004 \u0005[וסבור]\u0006 \u0003רבא\u0004 ש\u0003מאמר ל\u0004דעת \u0003בית שמאי עושה\u0004 אותה \u0003ודאי ארוסה וספק נשואה.\u0004 וכוונת הדברים: \u0003ודאי ארוסה\u0004 לענין \u0003לדחות בצרה,\u0004 כלומר, שאם עשה בה מאמר, שוב אין צרתה מתייבמת, שבעלת המאמר נחשבת כאשתו גמורה לענין זה, \u0003וספק נשואה\u0004 לענין ירושתה, שיורשיה ויורשיו צריכים \u0003לחלוק בנכסים.\u0004","ומעירים: \u0003איתמר משמיה\u0004 \u0005[נאמר משמו]\u0006 של \u0003ר' אלעזר\u0004 פירוש למשנה \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רבא, ואיתמר משמיה\u0004 \u0005[ונאמר משמו]\u0006 של \u0003ר' יוסי בר' חנינא כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003אביי.\u0004","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אלעזר הכי\u0004 \u0005[כך],\u0006 כרבא? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר: מאמר לבית שמאי אינה קונה אלא לדחות בצרה בלבד,\u0004 משמע: ולא יותר מזה, והרי שיטת רבא היא שהמאמר עושה ספק נישואין!","ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות, שר' אלעזר הוא שאמר כדעת אביי, ור' יוסי בר' חנינא כדעת רבא. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם לא תיפוך\u0004 \u0005[תהפוך]\u0006 ואפשר להבין את הדברים גם כפי שנמסרו, ויש לחלק — \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' אלעזר: כי אמרי אנא\u0004 \u0005[כאשר אמרתי\u0006 לו \u0005אני]\u0006 שזה תוקפו של מאמר, כוונתי היתה ש\u0003לא סגי\u0004 \u0005[די]\u0006 \u0003לה בגט, אלא דבעי נמי\u0004 \u0005[שצריכה גם כן]\u0006 \u0003חליצה,\u0004 אבל \u0003לחלוק בנכסים דלא קני\u0004 \u0005[שאינו קונה]\u0006 הבעל בהם — \u0003מי אמרי\u0004 \u0005[האם אמרתי]?\u0006 כלומר, דבריו לא התייחסו לענין נכסים כלל, ואין כאן איפוא סתירה.","\u0003אמר רב פפא: דיוקא דמתניתין, כוותיה\u0004 \u0005[הדיוק של משנתנו\u0006 הוא \u0005כשיטתו]\u0006 של \u0003אביי, ואף על גב דקשיא\u0004 \u0005[ואף על פי שקשה]\u0006 מענין זה שנאמר במשנה \u0003\"מתה\",\u0004","ומה הדיוק — \u0003דקתני\u0004 \u0005[ששנה]\u0006 שם במשנתנו: \u0003נכסים הנכנסים ויוצאים עמה, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נכנסין\" ומאי\u0004 \u0005[ומה]\u0006 \u0003\"יוצאין\"? לאו\u0004 \u0005[האם לא]\u0006 \u0003\"נכנסין\"\u0004 פירושו: אלה שנכנסים \u0003לרשות הבעל, ו\"יוצאים\" —\u0004 פירושו \u0003מרשות הבעל לרשות האב,\u0004 ומדוייק הדבר לשיטת אביי שנפלו לה כשהיתה נשואה,","\u0003ואף על גב דקשיא\u0004 \u0005[ואף על פי שקשה]\u0006 ממה שכתוב במשנה \u0003\"מתה\",\u0004 וכמו שאמר רבה \u0003אדמפלגי\u0004 \u0005[עד שהם חלוקים]\u0006 \u0003בגופה\u0004 של הקרקע \u0003ולאחר מיתה\u0004 של האשה, \u0003לפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003בחייה ול\u0004ענין \u0003פירות,\u0004 שהרי ידו כידה, בכל זאת לשון המשנה מדוייקת כשיטת אביי.","\u0003ותו לא מידי\u0004 \u0005[ועוד אין דבר],\u0006 כלומר, אין עוד להאריך ולדייק בענין זה בדרך אחרת.","שנינו במשנה: \u0003כנסה — הרי היא\u0004 כאשתו לכל דבר. שואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו, \u0005הלכה]\u0006 נאמר הדבר? \u0003אמר ר' יוסי בר חנינא: לומר, ש\u0004אחר שמייבמה, \u0003מגרשה בגט ומחזירה,\u0004 אם ירצה.","ותוהים: \u0003מגרשה בגט, פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא ומדוע לא? ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ולקחה לו לאשה ויבמה\"\u0004 (דברים כה, ה) — \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]:\u0006 \u0003ועדיין יבומי הראשון עליה\u0004 כלומר, כל ימי נישואיה ליבם היא עדיין קרויה יבמה, ולכן \u0003בחליצה — אין\u0004 \u0005[כן]\u0006 נפטרת מן היבם, \u0003ובגט — לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהיא כאשתו לכל דבר.","עוד אמר ר' יוסי בר' חנינא ש\u0003מחזירה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מדוע לא יחזירנה? ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי את ה\u0003מצוה דרמיא רחמנא עליה\u0004 \u0005[שהטילה התורה עליו]\u0006 — הלא \u0003עבדה\u0004 \u0005[עשה אותה],\u0006 ואם כן \u0003השתא תיקום עליה\u0004 \u0005[עכשיו,\u0006 לאחר שגירשה, \u0005תעמוד עליו]\u0006 \u0003באיסור אשת אח\u0004 שלא במקום מצות ייבום ולא יוכל להחזירה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","ושואלים: ובאמת, \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן]\u0006 שינהג בה דין יבמה גם לאחר שכנסה ולא יוכל להחזירה אחר שגירשה? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ולקחה לו לאשה\"\u0004 (שם), לומר: \u0003כיון שלקחה — הרי היא כאשתו לכל דבר,\u0004 ונוהג בה כבכל אשה, ואינה נחשבת עוד כאשת אחיו.","עוד שנינו במשנה: \u0003ובלבד שתהא כתובתה\u0004 על נכסי בעלה הראשון. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 \u0003אשה הקנו לו מן השמים.\u0004 שכיון שלא הוא בחר בה ולא היא בו, הרי אנחנו אומרים שמן השמים נתנו לו את האשה ואת כתובתה משל אחיו ואין נכסיו משתעבדים לכתובתה.","ומעירים: \u0003ואי לית\u0004 \u0005[ואם אין]\u0006 \u0003לה\u0004 כתובה \u0003מן הראשון,\u0004 משום שלראשון לא היו נכסים וממילא אין לכתובתה ערך — \u0003תקינו\u0004 \u0005[תיקנו]\u0006 \u0003לה\u0004 חכמים שתהיה לה כתובה \u0003מ\u0004בעלה ה\u0003שני\u0004 ומהטעם שבכלל תיקנו כתובה: \u0003כדי שלא תהא קלה בעיניו להוציאה,\u0004 שאם יידע שיצטרך לשלם עבור כתובה, יהרהר בכך ולא ימהר לגרשה.","\u0003מצוה בגדול\u0004 שבאחים \u0003לייבם\u0004 את האלמנה. \u0003לא רצה\u0004 הגדול לייבם — \u0003מהלכין\u0004 ופונים \u0003על כל האחין\u0004 שייבמו. \u0003לא רצו — חוזרין אצל הגדול, ואומרים לו: עליך מצוה: או חלוץ או ייבם.\u0004","אם \u0003תלה\u0004 האח הגדול \u0003ב\u0004אחיו ה\u0003קטן עד שיגדיל,\u0004 כלומר, שאומר להמתין עד שאחיו הקטן יגדל, ואולי הוא ייבם אותה, \u0003או\u0004 שהיה אחד האחים תולה \u0003ב\u0004אח \u0003גדול עד שיבא ממדינת הים, או\u0004 שהיה אחד האחים \u0003חרש או שוטה\u0004 והאחר דורש להמתין עד שיתרפא ואולי ירצה לייבמה — \u0003אין שומעין לו אלא אומרים לו: עליך מצוה, או חלוץ או ייבם.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה הבאה: \u0003ביאת קטן,\u0004 כלומר שיש אח צעיר יותר המוכן לייבם, \u0003וחליצת גדול,\u0004 שהמבוגר יותר אינו מוכן לייבמה, אלא לחלוץ לה — \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה ר' יוחנן ור' יהושע בן לוי\u0004 בשאלה מה עדיף, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: ביאת קטן עדיפא\u0004 \u0005[עדיפה]\u0006 על חליצה של גדול, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: חליצת גדול עדיפא.\u0004","ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003ביאת קטן עדיפא\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מצוה בייבום\u0004 תחילה. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 ש\u0003חליצת גדול עדיפא,\u0004 טעמו: \u0003במקום\u0004 שנמצא \u0003גדול — ביאת קטן לאו\u0004 \u0005[לא]\u0006 \u0003כלום היא.\u0004 ומנסים להביא ראיות לדברים.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003לא רצה\u0004 הגדול לייבם — \u0003מחזירין על כל האחין. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003לא רצה לייבם אלא לחלוץ, וקתני\u0004 \u0005[ושנה]:\u0006 \u0003מהלכין אצל האחין, שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003ביאת קטן עדיפא\u0004 על חליצת הגדול!","ומשיבים: \u0003לא,\u0004 הכוונה היא \u0003לא רצה לחלוץ ולא לייבם,\u0004 שלא רצה לעסוק כלל בדבר. ושואלים: אם כן, \u0003דכוותה\u0004 \u0005[כיוצא בזה]\u0006 \u0003גבי האחין \"לא רצו\" —\u0004 יהיה כוונתו גם כן שלא רצו \u0003לא לחלוץ ולא לייבם,\u0004 אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חוזרים אצל הגדול למיכפייה\u0004 \u0005[לכפותו]?\u0006 שהרי אינו רוצה גם לחלוץ, \u0003לכפייה לדידהו\u0004 \u0005[שנכפה אותם]\u0006 שיחלצו, ומדוע טורחים וחוזרים אליו לכפות אותו? ומשיבים: \u0003כיון\u0004 שלכתחילה \u0003מצוה\u0004 זו \u0003עליה דידיה רמיא\u0004 \u0005[עליו מוטלת] —\u0006 \u0003לדידיה כייפינן\u0004 \u0005[אותו אנו כופים].\u0006","ומנסים להביא ראיה אחרת, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003תלה בקטן עד שיגדיל — אין שומעין לו. ואי\u0004 \u0005[ואם]\u0006 \u0003ביאת קטן\u0004 (האח הצעיר) \u0003עדיפא, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין שומעין לו? נינטר דלמא גדיל ומייבם\u0004 \u0005[נמתין שמא יגדל וייבם]!\u0006","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 הרי שנינו שם גם שאם תלה \u0003בגדול עד שיבא ממדינת הים — אין שומעין לו,\u0004 ולפי זה \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נינטר דלמא אתי וחליץ\u0004 \u0005[נמתין שמא יבוא\u0006 האח הגדול \u0005ויחלוץ]\u0006 או ייבם, ומדוע מכריחים את האח הנשאר שיעשה בה מעשה? \u0003אלא\u0004 יש לומר \u0003כל שהויי\u0004 \u0005[השהיית]\u0006 \u0003מצוה לא משהינן\u0004 \u0005[איננו משהים],\u0006 אלא כיון שמוטלת המצוה עליו, יש לעשותה ולא לדחותה לאחר זמן, ואם כן זהו הטעם שאין ממתינים לקטן עד שיגדל ואין להוכיח מכאן לענין עדיפות חליצה."],["\u0003אית דאמרי\u0004 \u0005[יש שאומרים]\u0006 ומוסרים את המחלוקת הזו בנוסח אחר: \u0003בביאה כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003ביאת קטן עדיפא\u0004 על פני חליצה של גדול. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בחליצת קטן.\u0004","\u0003והכי איתמר\u0004 \u0005[וכך נאמר]:\u0006 \u0003חליצת קטן וחליצת גדול, פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה ר' יוחנן ור' יהושע בן לוי. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: חליצת גדול עדיפא, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כי הדדי נינהו\u0004 \u0005[זה כמו זה הם].\u0006","ומסבירים, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003חליצת גדול עדיפא\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003המצוה בגדול. ואידך\u0004 \u0005[והאחר]\u0006 — לדעתו \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 ש\u0003מצוה בגדול —\u0004 הרי זה דווקא \u0003לענין יבום, אבל לענין חליצה — כהדדי נינהו\u0004 \u0005[זה כמו זה הם].\u0006","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003לא רצו\u0004 האחים האחרים — \u0003חוזרין אצל גדול. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003לא רצו לייבם, אלא\u0004 רצו \u0003לחלוץ. וקתני\u0004 \u0005[ושנה]\u0006 במשנה: \u0003חוזרין אצל גדול, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003חליצת גדול עדיפא!\u0004","ודוחים: \u0003לא, \"לא רצו\"\u0004 כוונתו — \u0003לא לחלוץ ולא לייבם.\u0004 ושואלים: אם כן, \u0003דכוותיה\u0004 \u0005[כיוצא בו]\u0006 \u0003גבי גדול\u0004 צריך לומר שהכוונה היא ש\u0003לא רצה\u0004 מתחילה \u0003לא לחלוץ ולא לייבם, אלא\u0004 אם כך — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חוזרין אצל גדול\u0004 לבסוף — \u0003למכפייה\u0004 \u0005[לכפותו]?\u0006 \u0003לכפייהו לדידהו\u0004 \u0005[שנכפה אותם]!\u0006 ומשיבים: \u0003כיון\u0004 שה\u0003מצוה עליה דידיה רמיא\u0004 \u0005[עליו מוטלת],\u0006 \u0003לדידיה כייפינן\u0004 \u0005[אותו אנו כופים].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה ממשנתנו: \u0003תלה בגדול עד שיבא ממדינת הים — אין שומעין לו. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003חליצת גדול עדיפא, אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003אין שומעין לו? נינטר דלמא אתי וחליץ\u0004 \u0005[נמתין שמא יבוא ויחלוץ]!\u0006","ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 אף מה ששנינו שאם תולה \u0003בקטן עד שיגדיל\u0004, שהדין הוא ש\u0003אין שומעין לו\u0004 — \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נינטר דלמא גדיל ומייבם\u0004 \u0005[נמתין שמא יגדל וייבם]\u0006 אותה. \u0003אי נמי אתי איהו ומייבמה\u0004 \u0005[או\u0006 שמא \u0005יבוא גם הוא,\u0006 הגדול, ממדינת הים \u0005וייבם אותה].\u0006 \u0003אלא\u0004 על כרחך צריך לומר כי הטעם הוא: \u0003כל שהויי\u0004 \u0005[השהיית]\u0006 \u0003מצוה לא שהינן\u0004 \u0005[אין אנו משהים],\u0006 שכיון שמוטלת המצוה עליו, יש לעשותה מיד ולא לדחותה לאחר זמן, ולכן אין מכאן ראיה.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה אחרת: \u0003מצות יבום קודמת למצות חליצה.\u0004 מתי — \u0003בראשונה, שהיו מתכוונין\u0004 לעשות את הייבום \u0003לשם מצוה,\u0004 אולם \u0003עכשיו שאין מתכוונין לשם מצוה, אמרו: מצות חליצה קודמת למצות יבום.\u0004","\u0003אמר רב:\u0004 אף על פי כן, \u0003אין כופין\u0004 לחלוץ, אלא אם רוצה מייבם. ומספרים: \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים\u0006 יבם ויבמה \u0005לפני]\u0006 \u0003רב, אמר להו\u0004 \u0005[\u0006היה \u0005אומר להם]:\u0006 \u0003אי בעית\u0004 \u0005[אם רצונך] —\u0006 \u0003חלוץ, אי בעית\u0004 \u0005[אם רצונך] —\u0006 \u0003ייבם\u0004 כי \u0003בדידך\u0004 \u0005[ב\u0006רצון \u0005שלך]\u0006 \u0003תלא רחמנא\u0004 \u0005[תלה הכתוב],\u0006 שנאמר: \u0003\"ואם לא יחפץ האיש\"\u0004 (דברים כה, ז), ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אם חפץ, אי בעי\u0004 \u0005[אם רוצה] —\u0006 \u0003חליץ\u0004 \u0005[חולץ],\u0006 \u0003אי בעי\u0004 \u0005[אם רוצה] —\u0006 \u0003ייבם\u0004 \u0005[מייבם].\u0006","ומעירים: \u0003ואף רב יהודה סבר אין כופין.\u0004 וזאת יודעים אנו \u0003מדאתקין\u0004 \u0005[מ\u0006מה \u0005שהתקין]\u0006 \u0003רב יהודה בגיטא דחליצה\u0004 \u0005[בשטר החליצה],\u0006 שהיו כותבים בבית דינו כך: \u0003איך פלונית בת פלוני אקרבת ית\u0004 \u0005[הקריבה את]\u0006 \u0003פלוני יבמה קדמנא לבי דינא\u0004 \u0005[לפנינו לבית הדין],\u0006 \u0003ואשתמודעינהו דאחוה דמיתנא מאבא ניהו\u0004 \u0005[והכרנוהו שאחי המת מן האב הוא],\u0006 \u0003ואמרי ליה\u0004 \u0005[ואמרנו לו]:\u0006 \u0003אי צבית\u0004 \u0005[אם רצונך]\u0006 \u0003ליבם — יבם, ואי\u0004 \u0005[ואם]\u0006 \u0003לא — איטלע לה רגליך דימינא\u0004 \u0005[הושט לה\u0006 את \u0005רגלך הימנית].\u0006","\u0003ואיטלע לה רגלא דימינא\u0004 \u0005[והושיט לה\u0006 את \u0005רגלו הימנית]\u0006 \u0003ושרת סיניה מעל רגלוהי\u0004 \u0005[והסירה את נעלו מעל רגלו]\u0006 \u0003וירקת באנפוהי רוקא דמתחזיא לבי דינא על ארעא\u0004 \u0005[וירקה בפניו רוק הנראה לבית דין על הארץ]\u0006.","\u0003ור' חייא בר אויא מסיים בה משמיה\u0004 \u0005[היה מסיים\u0006 בשטר חליצה בנוסח זה \u0005משמו]\u0006 של \u0003רב יהודה\u0004 עוד משפט אחד: \u0003ואקרינהו\u0004 \u0005[והקראנו אותם]\u0006 שיאמרו \u0003מה דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בספר אורייתא דמשה\u0004 \u0005[בספר תורת משה],\u0006 את הדברים שצריכים היבם והיבמה להגיד.","מכיון שהוזכר שבנוסח שטר החליצה כתוב כי \u0003אשתמודעינהו\u0004 \u0005[הכרנוהו],\u0006 מביאים שאכן \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הכרה זו היא דווקא \u0003בעדים\u0004 שיבואו ויאמרו שהוא באמת אחי המת, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אין צריך לשם כך עדים כשרים, אלא \u0003אפילו קרוב, אפילו אשה\u0004 נאמנים להעיד על כך. ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה]\u0006 היא שאין זו עדות ממש, אלא \u0003גלויי מילתא בעלמא\u0004 \u0005[גילוי דבר בלבד]\u0006 \u0003הוא, ואפילו קרוב ואפילו אשה\u0004 כשרים לעדות זו.","שנינו במשנה ש\u0003בראשונה שהיו מתכוונין לשם מצוה — מצות יבום קודמת למצות חליצה, ועכשיו שאין מתכוונין לשם מצוה, אמרו: מצות חליצה קודמת למצות יבום.\u0004","\u0003אמר רמי בר חמא אמר ר' יצחק: חזרו לומר\u0004 אחר כך ש\u0003מצות יבום קודמת למצות חליצה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק\u0004 בתמיהה: וכי \u0003אכשור דרי\u0004 \u0005[הוכשרו הדורות],\u0006 וכי נעשו בני אדם כשרים יותר במשך הדורות, שבטוחים אנו שכולם מייבמים לשם מצוה?","ומשיבים: \u0003מעיקרא סברי לה\u0004 \u0005[מתחילה היו סבורים]\u0006 \u0003כ\u0004דעת \u0003אבא שאול,\u0004 ולכן הקדימו מצות חליצה, \u0003ולבסוף סברי לה כרבנן\u0004 \u0005[סברו כ\u0006דעת \u0005חכמים].\u0006","וביאור השיטות: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אבא שאול אומר: הכונס\u0004 (הנושא) \u0003את יבמתו לשם נוי\u0004 משום שהיא יפה, או \u0003לשום\u0004 (לשם) \u0003אישות,\u0004 מפני שהוא רוצה באשה, \u0003ולשום דבר אחר\u0004 כגון לשם ממון שבידה — \u0003כאילו פוגע בערוה.\u0004 שהרי אשת אח אסורה בעצם, ולא הותרה אלא לשם מצוה. \u0003וקרוב אני בעיני להיות הולד\u0004 הנולד מייבום שלא לשם מצוה, \u0003ממזר. וחכמים אומרים:\u0004 נאמר: \u0003\"יבמה יבא עליה\"\u0004 (דברים כה, ה), וכוונתו: \u0003מכל מקום.\u0004 כלומר, גם אם לא נתכוון למצוה, כיון שאמרה התורה לעשות זאת, מצוה יש בכך.","ומעירים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את זו ששנו חכמים]\u0006 בברייתא: מן הפסוק \u0003\"יבמה יבא עליה\"\u0004 (דברים כה, ה) למדים כי \u0003מצוה\u0004 בייבום יותר מבחליצה! מדוע צריך לומר שהיא מצוה — \u0003שבתחלה\u0004 לפני שנישאה לאחיו \u0003היתה עליו בכלל היתר\u0004 ככל הנשים, ולאחר מכן \u0003נאסרה\u0004 עליו בנישואיה לאחיו, \u0003וחזרה והותרה\u0004 עם פטירת אחיו בלא זרע, \u0003יכול תחזור להתירה הראשון — תלמוד לומר: \"יבמה יבא עליה\" — מצוה.\u0004","\u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 ששנה ברייתא זו? \u0003אמר ר' יצחק בר אבדימי: אבא שאול היא. והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין את הדבר: \u0003\"יבמה יבא עליה\" — מצוה.\u0004 משמע \u0003שבתחלה\u0004 לפני נישואיה \u0003היתה עליו\u0004 אשה זו \u0003בכלל היתר\u0004 ככל הנשים, \u0003רצה לשם נוי — כונסה, רצה לשם אישות — כונסה,\u0004 והכל מותר.","ולאחר מכן \u0003נאסרה\u0004 עליו בנישואיה לאחיו, \u0003חזרה והותרה\u0004 על ידי מות אחיו בלא בנים, \u0003יכול תחזור להתירה הראשון\u0004 לחלוטין — \u0003תלמוד לומר: \"יבמה יבא עליה\",\u0004 וכוונתו: \u0003למצוה\u0004 בלבד, ולכן אם אין כוונתו למצוה — איננה מותרת.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שברייתא זו כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006, כך צריך להבינה: \u0003\"יבמה יבא עליה\" — מצוה. שבתחלה היתה\u0004 עליו \u0003בכלל היתר,\u0004 וכוונתו: \u0003רצה — כונסה, רצה — אינו כונסה.\u0004","\u0003נאסרה, חזרה והותרה. יכול תחזור להתירה הראשון,\u0004 כלומר, שאם \u0003רצה — כונסה, רצה — אינו כונסה.\u0004 ועוד טרם סיום הענין, תוהים: כיצד אפשר לומר \u0003רצה אינו כונסה?\u0004","\u0003הא אגידא ביה\u0004 \u0005[הרי\u0006 היא \u0005קשורה בו]\u0006 בזיקת ייבום שקבעה התורה, וכי \u0003בכדי תיפוק\u0004 \u0005[לריק תצא]\u0006 בלי חליצה? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון כך: \u0003רצה — כונסה, רצה — חולץ לה\u0004 — \u0003תלמוד לומר: \"יבמה יבא עליה\" — מצוה.\u0004 כלומר, מצוה היא שייבם אותה, וכדעת חכמים שמצות ייבום קודמת ועדיפה.","ומעירים, כדי לברר את משמעותה של ברייתא זו: \u0003אימא רישא\u0004 \u0005[אמור\u0006 את \u0005ראשה,\u0006 תחילתה\u0005]\u0006 של ברייתא זו, כי בחלקה הראשון היא דנה בנושא אחר, מה שנאמר במנחה הנאכלת לכהנים \u0003\"מצות תאכל במקום קדש\"\u0004 (ויקרא ו, ט) — הרי זו \u0003מצוה.\u0004"],["\u0003שבתחלה\u0004 קודם שהוקדשה סולת זו \u0003היתה עליו בכלל היתר, נאסרה\u0004 לכל עם הקדשתה, \u0003וחזרה והותרה\u0004 כאשר הקטירו ממנה את הקומץ, \u0003יכול תחזור להיתירה הראשון\u0004 לכל דבר — \u0003תלמוד לומר: \"מצות תאכל במקום קדש\"\u0004 (ויקרא ו, ט) — \u0003מצוה.\u0004","ומעתה נברר, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא\u0004 ש\u0003אמר\u0004 כי \u0003הא מני רבנן\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כ\u0005מי\u0006 כדעת \u0005חכמים]\u0006 \u0003היא\u0004 לענין ייבום — \u0003הכא, הכי קאמר\u0004 \u0005[כאן,\u0006 בענין המנחה, \u0005כך אמר]:\u0006 \u0003\"מצות תאכל במקום קדש\" — מצוה, שבתחלה היתה עליו בכלל היתר,\u0004 כיצד? \u0003רצה — אוכלה, רצה — אינו אוכלה, נאסרה\u0004 בהקדשתה, ולאחר מכן \u0003חזרה והותרה\u0004 על ידי הקומץ, \u0003יכול תחזור להיתירה הראשון,\u0004 שאם \u0003רצה — אוכלה, רצה — אינו אוכלה.\u0004","ותוהים על אפשרות זו: \u0003רצה אינו אוכלה?!\u0004 הלא ודאי מצוה לאוכלה, \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואכלו אתם אשר כפר בהם\"\u0004 (שמות כט, לג), \u0003מלמד שהכהנים אוכלים ובעלים מתכפרין,\u0004 משמע שאכילת הכהנים היא חלק ממצוות הקרבן!","\u0003אלא,\u0004 הכוונה היא כך: \u0003רצה — הוא,\u0004 הכהן המקריב את המנחה, \u0003אוכלה, רצה — כהן אחר אוכלה\u0004 — \u0003תלמוד לומר: \"מצות תאכל במקום קדש\" — מצוה\u0004 על הכהן שהקריבה לאכול אותה.","\u0003אלא, ל\u0004דעת \u0003רב יצחק בר אבדימי,\u0004 ש\u0003אמר\u0004 שברייתא זו כדעת \u0003אבא שאול היא,\u0004 שלענין ייבום אין הדיון לגבי עצם חובת המעשה, אלא ביחס לאופן שבו הוא עושה אותו, \u0003הכא מאי תרי גווני איכא\u0004 \u0005[כאן מה\u0006 איזה \u0005שני אופנים יש]?\u0006 הרי בענין המנחה גם אם אינו מכוון לשם מצוה אינו עובר בכך!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאפשר לפרש בדרך דומה: \u0003רצה\u0004 לאוכלה \u0003לתאבון,\u0004 כדרך אכילה רגילה — \u0003אוכלה, רצה\u0004 לאוכלה \u0003אכילה גסה\u0004 (שאדם שבע ביותר וכופה עצמו לאכול) — \u0003אוכלה,\u0004 שגם היא בכלל אכילה — אולם \u0003אכילה גסה מי\u0004 \u0005[האם]\u0006 \u0003שמה אכילה,\u0004 האם היא נחשבת בכלל אכילה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש: האוכל אכילה גסה ביום הכפורים — פטור מ\u0004ביטול \u0003\"לא תענה\"\u0004 (\"כי כל הנפש אשר לא תעונה בעצם היום הזה ונכרתה מעמיה\". ויקרא כג, כט), שאכילה גסה אינה נחשבת אכילה אלא אף היא בכלל עינוי, ואם כן, אי אפשר להעלות על הדעת שיאכל המנחה אכילה גסה!","\u0003אלא\u0004 תפרש באופן אחר: \u0003רצה — מצה אוכלה,\u0004 את המנחה, \u0003רצה — חמץ אוכלה.\u0004","אולם גם זה בלתי אפשרי, \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא תאפה חמץ חלקם\"\u0004 (ויקרא ו, י), \u0003ואמר ריש לקיש,\u0004 כוונתו: \u0003ואפילו חלקם\u0004 של הכהנים \u0003לא תאפה חמץ,\u0004 שלא רק להקריב על המזבח מנחת חמץ אסור, אלא אף חלק הכהנים אסור שייעשה חמץ! \u0003אלא\u0004 לומר כך: \u0003רצה — מצה אוכלה, רצה — חלוט אוכלה,\u0004 שמבשל אותה במים.","ושואלים: \u0003האי חלוט היכי דמי\u0004 \u0005[חלוט זה כיצד הוא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מצה היא,\u0004 שעדיין לא החמיצה הסולת — אם כן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מצה היא, ואי\u0004 \u0005[ואם]\u0006 \u0003לא מצה היא,\u0004 אלא החמיץ אותה בחליטה — הלא \u0003\"מצות\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ואסור לעשותה חמץ!","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 ש\u0003מצה היא,\u0004 גם לאחר חליטה, \u0003ולהכי תנא ביה קרא\u0004 \u0005[ולכך שנה\u0006 חזר \u0005בה הכתוב] —\u0006 \u0003לעכב.\u0004 כלומר, שאף שחליטה זו אינה עושה חמץ, ומבחינה זו מותר, מכל מקום חזר הכתוב לומר \"מצות תאכל\", לומר דווקא מצה גמורה ולא מצה שנחלטה.","ושואלים: אם כן, \u0003אלא חלוט מצה היא דקאמרינן\u0004 \u0005[שאנו אומרים],\u0006 \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו, \u0005הלכה]\u0006 נאמר הדבר? שהרי לענין מנחות חלוט אינו נחשב מצה! ומשיבים: \u0003לומר שאדם יוצא בה ידי חובתו בפסח,\u0004 שלענין מצות בפסח אין החליטה מבטלת את המצה מהיות מצה, שכן \u0003אף על פי דחלטיה מעיקרא\u0004 \u0005[שחלטו\u0006 את הסולת \u0005מתחילה],\u0006 \u0003כיון דהדר אפייה\u0004 \u0005[שחזר\u0006 ו\u0005אפה אותה]\u0006 \u0003בתנור — \"לחם עוני\" קרינא ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003ואדם יוצא בה ידי חובתו בפסח,\u0004 ואין אומרים שזו איננה מצה. ולפי הסבר זה אפשר לפרש את הברייתא כולה גם כדעת אבא שאול.","\u0003החולץ ליבמתו — הרי הוא כאחד מן האחין לנחלה\u0004 של האח המת ואין לו זכות בנכסים אלה יותר מלשאר אחיו, אף שהם לא עשו בה דבר. \u0003ואם יש שם אב\u0004 שחי עדיין — \u0003נכסים\u0004 של האח שמת בלא ילדים הרי הם \u0003של אב,\u0004 ואין האחים זוכים בהם עכשיו, אלא רק לאחר מותו של האב. \u0003הכונס את יבמתו — זכה בנכסים של אחיו\u0004 המת. \u0003ר' יהודה אומר: בין כך ובין כך,\u0004 בין שייבם בין שחלץ, \u0003אם יש שם אב — נכסים של אב.\u0004","על ההלכה במשנה שהחולץ ליבמתו הרי הוא כאחד מן האחים, שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003חליצה במקום יבום קיימא\u0004 \u0005[עומדת]\u0006 ומשום כך הרי הוא כמייבם, \u0003ונשקול כולהו נכסי\u0004 \u0005[ויקח את כל הנכסים]\u0006 של אחיו המת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, לשון המשנה איננה מדוייקת, שבמקום \u0003\"הרי הוא כאחד מן האחים\u0004 לנחלה \u0003\", \"אינו אלא כאחד מן האחים\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי באה ההלכה למעט, שאין לו חלק יתר מהם!","\u0003אלא\u0004 כך צריך לומר: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל ואפסדה\u0004 \u0005[והפסידה,\u0006 מנע אותה\u0005]\u0006 \u0003מ\u0004מצות \u0003יבום,\u0004 אם כן \u0003לקנסיה\u0004 \u0005[נקנוס אותו],\u0006 שכיון שחלץ ולא ייבם, לא תהיה לו כל זכות בנכסי האח המת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זה כך, אלא הוא נשאר שווה לשאר האחים בירושת האח המת.","שנינו במשנה ש \u0003אם יש שם אב\u0004 — הנכסים של אב. ומסבירים: ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בדיני ירושות: בכל מקום שאין למת צאצאים, ה\u0003אב\u0004 (של המת) \u0003קודם לכל יוצאי ירכו,\u0004 שהראשון ליורשים הוא האב, ושאר היורשים נחשבים רק כבאים מכוחו של האב (כגון אחים).","שנינו במשנה ש \u0003הכונס את יבמתו\u0004 זכה בנכסי אחיו המת. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003\"יקום על שם אחיו\"\u0004 (דברים כה, ו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003והרי קם,\u0004 וכיון שהוא עומד במקומו ונושא את אשתו, הריהו עומד במקומו גם לענין בעלות על נכסיו.","עוד שנינו במשנה: \u0003ר' יהודה אומר\u0004 שאף המייבם אין לו זכות בנכסי אחיו המת כאשר אביהם חי. \u0003אמר עולא: הלכה כר' יהודה. וכן אמר ר' יצחק נפחא: הלכה כר' יהודה.\u0004","\u0003ואמר עולא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק נפחא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה הבכור אשר תלד\u0004 יקום על שם אחיו\u0003\"\u0004 (דברים כה, ו), לומר: היבם דינו \u0003כבכור, מה בכור אין לו\u0004 חלק יתר \u0003בחיי האב,\u0004 אלא רק אחרי מותו מקבל פי שניים, \u0003אף האי נמי\u0004 \u0005[זה,\u0006 היבם, \u0005גם כן]\u0006 \u0003אין לו\u0004 חלק \u0003בחיי האב.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כן, אמור כך: \u0003מה בכור נוטל פי שנים\u0004 על כל פנים \u0003לאחר מיתת האב — אף האי\u0004 \u0005[זה],\u0006 היבם, \u0003נוטל פי שנים לאחר מיתת האב!\u0004","ודוחים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"יקום על שם אביו\" כתיב\u0004 \u0005[נאמר]?\u0006 הלא \u0003\"יקום על שם אחיו\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003ולא \"על שם אביו\".\u0004","ושואלים: אם כן, \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003היכא דליכא\u0004 \u0005[היכן,\u0006 במקום, \u0005שאין]\u0006 ה\u0003אב\u0004 חי עוד, \u0003דלשקול\u0004 \u0005[ש\u0006יכול אז \u0005לקבל]\u0006 את ה\u0003נחלה — תתקיים\u0004 גם \u0003מצות יבום,\u0004 אולם \u0003היכא דאיכא\u0004 \u0005[היכן,\u0006 במקום, \u0005שיש]\u0006 \u0003אב דלא שקיל\u0004 \u0005[שאין\u0006 היבם \u0005מקבל]\u0006 את ה\u0003נחלה\u0004 של אחיו \u0005—\u0006 \u0003לא תתקיים מצות יבום.\u0004 שכיון שאינו קם תחת אחיו לירושה, לא יקום תחתיו גם לנשואין!","ומשיבים: \u0003מידי\u0004 \u0005[וכי]\u0006 ה\u0003יבום בנחלה תלה רחמנא\u0004 \u0005[תלתה התורה],\u0006 לומר שחובת הייבום תלויה בנחלה? אלא כך אמרה תורה: \u0003יבומי מיבמי\u0004 \u0005[מייבם הוא]\u0006 \u0003ואי איכא\u0004 \u0005[ואם יש]\u0006 \u0003נחלה — שקולי\u0004 \u0005[\u0006הוא \u0005מקבל],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא שקיל\u0004 \u0005[אינו מקבל].\u0006","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' חנינא קרא\u0004 (מלמד מקרא) \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ינאי, ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003הלכה כר' יהודה. אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: \u0003פוק קרי קרייך לברא\u0004 \u0005[צא וקרא את מקראך בחוץ],\u0006 שכיון שהיה מלמד מקרא, אמר לו בלשון זו, כלומר, דבריך דחויים הם ו\u0003אין הלכה כר' יהודה.\u0004","וכן \u0003תני\u0004 \u0005[שנה]\u0006 ה\u0003תנא,\u0004 חוזר המשניות, \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' נחמן: אין הלכה כר' יהודה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אלא כמאן\u0004 \u0005[כמי],\u0006 \u0003כרבנן\u0004 \u0005[כחכמים]?\u0006 \u0003—\u0004 דבר זה \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, שהרי \u0003יחיד ורבים — הלכה כרבים!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו תנא: \u0003אסמייה\u0004 \u0005[\u0006האם \u0005אמחק אותה]\u0006 את הפסיקה הזאת, מן הברייתות שאני חוזר עליהן, ואומר כי טעות היא?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003לא,\u0004 אל תמחק, כי אף שאין הדבר נחוץ, נכון הוא, וכך אירע שיבוש זה: \u0003את\u0004 \u0005[אתה]\u0006 כאשר למדת, הרי מי שלימד אותך — \u0003הלכה\u0004 כר' יהודה \u0003אתנייך\u0004 \u0005[למד אותך],\u0006 \u0003ומוקשה הוא דאקשי לך\u0004 \u0005[ולך היה קשה]\u0006 איך זה פוסקים כיחיד במקום רבים? \u0003ואפכת\u0004 \u0005[ו\u0006אתה \u0005הפכתה]\u0006 ותיקנת את הגירסה, שאין הלכה כמותו. \u0003ולמאי דאפכת, שפיר אפכת\u0004 \u0005[ו\u0006לפי \u0005מה שהפכתה, יפה הפכתה]\u0006 שכיוונת להלכה. אבל באמת היתה קיימת ברייתא כזו, שבה נפסקה הלכה בנושא זה, ואתה רק שינית את הנוסח שלה. ולענין הלכה ברור מכאן כי גם רב נחמן סבור שאין הלכה כר' יהודה.","\u0003החולץ ליבמתו — הוא אסור בקרובותיה\u0004 כאילו היתה אשתו, \u0003ו\u0004כן \u0003היא אסורה בקרוביו —\u0004 כאילו היתה נשואה לו בעבר ונתגרשה."],["\u0003הוא אסור באמה, ובאם אמה, ובאם אביה, ובבתה, ובבת בתה, ובבת בנה, ובאחותה בזמן שהיא\u0004 (היבמה) \u0003קיימת\u0004 (חיה). \u0003והאחין\u0004 של החולץ \u0003מותרין\u0004 בכולן.","\u0003והיא אסורה באביו, ובאבי אביו, ובבנו, ובבן בנו, באחיו, ובבן אחיו.\u0004","ועוד הלכה בענין זה: \u0003מותר אדם בקרובת צרת חלוצתו,\u0004 אף שהחולץ לאשה אסור גם בצרתה, מכל מקום צרה זו אינה נחשבת כקרובתו, ורשאי לשאת את קרובותיה של הצרה. \u0003ו\u0004אולם \u0003אסור בצרת קרובת חלוצתו,\u0004 שאם חלץ לאשה ואחת מקרובותיה (כגון אחותה) היתה נשואה לאדם אחר, והיתה לה צרה — אם מת הבעל, לא רק שאסור בקרובת חלוצתו אלא אסור גם בצרתה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: האם \u0003גזרו שניות\u0004 גם \u0003בחלוצה?\u0004 שנאסרו לא רק קרובות האסורות מן התורה כקרובות אשתו, אלא שגם שניות לעריות, שהן מדברי סופרים, אסורות בחלוצה, \u0003או לא\u0004 נאסרו שניות?","וצדדי השאלה: האם נאמר כי \u0003בערוה\u0004 עצמה שאיסורה \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 \u0003שניות,\u0004 ואילו \u0003בחלוצה\u0004 שאינה אסורה מן התורה, \u0003לא גזרו רבנן\u0004 \u0005[חכמים]\u0006 ב\u0003שניות\u0004 שלה, \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 שכיון שאסרו עליו אשה וקבעו שתהיה לו כערוה — לא חילקו בדבר.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנתנו: \u0003הוא אסור באמה ובאם אמה, ואילו \"אם אם אמה\"\u0004 שהיא שניה — \u0003לא קתני\u0004 \u0005[שנה],\u0006 משמע שלא גזרו שניות!","ומשיבים: \u0003דלמא היינו טעמא\u0004 \u0005[שמא זהו הטעם]\u0006 ש\u0003לא תני\u0004 \u0005[שנה],\u0006 לא מפני שהיא מותרת, אלא \u0003משום דקבעי למיתני סיפא\u0004 \u0005[שרצה לשנות\u0006 ב\u0005סופה]\u0006 של אותה פיסקה \u0003\"והאחין מותרין\", ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 \u0003\"אם אם אמה\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 ומפרש: ש\u0003האחין מותרין —\u0004 כוונתו \u0003דוקא באם אם אמה,\u0004 שלא גזרו שניה לגבי האחים, \u0003אבל באם אמה ובאמה\u0004 שהן קרובותיה מן התורה — \u0003לא\u0004 הותרו האחים, ולכן לא שנה במשנה אם אם אימה.","ומקשים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"אם אם אמה\", וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"האחין מותרין בכולן\",\u0004 ואז לא היה שום מקום לספק! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר, אבל אין לנו הוכחה גמורה מכאן.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו עוד במשנתנו: \u0003היא אסורה באביו ובאבי אביו. קתני מיהא\u0004 \u0005[שנו על כל פנים]\u0006 שאסורה ב\u0003אבי אביו, מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 שאסורה באבי אביו \u0003משום\u0004 שהיא נחשבת כאילו היתה אשתו של ה\u0003חולץ\u0004 ולגבי אבי האב \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 נחשבת כ\u0003כלת בנו,\u0004 ואינה אסורה עליו אלא משום שניה!","ודוחים: \u0003לא,\u0004 אמנם היא אסורה משום שניה, אולם איסור זה אינו מחמת החולץ אלא \u0003משום מיתנא\u0004 \u0005[המת],\u0006 שהרי אותו אדם היה גם אבי אביו של בעלה המת, \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003כלת בנו\u0004 ממש.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו עוד, שהיא אסורה \u0003בבן בנו\u0004 של החולץ, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שהיא קרובתו של \u0003חולץ, דהויא לה\u0004 \u0005[שהרי היא]\u0006 אסורה עליו \u0003משום\u0004 שהיא \u0003אשת אבי אביו\u0004 ואשת אבי האב הלא היא שניה!","ודוחים: \u0003לא,\u0004 אמנם היא אסורה משום שניה, אבל \u0003משום מיתנא\u0004 \u0005[המת]\u0006 עצמו \u0003והויא לה\u0004 \u0005[והרי היא]\u0006 \u0003אשת אחי אבי אביו,\u0004 מכיון שהיתה נשואה בשעתו לאח שמת, הריהי אסורה משום שניה לנכד אחיו.","ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמימר מכשר\u0004 \u0005[\u0006היה \u0005מכשיר]\u0006 \u0003באשת אחי אבי אביו\u0004 ואין כאן איסור שניה כלל!","ומשיבים: \u0003אמימר מוקי לה בבר ברא דסבא\u0004 \u0005[מעמיד,\u0006 מפרש \u0005אותה בבן בנו של הזקן],\u0006 כלומר, \"בן בנו\" אינו בן בנו של החולץ, אלא מתייחס לאביו, המוזכר קודם במשנה, והכוונה היא לבן בנו של אביו של המת שהיא אסורה עליהם מהתורה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שזו הכוונה, \u0003היינו\u0004 \u0005[הרי הוא]\u0006 \u0003אחיו ובן אחיו,\u0004 ולמה חוזר התנא ואומר גם אחיו ובן אחיו, וגם בנו ובן בנו? ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003אחיו מן האב וקתני\u0004 \u0005[ושנה]\u0006 גם \u0003אחיו מן האם.\u0004 שאחיו ובן אחיו הריהם בין מן האב ובין מן האם, ובנו ובן בנו מייחסים לזקן (אביו של החולץ) שהם אחים ובני אחים מן האב דווקא.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: ארבע\u0004 אנשים אסורים בחלוצה \u0003מדברי תורה, וארבע\u0004 אסורים \u0003מדברי סופרים: אב ובנו\u0004 של החולץ, \u0003אחיו, ובן אחיו\u0004 של בעלה המת — אסורים בה \u0003מדברי תורה, אבי אביו, ואבי אמו, בן בנו, ובן בתו — אסורים\u0004","\u0003מדברי סופרים, קתני מיהא\u0004 \u0005[שנה על כל פנים]\u0006 \u0003אבי אביו, מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003משום חולץ, ו\u0004אם כן \u0003הויא לה\u0004 \u0005[והרי היא]\u0006 נחשבת כ\u0003כלת בנו,\u0004 ואם כן נמצא שגזרו שניות גם בחלוצה!","ודוחים: \u0003לא, משום מיתנא\u0004 \u0005[המת]\u0006 עצמו, \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003כלת בנו\u0004 ממש, ובנשואין גמורים ודאי אסרו שניות.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שנינו, שאסורה ב\u0003אבי אמו, מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003משום חולץ, דהויא לה\u0004 \u0005[שהרי היא]\u0006 נחשבת כ\u0003כלת בתו\u0004 ונמצא שגזרו שניות בחלוצה!","ודוחים: \u0003לא,\u0004 גם כאן האיסור הוא \u0003משום מיתנא\u0004 \u0005[המת]\u0006 עצמו, \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 ממש \u0003כלת בתו\u0004 של המת.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שאסרוה על \u0003בן בנו. מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003משום חולץ, דהויא לה\u0004 \u0005[שהרי היא]\u0006 נחשבת כ\u0003אשת אבי אביו!\u0004","ודוחים: \u0003לא, משום מיתנא\u0004 \u0005[המת]\u0006 עצמו, \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003אשת אחי אבי אביו,\u0004 שהיא שניה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמימר מכשיר באשת אחי אבי אביו,\u0004 שסבר שאיננה שניה! ומשיבים: \u0003אמימר מוקים לה\u0004 \u0005[מעמיד,\u0006 מפרש \u0005אותה]\u0006 שאסורה \u0003משום חולץ, וקסבר\u0004 \u0005[וסבור]\u0006 ש\u0003גזרו שניות בחלוצה,\u0004 אבל אין מכאן הוכחה גם לדעות האחרות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו עוד שאסורה \u0003בבן בתו, מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003משום חולץ, דהויא לה\u0004 \u0005[שהרי היא]\u0006 נחשבת כ\u0003אשת אבי אמו,\u0004 והיא שניה!","ודוחים: \u0003לא, משום מיתנא\u0004 \u0005[המת]\u0006 עצמו, \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 ממש \u0003אשת אחי אבי אמו.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 אפילו \u0003גבי שניות\u0004 של \u0003ערוה\u0004 ממש \u0003לא גזרו\u0004 לאסור אשת אחי אבי אמו!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום חולץ,\u0004 שהיא אשת אבי אמו, שקירבה זו היא שניה לעריות, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003גזרו שניות בחלוצה?\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהחלוצה נחשבת כאשתו לכל דבר, אפילו לענין איסור שניות.","שנינו במשנה ש\u0003מותר אדם\u0004 בקרובת צרת חלוצתו ואסור בצרת קרובת חלוצתו. \u0003אמר רב טובי בר קיסנא אמר שמואל: הבא על צרת חלוצה — הולד ממזר. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 היא \u0003באיסורה קיימא\u0004 \u0005[עומדת],\u0006 שאין דינה כחלוצה, אלא דנים אותה כאשת אח שלא הותרה כלל, ולכן הוולד הנולד לה הינו ממזר.","\u0003אמר רב יוסף: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]:\u0006 \u0003מותר אדם בקרובת צרת חלוצתו. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003צרה אבראי\u0004 \u0005[מבחוץ],\u0006 כלומר, שהצרה אסורה לו לחלוטין, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מותר באחותה\u0004 שהיא נחשבת כשאר הנשים שאין לו כל קשר אליהן.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003צרה כחלוצה דמיא\u0004 \u0005[נחשבת]\u0006 ולאחר החליצה שוב אינה כאשת אח \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מותר\u0004 בקרובותיה? הלא ראוי שתיאסרנה כמו קרובות החלוצה עצמה! אלא ודאי הצרה אין דינה כאילו היא עצמה נחלצה, ואסורה לו באיסור ערוה ממש.","ושואלים: \u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003ר' יוחנן\u0004 ש\u0003אמר,\u0004 ש\u0003בין הוא,\u0004 החולץ, \u0003בין\u0004 ה\u0003אחין — אין חייבין לא על החלוצה כרת ולא על צרתה כרת.\u0004 והרי מן המשנה מוכח לכאורה שצרת חלוצה אסורה איסור ערוה!","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' יוחנן: ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שאיסור \u0003אחות חלוצה\u0004 הוא איסור \u0003דאורייתא\u0004 \u0005[מן התורה]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש\u0004 שחלק על ר' יוחנן בדין צרה וחלוצה, בנושא אחר: \u0003כאן שנה רבי: אחות גרושה\u0004 אסורה \u0003מדברי תורה, אחות חלוצה —\u0004 אסורה \u0003מדברי סופרים\u0004 בלבד, ואין בה איסור תורה. וכיון שעצם האיסור הוא מדברי סופרים, לא גזרו לאסור גם בצרה.","ושואלים: אם כן, לפי השיטה שאיסור קרובת חלוצה הוא מדברי חכמים בלבד, \u0003מאי שנא האי\u0004 \u0005[מה שונה זו]\u0006 קרובת צרת חלוצה שהיא מותרת, \u0003ומאי שנא האי\u0004 \u0005[ומה שונה זו]\u0006 צרת קרובת חלוצה שהיא אסורה? שלכאורה שתיהן הן נשים שאין לו קירבת משפחה עמהן, ומדוע חילקו בדיניהן?"],["\u0003הך דאזלא בהדה לבי דינא\u0004 \u0005[זו שהולכת איתה לבית הדין],\u0006 כלומר, כיון שכאשר האשה החולצת הולכת לבית הדין מתלווית אליה אחותה, עשוי הרואה לחשוב שאחותה היא זו שחלצה ולכן \u0003גזרו בהו רבנן\u0004 \u0005[בהן חכמים]\u0006 ואסרוהו לישא את צרתה האחות, כדי שלא יבואו הרואים לומר שאת צרת חלוצתו נשא. ואולם \u0003האי דלא אזלא בהדה לבי דינא\u0004 \u0005[זו,\u0006 הצרה, \u0005שאינה הולכת איתה לבית הדין]\u0006 כלומר, הצרה, שלא השתתפה בכל מעשה בית הדין של החליצה, שכאשר חולצת האחת אין צרתה נוכחת בדרך כלל בבית הדין ואין חשש שמא יחשבו הרואים שהצרה היא זו שחלצה ולכך קרובותיה אסורות לו, ולכן \u0003לא גזרו בהו רבנן\u0004 \u0005[בהן חכמים]\u0006 בקרובותיה של הצרה.","\u0003החולץ ליבמתו, ו\u0004אחר כך \u0003נשא אחיו את אחותה, ומת\u0004 אותו אח — האחות \u0003חולצת ולא מתיבמת,\u0004 מפני שהיתה אסורה עליו עוד לפני נישואיה לאחיו משום אחות חלוצתו. \u0003וכן המגרש את אשתו, ונשא אחיו את אחותה ומת —\u0004 אם אין להם אח אחר שיכול לייבמה, \u0003הרי זו פטורה\u0004 מן החליצה ומן הייבום, שהרי היא אחות גרושתו, ואסורה עליו משום ערוה כל עוד גרושתו חיה.","\u0003שומרת יבם\u0004 (ממתינה לייבום), \u0003שקידש אחיו\u0004 של אותו יבם \u0003את אחותה\u0004 — \u0003משום\u0004 (בשם) \u0003ר' יהודה בן בתירא אמרו: אומרים לו\u0004 לאח המקדש: \u0003המתן\u0004 ואל תשא את ארוסתך \u0003עד שיעשה אחיך\u0004 היבם \u0003מעשה,\u0004 שיכנוס או יחלוץ, כי כל עוד לא עשה היבם מעשה, הרי היא זקוקה לייבום לכל האחים, ובכלל זה גם לאח שקידש את אחותה ואסור לו לשאת את אחות זקוקתו.","\u0003חלץ לה אחיו\u0004 ליבמה, \u0003או כנסה — יכנוס\u0004 האח \u0003את אשתו. מתה היבמה — יכנוס את אשתו\u0004 שהיא אחותה, שעכשיו אינה עוד אחות זקוקתו. אם \u0003מת יבם\u0004 לפני שעשה מעשה באשה, נמצא אז שלפני האח יש שתי אחיות, אחת היא ארוסתו, ואחת זקוקה לו לייבום, ולכן \u0003יוציא את אשתו\u0004 (ארוסתו) \u0003בגט,\u0004 מפני שהיא נאסרת עליו משום שהיא אחות זקוקתו, \u0003ו\u0004יוציא את \u0003אשת אחיו בחליצה,\u0004 שהרי היא אסורה עליו משום אחות גרושתו.","לאחר שנשנה הדין הראשון שבמשנה בענין אחות חלוצתו, נאמר: וכן המגרש את אשתו. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הלשון \u0003\"וכן\"?\u0004 שהרי אין דינים אלה דומים זה לזה! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 במקום זה בלשון המתאימה: \u0003\"אבל המגרש\",\u0004 שהרי במקרה הזה אין דינה שחולצת ולא מתייבמת, אלא היא פטורה לגמרי, משום אחות אשה.","\u0003אמר ריש לקיש: כאן שנה רבי\u0004 והסביר את היחס בין שני דינים אלה, ש\u0003אחות גרושה\u0004 אסורה \u0003מדברי תורה,\u0004 ולכן פטורה לגמרי מן הייבום, ואילו \u0003אחות חלוצה\u0004 אסורה רק \u0003מדברי סופרים,\u0004 משום שדומה לגרושה, ואם נפלה לפניו, חולצת ולא מתייבמת.","שנינו במשנה ש\u0003שומרת יבם שקידש\u0004 אחיו את אחותה, לדעת ר' יהודה בן בתירא אומרים לו שימתין עד שיעשה אחיו מעשה. \u0003אמר שמואל: הלכה כדברי ר' יהודה בן בתירא.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: אם \u0003מתה אשתו, מהו\u0004 דינו \u0003ביבמתו?\u0004 האם אסור בה כשם שאסור בה בעוד ארוסתו חיה משום אחות אשתו, או לא? \u0003רב ור' חנינא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 כיון ש\u0003מתה אשתו — מותר ביבמתו,\u0004 שבמות ארוסתו פקע איסור אחות אשתו, ומותרת לו. \u0003שמואל ורב אסי דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 אם \u0003מתה אשתו — אסור ביבמתו.\u0004","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב — משום דהואי\u0004 \u0005[שהריהי]\u0006 זו \u0003יבמה שהותרה\u0004 לו במות בעלה \u0003ונאסרה\u0004 לו לאחר מכן כשקידש את אחותה, \u0003וחזרה והותרה\u0004 לו משמתה ארוסתו, ומכיון שכן \u0003תחזור להיתרה הראשון\u0004 לגמרי. ואף שבמשך זמן מסויים היתה אסורה משום אחות אשתו כשהיתה זקוקה לו — לא נאסרה עליו לעולם.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב המנונא\u0004 ממה ששנינו: היו \u0003שלשה אחין, שנים\u0004 מהם \u0003נשואין שתי אחיות, ואחד מופנה\u0004 (רווק), \u0003מת אחד מבעלי אחיות ועשה בה\u0004 ה\u0003מופנה\u0004 (האח הרווק) \u0003מאמר\u0004 ביבמה זו, \u0003ואחר כך מת אחיו השני,\u0004 ונפלה לפניו גם האחות השניה לייבום, ואז שתיהן אסורות עליו משום שהן אחיות הקשורות אליו בזיקה,","\u0003ואחר כך מתה אשתו\u0004 של האח השני \u0003אחריו\u0004 — הרי \u0003אותה יבמה\u0004 שעשה בה מאמר \u0003חולצת ולא מתיבמת.\u0004","\u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003תיהוי\u0004 \u0005[תהיה]\u0006 זו \u0003כיבמה שהותרה\u0004 לו במות בעלה \u0003ונאסרה\u0004 עליו משמת אחיו ונפלה לפניו גם אחותה \u0003ו\u0004משמתה אחותה \u0003חזרה והותרה,\u0004 ואם כן \u0003תחזור להיתירה הראשון!\u0004","\u0003אישתיק\u0004 \u0005[שתק]\u0006 רבא, שלא מצא לכך תשובה מיד. \u0003לבתר דנפק\u0004 \u0005[לאחר שיצא]\u0006 רב המנונא \u0003אמר\u0004 רבא כמדבר אל עצמו: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא אמרת ליה\u0004 \u0005[אמרת\u0006 (אמרתי) \u0005לו]\u0006 שמשנה זו שהקשה ממנה, כשיטת \u0003ר' אלעזר היא, ש\u0004\u0003אמר:\u0004 כל יבמה \u0003כיון שעמדה עליו שעה אחת באיסור — נאסרה עליו עולמית?\u0004 ואילו אני פסקתי כחכמים.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 לעצמו: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' אלעזר\u0004 דבר זה — \u0003היכא דלא חזיא\u0004 \u0005[היכן,\u0006 כאשר, \u0005שלא\u0006 היתה \u0005ראויה\u0006 לו כלל\u0005]\u0006 \u0003בשעת נפילה, אבל היכא דחזיא\u0004 \u0005[היכן,\u0006 כאשר \u0005שהיתה ראויה]\u0006 \u0003בשעת נפילה,\u0004 כגון במקרה שלנו, שכאשר מת האח הראשון היתה היבמה ראויה לו, ובמקרה כזה \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 שאם נאסרה אחר כך אין לה היתר?","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר: אין\u0004 \u0005[כן]\u0006 ר' אלעזר אוסר גם בזו, \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן\u0006 \u0005שנינו\u0006 בברייתא\u0005]\u0006 שכאשר קידש אדם את אחות יבמתו \u0003ר' אלעזר אומר: מתה יבמתו — מותר באשתו\u0004 (זו שקידש), \u0003מתה אשתו — אותה יבמה חולצת ולא מתיבמת.\u0004 הרי שר' אלעזר סבור שאם נאסרה היבמה עליו אפילו שעה אחת, בין בשעת נפילה בין לאחר מכן — הריהי אסורה לעולם.","ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003שמואל ורב אסי דאמרי\u0004 \u0005[שאומרים]\u0006 שאינה מתייבמת, סבורים \u0003כר' אלעזר?\u0004","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהם סבורים \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים],\u0006 אלא, \u0003עד כאן לא\u0004 שמענו כי \u0003קמיפלגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003ר' אלעזר\u0004 בענין זה שגירש אשה והחזירה, ואחר כך מת, ונפלה אשה זו לייבום, שר' אלעזר אוסרה ליבם משום שבעת שנתגרשה מבעלה היתה אסורה על האח, וחכמים סבורים שמותרת, \u0003אלא משום\u0004 ש\u0003מ\u0004שעת ה\u0003נפילה ואילך לא מיתסר עלייהו\u0004 \u0005[נאסרה עליהם]\u0006 על האחים, שהרי חזר ולקחה, והאיסור שחל על האשה בחיי אחיו אינו נחשב, \u0003אבל הכא דאיתסר\u0004 \u0005[כאן שנאסרה]\u0006 לאחר שנפלה לו לייבום, שהותרה ונאסרה — \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שהיא אסורה, ואם כן, אפשר לפרש את דבריהם גם לדעת החכמים.","\u0003היבמה לא תחלוץ ולא תתייבם עד שיש לה\u0004 (שיעברו) \u0003שלשה חדשים\u0004 מאז מות בעלה. \u0003וכן כל שאר הנשים,\u0004 ולא רק יבמה, \u0003לא יתארסו, ולא ינשאו עד שיהו\u0004 (שיעבור) \u0003להן\u0004 זמן של \u0003שלשה חדשים\u0004 לאחר שנפסק קשר האישות הקודם, כדי שתהא הבחנה בין ילדיו של הבעל הראשון ובעל שני. וכיון שתיקנו תקנה זו אמרו: \u0003אחד בתולות ואחד בעולות, אחד גרושות ואחד אלמנות, אחד\u0004 אם היו קודם לכן \u0003נשואות ואחד\u0004 אם היו רק \u0003ארוסות,\u0004 שבכל אלה (גם כאשר סיבת הגזירה אינה קיימת) גזרו שצריך להמתין שלושה חודשים מתום קשר הנישואין הקודם.","\u0003ר' יהודה אומר:\u0004 אלה שהיו מקודם \u0003נשואות\u0004 — \u0003יתארסו,\u0004 שהרי באירוסין אין איסור, שעדיין אין ביניהם יחסי אישות, \u0003ו\u0004אלה שהיו רק \u0003ארוסות\u0004 ולכן לא היו להן יחסי אישות עם בעליהן — \u0003ינשאו. חוץ מן הארוסות שב\u0004ארץ \u0003יהודה, מפני שלבו גס בה.\u0004 משום שבארץ יהודה היו נוהגים שהארוס וארוסתו היו נפגשים ומתייחדים קודם לנישואיהם, וייתכן שהארוס בעל את ארוסתו, אבל בכל מקום אחר אין חוששים לכך.","\u0003ר' יוסי אומר: כל הנשים יתארסו\u0004 בתוך שלושה חודשים, שלא גזר באירוסין משום נישואין, \u0003חוץ מן האלמנה,\u0004 שהיא יכולה להתארס רק בתום שלושים יום למות בעלה, ולא משום הבחנה, אלא"],["\u0003מפני האיבול\u0004 (האבילות) על בעלה שמת.","שנינו במשנה שהיבמה אינה מתייבמת ואינה חולצת עד שיעברו שלושה חודשים ממות בעלה. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003לא תתייבם —\u0004 יש סיבה לדבר: \u0003שמא\u0004 היא מעוברת, ו\u0003יהיה הולד בן קיימא, וקא פגע\u0004 \u0005[ופוגע]\u0006 היבם \u0003באיסור אשת אח\u0004 שיש לו בנים שהוא איסור \u0003דאורייתא\u0004 \u0005[מן התורה].\u0006 \u0003אלא לא תחלוץ, אמאי\u0004 \u0005[מדוע]?\u0006 שאפילו אם נתברר שהיתה הרה, ותלד בן — נמצא שלא היתה זו חליצה כלל, שהרי בחליצה עצמה אין איסור!","ואם כן \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003ר' יוחנן,\u0004 ש\u0003אמר: חליצת מעוברת שמה חליצה.\u0004 שאם חלץ למעוברת והפילה אחר כך את הולד — הועילה חליצתה זו לפוטרה מן הזיקה. ובמשנתנו נאמר שאינה חולצת כלל, שיש לחשוש שמא היא מעוברת, ותפיל, ותסמוך על החליצה ותינשא ובאמת אין חליצת מעוברת פוטרת. ושואלים: \u0003ולאו מי אותביניה\u0004 \u0005[ו\u0006כי \u0005לא הקשינו\u0006 כבר \u0005עליו]\u0006 על \u0003ר' יוחנן חדא זמנא\u0004 \u0005[פעם אחת]\u0006 (לעיל יבמות לה, ב) וכבר נדחו דבריו?! ומשיבים: \u0003לימא מהא נמי תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005מזה גם כן תהיה קושיה]!\u0006 כיון שאין לנו טעם אחר לדברי המשנה שאינה חולצת.","ודוחים: \u0003לא,\u0004 את הקושיה מכאן אפשר ליישב, \u0003הכא היינו טעמא\u0004 \u0005[כאן זהו הטעם]:\u0006 \u0003שמא יהא\u0004 ה\u0003ולד בן קיימא,\u0004 ונמצא שלא היתה חליצתה חליצה, \u0003ונמצאת אתה מצריכה כרוז\u0004 מטעם בית הדין שיכריז שלמרות שחלצה עדיין ראויה היא להינשא \u0003לכהונה,\u0004 וכדי למנוע זאת אוסרים עליה לחלוץ עד אחר שלושה חדשים.","ושואלים: ומה בכך? \u0003ונצרכה\u0004 \u0005[ונצריך אותה]\u0006 כרוז, ונכריז שהיא כשירה! ומשיבים: אין עושים דבר זה, \u0003דלמא איכא דהואי\u0004 \u0005[שמא יש\u0006 אנשים \u0005שהיו]\u0006 \u0003בחליצה ולא הוי\u0004 \u0005[היו]\u0006 \u0003בהכרזה ומפסלוה\u0004 \u0005[ויפסלוה]\u0006 \u0003מן הכהונה.\u0004","ושואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 שהיתה יבמה זו \u0003אלמנה\u0004 בלבד מבעלה, שאז יש לחשוש לה שמא יאמרו שנפסלה מן הכהונה, אבל אם היתה היבמה הזו \u0003גרושה\u0004 מנישואין קודמים, שבין כה וכה פסולה היא לכהן — \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע איפוא לא תחלוץ? הלא לפסול לכהונה אין לחשוש! ומשיבים: יש טעם אחר בדבר: \u0003משום\u0004 שבחליצה זו הוא \u0003מפסיד לה מזונות,\u0004 שכן כל שלושת החודשים הראשונים ניזונה האלמנה מנכסי בעלה שמת, ומיד כשחולץ לה אינה רשאית ליהנות עוד ממזונות אלה, וכיון שאינה רשאית להינשא — נמצא שאין לה מזונות כלל, ולכן תיקנו לטובתה שלא תחלוץ.","ושואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 תירוץ זה ל\u0003נשואה\u0004 שיש לה מזונות מנכסי בעלה שמת, אולם אם היתה יבמה זו רק \u0003ארוסה,\u0004 והיתה מקודם לכן גם \u0003גרושה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי מזונות מן הנפטר אין לה, ואין לחשוש לפוסלה לכהונה מכיון שהיא כבר פסולה בתור גרושה.","\u0003אלא משום\u0004 הטעם שפירש \u0003ר' יוסי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה באדם אחד שבא לפני ר' יוסי. אמר לו: מהו לחלוץ בתוך שלשה\u0004 חודשים למות האח? \u0003אמר לו: לא תחלוץ.\u0004 שאל אותו: \u0003ותחלוץ, ומה בכך?\u0004 שגם אם היא מעוברת הרי לא ייגרם בכך כל נזק!","\u0003קרא עליו,\u0004 כלומר, הסביר לו את הדברים על פי \u0003מקרא זה: \"ואם לא יחפץ\u0004 האיש לקחת את יבמתו\u0003\"\u0004 (דברים כה, ז) משמע: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אם חפץ — יבם.\u0004 ומכאן אנחנו למדים: \u0003כל העולה לייבום,\u0004 שהיבם רשאי ליבמה אם יחפוץ בכך — \u0003עולה\u0004 גם \u0003לחליצה,\u0004 אבל זו שאינה עולה לייבום, וכגון שהיא בתוך שלושה חודשים למות בעלה, שאינו רשאי ליבמה, אף אינו יכול לחלוץ לה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב חיננא,\u0004 הלא שנינו: יבמות \u0003הספקות — חולצות ולא מתיבמות.\u0004","ונברר תחילה \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ספקות? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ספק קדושין,\u0004 שהיה ספק אם קידשה האח שמת (וכגון שזרק לה כסף קידושין ספק קרוב לו, ספק קרוב לה) — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא מתיבמות? תתייבם, ואין בכך כלום.\u0004 שכן, אם תפסו הקידושין הראשונים — הרי היא יבמה ומותר לייבם אותה, ואם לא היה ממש בקידושין הראשונים, אם כן לא היתה כלל אשת האח, ומותרת להינשא מלכתחילה ליבם.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כגון שהיה כאן \u0003ספק שקידש\u0004 אחיו \u0003אחת משתי אחיות ואינו יודע איזו מהן קידש,\u0004 שבגלל ספק זה אין היבם רשאי לייבם אף אחת מהן, שמא היא אחות זקוקתו. \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 כאן: \u0003חולצות,\u0004 משמע, שאף שאינו רשאי לייבם — יכול לחלוץ!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם],\u0006 בספק של מי שקידש אחת משתי אחיות, מקור הספק הוא בחוסר ידיעתנו, ולכן \u0003אם יבא אליהו ויאמר דהא\u0004 \u0005[ש\u0006את \u0005זו]\u0006 \u0003קידש\u0004 — הרי \u0003בת חליצה וייבום היא,\u0004 הרי שאין באשה זו איסור ייבום כשלעצמה, וכל הטעם שאינו מייבם הוא מחמת חוסר ידיעתנו,","מה שאין כן \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003אם יבא אליהו ויאמר דהא לא איעברה\u0004 \u0005[שזו איננה מעוברת] —\u0006 \u0003מי משגח ביה, ויבמינן לה\u0004 \u0005[האם משגיחים בו,\u0006 מתייחסים לכך, \u0005ומייבמים אותה]?\u0006 וראיה שבמקרה זה אין האיסור נובע מחמת חוסר ידיעתנו — \u0003הא\u0004 \u0005[הרי]\u0006 הדוגמה של \u0003קטנה דלאו בת איעבורי\u0004 \u0005[שלא בת עיבור]\u0006 \u0003היא, ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003צריכה להמתין שלשה חדשים.\u0004 שכיון שגזרו חכמים גזירה — אין מבדילים בין מקרה למקרה, וחל עליה איפוא איסור גמור מדברי חכמים להתייבם ולא מחמת הספק, ולכן אינה עולה גם לחליצה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יבמה,\u0004 כל \u0003שלשה חדשים הראשונים\u0004 אחרי מות בעלה, כיון שאינה יכולה להינשא מחמת בעלה, הריהי \u0003נזונת משל בעל. מכאן ואילך — אינה נזונת לא משל בעל,\u0004 מפני שמה שאינה נישאת אינו מחמת אלמנותה אלא משום שצריך לפטרה בייבום או בחליצה, \u0003ולא משל יבם,\u0004 לפי שעדיין לא ייבם אותה.","\u0003עמד\u0004 היבם \u0003בדין,\u0004 ופסקו שחובתו לכנוס או לפטור אותה בחליצה, \u0003וברח\u0004 ולא עשה בה מעשה כלל — \u0003נזונת משל יבם.\u0004","ושואלים: אם \u0003נפלה לפני יבם קטן מאי\u0004 \u0005[מה]\u0006 יהא דינה? שיבם זה, שהיא ממתינה לו, עדיין קטן הוא, וצריכה להמתין עד שיגדל. שהרי מזונות \u0003מיבם לית\u0004 \u0005[אין]\u0006 \u0003לה,\u0004 שהרי אינו יכול לייבם אותה, וכיון שהמניעה אינה באשמתו, אי אפשר לקונסו שיתן לה מזונות. אולם כיון שהיא חייבת להמתין עד שיגדל היבם, שתמשיך ותזון \u0003מ\u0004של ה\u0003בעל מאי\u0004 \u0005[מה]\u0006 הדין, האם מותר לה, או לא?","\u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 מזונות מנכסי בעלה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לית\u0004 \u0005[אין]\u0006 \u0003לה, והלכתא\u0004 \u0005[ההלכה]\u0006 היא: \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 מזונות כלל, \u0003משמיא\u0004 \u0005[מן השמים]\u0006 \u0003קנסוה.\u0004 כלומר, משמים אירע לה כך ואי אפשר לחייב את נכסי בעלה המת במזונותיה.","\u0003תנו רבנן\u0004 \u0005[שנו החכמים]:\u0006 \u0003יבמה שחלצו לה אחים בתוך שלשה\u0004 חדשים למות האח — \u0003צריכה להמתין שלשה חדשים\u0004 מיום המיתה."],["\u0003לאחר שלשה\u0004 חודשים — \u0003אין צריכה להמתין שלשה חדשים\u0004 מזמן החליצה ורשאית להינשא מיד.","\u0003הוי\u0004 \u0005[הרי]\u0006 ראיה ש\u0003השלשה חדשים שאמרו,\u0004 נמנים \u0003משעת מיתת הבעל, ולא משעת חליצת היבם.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר\u0005]\u0006 \u0003מגט,\u0004 ש\u0003רב אמר\u0004 בעניינו: מונים שלושה חדשים \u0003משעת נתינה\u0004 של הגט, \u0003ושמואל אמר: משעת כתיבה,\u0004 שמשעה שכותב גט לאשתו אסור לו להתייחד עימה, שאם לא כן ייפסל הגט, ולכן אפשר למנות כבר מזמן הכתיבה. נמצא שבגט סבור רב כי מונים מזמן התרת האשה בפועל שהוא זמן נתינת הגט, ואילו בחליצה אין הולכים אחר זמן החליצה!","\u0003אמר רבא: קל וחומר\u0004 הוא ביבמה שחליצתה מתירתה: שכן אם \u0003איסור כרת התרת,\u0004 שהרי מותר ליבם לבוא על יבמתו שלושה חדשים לאחר מות בעלה, למרות שייתכן שיבמה זו היא בהריון, ואז עובר היבם משום אשת אח, שאסורה מן התורה באיסור כרת, ובכל זאת אין חוששים לכך לאחר שלושה חדשים ומתירים לייבמה — \u0003איסור לאו\u0004 שמא היה פסול בחליצה ונישאה היבמה לאדם אחר בלא חליצה, שיש בכך רק איסור לאו — \u0003לא כל שכן\u0004 שיהא מותר. ולכן, כיון שאחרי שלושה חדשים מותר לייבמה, כל שכן שמותר גם לאדם מן השוק לשאתה לאשה אם נחלצה.","שנינו במשנה: \u0003וכן כל שאר הנשים\u0004 צריכות להמתין שלושה חדשים מזמן התרת קשר הנישואין עד לנישואין אחרים. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003יבמה,\u0004 הרי זה \u0003כדאמרן\u0004 \u0005[כ\u0006מו \u0005שאמרנו],\u0006 כדי שיתברר אם מעוברת היא, כדי שלא יפגע באיסור אשת אח שיש לה בנים, \u0003אלא שאר כל הנשים אמאי\u0004 \u0005[מדוע]\u0006 צריכות להמתין? שהרי גם אם היתה בהריון מן הבעל הראשון, נישואיה השניים אין בהם פסול, והילד הוא ילד כשר בכל מקרה, גם אם יש ספק מי מן הבעלים הוא אביו!","\u0003אמר רב נחמן אמר שמואל: משום\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באברהם: \u0003\"להיות לך לאלהים ולזרעך אחריך\"\u0004 (בראשית יז, ז), ללמד שהשכינה שורה רק על אלה שייחוסם ברור וודאי, ולכן ממתינה האשה שלושה חודשים כדי \u0003להבחין בין זרעו של ראשון לזרעו של שני.\u0004 שאם אמנם היתה מעוברת מן הראשון, הרי הוולד שיוולד זמן קצר לאחר הנישואין ברור יהיה לכול שהוא בנו של הראשון.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא:\u0004 אם זהו הטעם, אם כן, מה ששנינו: \u0003לפיכך,\u0004 בגלל גדר זה שגדרו חכמים, \u0003גר וגיורת\u0004 שהיו נשואים זה לזה והתגיירו שניהם — \u0003צריכין\u0004 לפרוש זה מזה ו\u0003להמתין שלשה חדשים\u0004 ורק אז מותר להם לשוב ולחיות כאחד, ולכאורה \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 ענין של \u0003להבחין איכא\u0004 \u0005[יש]?\u0006","ומשיבים: \u0003הכא נמי איכא\u0004 \u0005[כאן גם כן יש]\u0006 \u0003להבחין בין זרע שנזרע בקדושה,\u0004 כלומר, שגם הורתו של הילד היתה בקדושת ישראל, \u0003לזרע שלא נזרע בקדושה.\u0004 שאם הגיורת היתה מעוברת בהיותה גויה, אף שהילד הוא ילד כשר בישראל, מכל מקום יש בו פגם מסויים, שכן הורתו לא היתה בקדושה, ויש גם הבדל בדינם.","\u0003רבא אמר\u0004 טעם אחר להבחנה זו: משום \u0003גזירה,\u0004 שאם לא יהא ברור מי אבי הילד ויתכן שייחסו אותו בטעות לאב אחר ו\u0003שמא\u0004 בעתיד \u0003ישא את אחותו מאביו\u0004 האמיתי, או שיש לחשוש שמא תלד אמו בן לשני (שעל פי האמת אינו אחיו אלא מאמו) וימות אותו בן בלא בנים ובטעות יבוא זה ו\u0003ייבם\u0004 את \u0003אשת אחיו מאמו\u0004 שהיא עליו בכרת.","וכן יש לחשוש שמא ימות השני בלא בנים, ומתוך שהוא חושב שהוא בנו של השני וממילא היא פטורה מייבום וחליצה \u0003יוציא\u0004 בטעות \u0003את אמו\u0004 ויתירה להינשא \u0003לשוק.\u0004 וכן אם נולד לאמו מבעלה הראשון בן אחר ומת אותו בן בלי בנים ואין להם אח נוסף, ומתוך שהוא חושב שהוא בנו של השני, ממילא יבוא \u0003ויפטור\u0004 בטעות \u0003את יבמתו\u0004 להינשא \u0003לשוק,\u0004 אף על פי שעל פי האמת היא זקוקה לו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב חנניה: בכולן,\u0004 בכל היבמות שאסרו חכמים שתינשאנה, \u0003אני קורא בהן,\u0004 כלומר, הטעם הוא \u0003משום תקנת ערוה,\u0004 שלא יגיע לידי גילוי עריות, \u0003וכאן\u0004 באיסור זה שלא לייבם או לשאת אשה מיד לאחר מות בעלה הראשון, הטעם הוא \u0003משום תקנת ולד,\u0004 כדי שידעו מי אביו. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדבריו של רבא, אם כן \u0003כולהו\u0004 \u0005[כולם]\u0006 ואף תקנה זו בכלל, הן \u0003משום תקנת ערוה!\u0004","ומשיבים: אכן, זו הכוונה, \u0003האי\u0004 \u0005[\u0006תקנה \u0005זו]\u0006 היא \u0003משום תקנת ולד,\u0004 ש\u0003לא לפגע בהו\u0004 \u0005[יפגע בהם]\u0006 \u0003ערוה,\u0004 שאכן גם בתקנה זו הטעם הוא בסופו של דבר משום ערוה, אלא שכאן הדאגה היא בראש ובראשונה לתקנת הוולד.","בלגופה של גזירת חכמים, להמתנה של שלושה חודשים, שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003תמתין שני חדשים ותנשא — לא\u0004 התרנוה, \u0003דהיינו ספיקא\u0004 \u0005[שהרי זה הספק]:\u0006 \u0003אי\u0004 \u0005[אם\u0006 הוולד\u0005]\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003תשעה\u0004 חודשים והוא נולד \u0003לקמא\u0004 \u0005[ל\u0006בעל \u0005הראשון],\u0006 \u0003אי בר\u0004 \u0005[או\u0006 שהוולד \u0005בן]\u0006 \u0003שבעה\u0004 חודשים \u0003לבתרא\u0004 \u0005[ל\u0006בעל \u0005האחרון,\u0006 השני\u0005].\u0006","\u0003אלא\u0004 מדוע לא \u0003תמתין חדש אחד\u0004 בלבד \u0003ותנשא, ואי\u0004 \u0005[ואם]\u0006 \u0003לשבעה\u0004 חודשים אחרי נישואיה השניים \u0003ילדה — האי\u0004 \u0005[זה,\u0006 הוולד\u0005]\u0006 ברור ש\u0003בר\u0004 \u0005[בן]\u0006 \u0003שבעה\u0004 חודשים \u0003לבתרא\u0004 \u0005[לאחרון,\u0006 לשני\u0005]\u0006 \u0003הוא,\u0004 שאין אשה יולדת ולד חי לשמונה חודשים. \u0003ואי לתמניא\u0004 \u0005[ואם לשמונה]\u0006 חודשים \u0003ילדה — האי\u0004 \u0005[זה,\u0006 הוולד\u0005]\u0006 ברור ש\u0003בר\u0004 \u0005[בן]\u0006 \u0003תשעה\u0004 חודשים \u0003לקמא\u0004 \u0005[לראשון]\u0006 \u0003הוא!\u0004","ומשיבים: \u0003אי נמי לתמניא\u0004 \u0005[אם גם לשמונה]\u0006 חודשים \u0003ילדה, איכא למימר דבתרא\u0004 \u0005[יש\u0006 מקום \u0005לומר ש\u0006של \u0005האחרון,\u0006 השני\u0005]\u0006 \u0003הוא.\u0004 כיצד? שמא עובר זה נולד לשבעה חודשים, אלא \u0003דלמא אשתהויי אשתהא\u0004 \u0005[שמא שהתה]\u0006 \u0003חדש אחד,\u0004 שלא נתעברה מיד עם נשואיה, \u0003ואיעבר\u0004 \u0005[ונתעברה]\u0006 חודש לאחר מכן.","ושואלים עוד: \u0003ותמתין שני חדשים ומחצה ותנשא,\u0004 ואז לא יהיה ספק: \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לשבעה\u0004 חודשים \u0003ילדה, האי בר\u0004 \u0005[זה,\u0006 הוולד \u0005בן]\u0006 \u0003שבעה לבתרא\u0004 \u0005[לאחרון,\u0006 לשני\u0005]\u0006 \u0003הוא, ואי לשיתא ופלגא\u0004 \u0005[ואם לשישה וחצי]\u0006 חודשים \u0003ילדה,\u0004 ודאי \u0003האי בר\u0004 \u0005[זה בן]\u0006 \u0003תשעה\u0004 חודשים \u0003לקמא\u0004 \u0005[לראשון]\u0006 \u0003הוא. דאי בר בתרא\u0004 \u0005[שאם בן האחרון,\u0006 השני\u0005]\u0006 \u0003הוא —\u0004 הלא עובר \u0003בר שיתא ופלגא לא חיי\u0004 \u0005[בן שישה וחצי\u0006 חודשים \u0005איננו חי]!\u0006","ודוחים: \u0003אי נמי לשיתא ופלגא\u0004 \u0005[אם גם כן לשישה וחצי]\u0006 חודשים \u0003ילדה, איכא למימר דבתרא\u0004 \u0005[יש\u0006 עדיין מקום \u0005לומר ששל האחרון,\u0006 השני\u0005]\u0006 \u0003הוא,\u0004 ש\u0003אמר מר זוטרא: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי ה\u0003יולדת לתשעה\u0004 חודשים \u0003אינה יולדת למקוטעין,\u0004 אלא משלימה תשעה חודשים שלמים, מכל מקום, אם \u0003ילדה לשבעה — יולדת\u0004 אפילו \u0003למקוטעין.\u0004","\u0003שנאמר: \"ויהי לתקפות הימים\u0004 ותהר חנה ותלד בן\u0003\"\u0004 (שמואל א' א, כ), וחשבון הזמן הוא: \u0003מיעוט \"תקופות\"\u0004 שהוא לשון רבים — \u0003שתים,\u0004 וכל תקופת שנה היא שלושה חודשים, הרי שישה חודשים, \u0003מיעוט \"ימים\" — שנים,\u0004 כלומר, שילדתו לשישה חודשים ושני ימים, הרי שאשה היולדת לשבעה חודשים יכולה ללדת אפילו בפחות משבעה חודשים שלמים.","ושואלים עוד: \u0003ותמתין משהו,\u0004 זמן קצר, פחות מחודש, \u0003ותנשא. וכי מלו\u0004 \u0005[וכאשר ימלאו]\u0006 \u0003שלשה חדשים\u0004 מיום שניתק הקשר מבעלה הראשון — \u0003לבדקה\u0004 \u0005[שיבדקו אותה]\u0006 אם הרה היא, כדרך הבדיקות שבודקים כרגיל בין הנשים שהרי פחות משלושה חדשים אין העובר ניכר, ואם לפי הבדיקות הריהי הרה שלושה חודשים — ודאי שלראשון היא הרה!","\u0003אמר רב ספרא:\u0004 כלל הוא ש\u0003אין בודקין את הנשואות\u0004 בזה, כדי \u0003שלא יתגנו על בעליהן\u0004 שמישהו אחר בודק אותן. ושואלים: \u0003ונבדקה\u0004 \u0005[ונבדוק אותה]\u0006 \u0003בהלוכה\u0004 שאפשר להבחין בין אשה בהריון לאחר שלושה חודשים לשאינה בהריון, לפי דרך הילוכה.","\u0003אמר רמי בר חמא: אשה\u0004 לפעמים \u0003מחפה\u0004 (מסתירה) \u0003עצמה\u0004 ומשנה את דרך הילוכה בכוונה, כדי שלא ידעו שהיא מעוברת. ויש לה טעם בדבר, \u0003כדי שיירש בנה בנכסי בעלה\u0004 השני שיחשבו שבנו הוא. ולכן אי אפשר לסמוך על בדיקה זו.","ושואלים: \u0003היכא דקים לן\u0004 \u0005[היכן שמוחזק,\u0006 שברור, \u0005לנו]\u0006 ש\u0003מעוברת היא,\u0004 מדוע לא \u0003תנשא\u0004 מיד? שאז אין חשש כלל, שכן כל החששות הללו של הבחנה אינם קיימים! \u0003אלמה תניא\u0004 \u0005[מדוע שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ישא אדם\u0004 אלמנה או גרושה שהיא \u0003מעוברת חברו\u0004 (לבעלה הקודם), או \u0003מינקת חברו,\u0004 שיש לה ילד מבעלה הקודם שהוא עדיין בתקופת ההנקה שלו. \u0003ואם נשא\u0004 למרות זאת — \u0003יוציא,\u0004 יגרש אותה, \u0003ולא יחזיר עולמית!\u0004","ומסבירים שם שהטעם הוא \u0003גזרה שמא תעשה עוברה סנדל,\u0004 כלומר, אם תינשא לאחר בתוך זמן הריונה, שמא תחזור ותתעבר שנית, ועל ידי זה יימעך עוברה הראשון, ושואלים: \u0003אי הכי דידיה נמי\u0004 \u0005[אם כך\u0006 הילד \u0005שלו גם כן]\u0006 שאם אנו חוששים שמא תחזור ותתעבר, הרי יש לאסור לכל אדם לבוא על אשתו כשהיא בהריון, מחשש זה!","ומשיבים: \u0003אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]\u0006 שאשה מעוברת רשאית להשתמש \u0003במוך\u0004 כדי שלא תתעבר — אם כן תשתמש \u0003במוך, ואי למאן דאמר\u0004 \u0005[ואם ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003מן השמים ירחמו\u0004 ולכן אין אוסרים שיבא אדם על אשתו ההרה — אם כן יבוא עליה ו\u0003מן השמים ירחמו.\u0004","ושבים ומקשים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במעוברת חבירו — \u0003אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]\u0006 שרשאית להשתמש \u0003במוך\u0004 — תשתמש גם כאן \u0003במוך, אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003מן השמים ירחמו —\u0004 גם כאן יבוא עליה השני ו\u0003מן השמים ירחמו!\u0004","\u0003אלא,\u0004 לא זה הטעם, כי אם \u0003משום דחסה\u0004 \u0005[הדוחק]\u0006 של שעת תשמיש, שיכול להזיק לעובר. ושואלים: \u0003אי הכי דידיה נמי\u0004 \u0005[אם כך\u0006 ב\u0005שלו גם כן]\u0006 נגזור שלא יבוא עליה משום אותו חשש! ומשיבים: \u0003דידיה חייס עילויה\u0004 \u0005[על\u0006 העובר \u0005שלו\u0006 הוא \u0005חס]\u0006 וישתדל שלא לדחוק אותה הרבה. ואומרים: \u0003הכא נמי חייס עילויה\u0004 \u0005[כאן,\u0006 במעוברת חבירו, \u0005גם כן חס עליו],\u0006 שבוודאי אין אדם הורג את הנפש בכוונה, ואם הוא יודע שהאשה מעוברת והלחץ יזיק לעובר ישתדל לא ללחוץ אותה.","\u0003אלא\u0004 יש לחזור מטעם זה, ולומר שהטעם הוא: כי \u0003סתם מעוברת למניקה קיימא\u0004 \u0005[להניק\u0006 את הילד שעתיד להוולד היא \u0005עומדת],\u0006 ואם כן יש לחשוש"],["\u0003דלמא איעברה ומעכר\u0004 \u0005[שמא תתעבר\u0006 שנית \u0005ויעכר]\u0006 \u0003חלבה\u0004 בזמן ההריון \u0003וקטלה ליה\u0004 \u0005[ותהרוג אותו],\u0006 כלומר, תגרום שימות הוולד משום שלא יהיה לו מספיק חלב לינוק. ושואלים: \u0003אי הכי דידיה נמי\u0004 \u0005[אם כך שלו גם כן]\u0006 יש לחשוש לכך. ומשיבים: \u0003דידיה ממסמסא ליה\u0004 \u0005[את שלו\u0006 היא \u0005מאכילה אותו]\u0006 \u0003בביצים וחלב,\u0004 כתחליף לחלב האם. ושואלים: אם כן \u0003דידה נמי ממסמסא ליה\u0004 \u0005[\u0006את הילד \u0005שלה\u0006 \u0005גם כן תאכיל]\u0006 \u0003בביצים וחלב!\u0004 ומשיבים: \u0003לא יהב\u0004 \u0005[נותן]\u0006 \u0003לה בעל\u0004 כסף לקנות את אלה עבור ילד שאיננו שלו. ומקשים: \u0003וליתבעיניה\u0004 \u0005[ושתתבע]\u0006 את ה\u0003יורשים\u0004 של בעלה הראשון שיפרנסו את הילד! \u0003אמר אביי: אשה בושה לבא לבית דין\u0004 בתביעות, ונמצא שאין לילד מזונות \u0003והורגת\u0004 על ידי כך \u0003את בנה.\u0004","שנינו במשנה: \u0003אחת בתולות ואחת בעולות,\u0004 אחת גרושות ואחת אלמנות, אחת נשואות ואחת ארוסות, כולן, אינן יכולות להתארס או להינשא עד שיעברו שלושה חודשים מבעליהן הקודמים. ותוהים: \u0003הי ניהו\u0004 \u0005[מי אלו]\u0006 ה\u0003בתולות והי ניהו\u0004 \u0005[ומי אלו]\u0006 ה\u0003ארוסות?\u0004 שהרי זו שנתאלמנה מן האירוסין, יבמה בתולה היא! וכן \u0003הי ניהו\u0004 \u0005[מי אלו]\u0006 ה\u0003בעולות והי ניהו\u0004 \u0005[ומי אלו]\u0006 ה\u0003נשואות?\u0004 הרי לכאורה שוב מדובר על אותן נשים!","\u0003אמר ר' יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: אין מונים כאן נשים שונות, אלא זו קביעה כללית: \u0003אחת בתולות ואחת בעולות, שנתארמלו או שנתגרשו, בין מן האירוסין\u0004 ו\u0003בין מן הנשואין.\u0004","מסופר: \u0003ר' אלעזר לא על לבי מדרשא\u0004 \u0005[נכנס לבית המדרש]\u0006 יום אחד, \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003ר' אסי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי אמור רבנן בבי מדרשא\u0004 \u0005[מה אמרו חכמים בבית המדרש]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: הלכה כר' יוסי\u0004 המתיר לארוסות להינשא ולנשואות להתארס.","שאל אותו ר' אלעזר: האם \u0003מכלל\u0004 זה אתה למד \u0003דיחידאה פליג עליה\u0004 \u0005[שיחיד\u0006 הוא ה\u0005חולק עליו],\u0006 ואין ההלכה השנויה במשנה סתם דעת רבים? ענה לו: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי\u0004 אשה \u0003שהיתה רדופה\u0004 (רגילה ולהוטה) \u0003לילך לבית אביה\u0004 והיתה מצויה שם זמן רב בלא בעלה, \u0003או שהיה לה כעס בבית בעלה\u0004 והלכה לבית אביה מטעם זה, \u0003או שהיה בעלה חבוש בבית האסורין\u0004 לפני מותו, \u0003או שהיה בעלה זקן או חולה\u0004 שאינו יכול להוליד, \u0003או שהיתה היא חולה,\u0004","\u0003או שהפילה\u0004 מיד \u0003אחר מיתת בעלה, או שהיתה עקרה\u0004 (שניטל רחמה), \u0003או\u0004 שהיתה \u0003זקנה, או\u0004 שהיתה \u0003קטנה, או אילונית\u0004 (שאינה ראויה ללדת מטבע בריי תה), \u0003או שאינה ר\u0004 אויה ל\u0003ילד\u0004 מחמת מחלה וכדומה — הרי זו \u0003צריכ\u0004 ה להמתין שלשה חדשים, למרות שהטעמים שניתנו לגזירת ההפר \u0003שה אינם קיימים במקרים אלה, אלו דבר\u0004 י ר' מאיר\u0003. ר' יהודה מתיר\u0004 במקרי ם אלה \u0003ליארס ולינשא מיד\u0004 ומכאן שהחולק על ר \u0003' יוסי הוא חכם יחיד, ר' מאיר.\u0004","\u0003אמר ר' חייא בר אבא: חזר בו ר' יוחנן\u0004 ממה שפסק כר' יוסי. \u0003אמר רב יוסף: אי הדר ביה\u0004 \u0005[אם חזר בו] —\u0006 \u0003ממתניתא דכרמא הדר ביה\u0004 \u0005[מ\u0006פני \u0005הברייתא של הכרם חזר בו].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' ישמעאל בנו של ר' יוחנן בן ברוקה, שמעתי מפי חכמים בכרם ביבנה: כולן,\u0004 גם נשים שאינן ראויות ללדת, \u0003צריכות להמתין שלשה חדשים.\u0004 הרי שדעת גדולי החכמים כדעת סתם משנתנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זריקא: כי עיילת לקמיה\u0004 \u0005[כאשר תיכנס לפניו]\u0006 לפני \u0003ר' אבהו, רמי ליה\u0004 \u0005[השלך לו,\u0006 הראה לפניו סתירה זו\u0005]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן הלכה כר' יוסי? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 כלל: \u0003הלכה כסתם משנה. ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]\u0006 בסתם: \u0003כל הנשים לא ינשאו ולא יתארסו עד שיהו להם שלשה חדשים, אחת בתולות ואחת בעולות!\u0004","כאשר בא ר' זריקא ושאל, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003דרמא\u0004 \u0005[\u0006זה \u0005שהשליך],\u0006 שהראה \u0003לך הא\u0004 \u0005[\u0006סתירה \u0005זו] —\u0006 \u0003לא חש לקמחיה\u0004 \u0005[חשש לקמחו],\u0006 כלומר, לא דאג לדקדק בדברים שהוא מוציא מפיו. והרי משנתנו \u0003סתם ואחר כך מחלוקת היא,\u0004 שאין זו סתם משנה ללא חולקים, אלא מיד מובאת דעת החולקים, \u0003ו\u0004במקרה זה \u0003אין הלכה כסתם.\u0004 ש\u0003אמר רב פפא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן: מחלוקת ואחר כך סתם — הלכה כסתם,\u0004 שנראה שסתם משנה היא סיכום ההלכה בענין זה, אולם אם יש \u0003סתם ואחר כך מחלוקת — אין הלכה כסתם.\u0004","מסופר: היה \u0003מסתמיך ואזיל\u0004 \u0005[נשען והולך]\u0006 \u0003ר' אבהו אכתפיה\u0004 \u0005[על כתיפו]\u0006 של \u0003ר' נחום שמעיה\u0004 \u0005[שמשו]\u0006 ותוך כדי הילוך היה ר' נחום \u0003מנקיט ואזיל הלכתא מיניה\u0004 \u0005[\u0006היה \u0005לוקט ואוסף הלכות ממנו]\u0006 מר' אבהו. ובתוך כך \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 ר' נחום מר' אבהו: \u0003מחלוקת ואחר כך סתם מאי\u0004 \u0005[מה]\u0006 פסק ההלכה במקרה כזה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003הלכה כסתם.\u0004 המשיך ר' נחום ושאל: \u0003סתם ואחר כך מחלוקת מאי\u0004 \u0005[מה]\u0006 הדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003אין הלכה כסתם.\u0004","ושוב שאל: כשיש \u0003סתמא דמתניתין\u0004 \u0005[סתם\u0006 ב\u0005משנתנו]\u0006 \u0003ומחלוקת בברייתא מאי\u0004 \u0005[מה]\u0006 הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הלכה כסתם\u0004 משנה. ועוד שאל: \u0003מחלוקת במתניתין\u0004 \u0005[במשנתנו]\u0006 \u0003וסתמא\u0004 \u0005[וסתם]\u0006 \u0003בברייתא, מאי\u0004 \u0005[מה]\u0006 דינו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003וכי רבי לא שנאה, ר' חייא\u0004 תלמידו שערך את הברייתא \u0003מנין לו?\u0004 כלומר, אין אנחנו מתחשבים בברייתא, אפילו זו שערך ר' חייא, משום שאם רבי לא שנה ולא סיכם הלכה זו במשנה, אין לסמוך על דברי ר' חייא שסתם אותה, אלא על המשנה שראתה בכך דעת יחיד.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מסרק של פשתן,\u0004 שסורקים בו את הפשתן לאחר ניפוצו, כדי להכינו לטוויה, \u0003שניטלו שיניו, ונשתיירו בו שתים\u0004 מהן, אם היה המסרק טמא — אף השיניים שנשתיירו בו \u0003טמאות,\u0004 משום שמסרק זה ראוי עדיין לשמש ככלי, ואין טומאתו בטילה. \u0003ו\u0004אם נשארה בו רק שן \u0003אחת,\u0004 שאינו ראוי לשמש לסריקה כלל, \u0003טהורה. וכולן,\u0004 כל השיניים הללו לעצמן, \u0003שניטלו אחת אחת בפני עצמן — טמאות,\u0004 משום שהן ראויות לשמש ככלי בפני עצמו, כגון לכרוך עליהן חוט וכיוצא בזה.","מסרק \u0003של צמר שניטלו שיניו,\u0004 אם היה זה באופן שניטלה אחת \u0003אחת מבינתים,\u0004 כך שאין שתי שיניים סמוכות זו לזו — המסרק \u0003טהור,\u0004 משום שאיננו יכול לשמש עוד לסריקת הצמר. \u0003נשתיירו בו שלש\u0004 שיניים \u0003במקום אחד — טמא,\u0004 שהרי אפשר לסרוק בו שם. אם \u0003היתה החיצונה\u0004 שהיא המסגרת \u0003אחת מהן\u0004 מאותן השיניים — \u0003טהור,\u0004 משום ששן זו עבה יותר, ואין השיניים האחרות ראויות עוד לסירוק. \u0003ניטלו שנים\u0004 מן השיניים \u0003ועשאן למלקט\u0004 (מלקחיים קטנות) — \u0003טמאות.\u0004 ניטלה \u0003אחת\u0004 מן השיניים \u0003והתקינה לנר\u0004 כדי לנקותו \u0003או למיתוח\u0004 כעין יתד קטנה שימתחו עליה דברים — \u0003טמאה\u0004 שהרי היא משמשת כלי לעצמו,","\u0003וקיימא לן\u0004 \u0005[ומוחזק לנו]\u0006 ש\u0003אין הלכה כאותה משנה,\u0004 והרי זה סותר את כללו של ר' יוחנן שהלכה כסתם משנה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בר מינה\u0004 \u0005[חוץ ממנה],\u0006 מן המשנה \u0003ההיא,\u0004 שכן, \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003זו אינה משנה,\u0004 כלומר, אין לסמוך על גירסת משנה זו ואין לקבלה כהלכה.","לגופו של הענין שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שאמרו שזו אינה משנה? \u0003אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אידי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: משום דקשיא רישא לסיפא\u0004 \u0005[שקשה ראשה לסופה],\u0006 ולכן נראה שנוסחתה משובשת. \u0003דקתני\u0004 \u0005[ששנה\u0006 התנא שם\u0005]:\u0006 מסרק \u0003של צמר שניטלו שיניו אחת מבינתים — טהור.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נשתיירו בו שתים במקום אחד —\u0004 משמע שהוא \u0003טמא, והדר תני\u0004 \u0005[וחזר\u0006 ו\u0005שנה]\u0006 \u0003נשתיירו בו שלש\u0004 שיניים כאחת — \u0003טמא.\u0004 ונדייק \u0003שלש — אין\u0004 \u0005[כן],\u0006 \u0003שתים\u0004 — \u0003לא,\u0004 ואם כן יש סתירה בנוסח זה!","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 שבכך? \u0003דלמא הא בגווייתא\u0004 \u0005[שמא זו ב\u0006שינים \u0005הפנימיות]\u0006 שהן באמצע במסרק ואפשר להשתמש בהן, ובאופן כזה עדיין הוא נחשב ככלי וטמא, ו\u0003הא בברייתא\u0004 \u0005[\u0006ו\u0005זו בחיצוניות]\u0006 שסמוכות לצד המסרק ובשתיים כאלה אי אפשר לסרוק ושוב אינו נחשב ככלי, ועל ידי כך תיושב הסתירה שבדברים.","\u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 הקושי, \u0003דקתני\u0004 \u0005[ששנה]\u0006 שם: \u0003וכולן שניטלו אחת אחת בפני עצמן טמאות.\u0004 ונדייק: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא התקינה,\u0004 את השן הזו לשמש לצורך דבר אחר, טמאה היא. \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 ניטלה \u0003אחת\u0004 מן השיניים \u0003והתקינה לנר או למיתוח — טמאה.\u0004 משמע: \u0003התקינה — אין\u0004 \u0005[כן],\u0006 \u0003לא התקינה — לא!\u0004","\u0003אמר אביי\u0004 בדחיה: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 שבכך? \u0003דלמא הא בקתייהו\u0004 \u0005[שמא זה\u0006 שניטלו השיניים \u0005בקתיהן,\u0006 עם בסיסן\u0005]\u0006 ואז ראויות הן מיד לשימושים שונים, \u0003הא\u0004 \u0005[זה]\u0006 שניטלו \u0003בלא קתייהו\u0004 \u0005[קתיהן],\u0006 ואם לא התקינן — אינן טמאות.","\u0003אמר רב פפא,\u0004 אפשר לתרץ קושי זה באופן אחר: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 בזה? \u0003ודלמא הא בקטינתא הא באלימתא\u0004 \u0005[ושמא, זו, בדקות\u0006 שאינן ראויות לשימוש ו\u0005זו, בעבות],\u0006 שכל אחת ראויה לשימוש בפני עצמה.","\u0003אלא,\u0004 יש לדחות את הטעם שאמרנו שמשנה זו משובשת בנוסחה, והטעם מדוע אינה נחשבת סתם משנה הוא \u0003משום דמסיימי\u0004 \u0005[שמסיימים]\u0006 \u0003בה\u0004 במשנה זו \u0003דווקני\u0004 \u0005[המדייקים]\u0006 בעלי המסורת: \u0003זו דברי ר' שמעון.\u0004 כלומר, שהיא דעת יחיד בלבד ולא סתם משנה.","לגופה של ההלכה במשנה \u0003שלח ר' חייא בר אבין\u0004 מארץ ישראל: \u0003מארסין\u0004 (אבל לא נושאים) אשה \u0003תוך שלשה\u0004 חודשים למות בעלה, \u0003וכן עושים מעשה\u0004 בפועל.","\u0003וכן היה ר' אלעזר מלמדנו משום ר' חנינא הגדול,\u0004 שכך מונים: \u0003רובו של\u0004 חודש \u0003ראשון ורובו של שלישי, ו\u0004חודש \u0003אמצעי שלם,\u0004 ואין צריך להמתין שלושה חודשים שלמים כדי להתארס.","\u0003אמימר שרא\u0004 \u0005[התיר]\u0006 \u0003ליארס ביום תשעים. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003צריכה להמתין שלשה חדשים\u0004 שלמים, \u0003חוץ מיום שמת בו וחוץ מיום שנתארסה בו,\u0004 משמע שביום תשעים שהוא בסוף שלושה חודשים אסור! אמר לו אמימר: \u0003ההוא,\u0004 אותו דבר ששמעת חוץ מיום שמת ויום שנתארסה — \u0003לענין מינקת איתמר\u0004 \u0005[נאמר],\u0006 ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 המינקת \u0003צריכה להמתין\u0004 מלהתארס עד לאחר \u0003עשרים וארבעה חודש, חוץ מיום שנולד בו וחוץ מיום שנתארסה בו.\u0004","ומקשים: \u0003והא ההוא דעבד\u0004 \u0005[והרי\u0006 מעשה ב\u0005אחד שעשה]\u0006 \u0003סעודת אירוסין ביום תשעים\u0004 למות הבעל הראשון \u0003ואפסדיה\u0004 \u0005[והפסידו]\u0006 \u0003רבא לסעודתיה\u0004 \u0005[את סעודתו],\u0006 שאסר על האשה להתארס ביום זה! ומשיבים: הסעודה \u0003ההיא, סעודת נשואין הואי\u0004 \u0005[היתה]\u0006 ולכן הפסיד את הסעודה, אבל אירוסין מותר.","ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה]:\u0006 מינקת \u0003צריכה להמתין עשרים וארבעה חודש חוץ מיום שנולד בו וחוץ מיום שנתארסה בו. ו\u0004זו שנתאלמנה או נתגרשה ואינה מינקת \u0003צריכה להמתין שלשה חדשים, חוץ מיום שמת בו וחוץ מיום שנתארסה בו.\u0004","נאמר במשנה שר' יוסי התיר לכל הנשים להתארס תוך שלושה חודשים \u0003חוץ מן האלמנה\u0004 מפני האבל. \u0003אמר רב חסדא\u0004 בתמיהה: הלא \u0003קל וחומר\u0004 הוא שנאמר להיפך: \u0003ומה במקום שאסור\u0004 אפילו \u0003לכבס\u0004 בגדים מפני האבל, אמרו חכמים כי \u0003מותר ליארס — מקום שמותר לכבס\u0004 לאחר שבעה ימים של אבל \u0003אינו דין שמותר ליארס?!\u0004","ומסבירים: תחילה \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 ההלכה שרב חסדא רמז לה — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שבת\u0004 (שבוע) \u0003שחל תשעה באב בתוכה — אסור לספר ולכבס,\u0004 אבל \u0003ב\u0004יום \u0003חמישי\u0004 בשבוע — \u0003מותר, מפני כבוד השבת. ותניא\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קודם הזמן הזה\u0004 (והבינו — קודם תשעה באב) — \u0003העם ממעטין בעסקיהם, מלישא ומליתן\u0004 במסחר, \u0003מלבנות ולנטוע, ומארסין\u0004 נשים \u0003אבל לא כונסין\u0004 אותן, \u0003ואין עושין סעודת אירוסין.\u0004 הרי שמותר לעשות אירוסין אפילו בזמן אבילות חמורה שאסור לכבס!","ומתרצים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 שאירוסין מותרים, הרי זה \u0003קודם\u0004 ל\u0003קודם תניא\u0004 \u0005[שנויה],\u0006 כלומר, לא קודם תשעה באב בשבוע שחל בו אלא קודם שבוע זה, מראש חודש אב שאז מותר לכבס.","\u0003אמר רבא: וקודם\u0004 ל\u0003קודם נמי\u0004 \u0005[גם כן]\u0006 יש להקשות באותה דרך: הרי \u0003קל וחומר\u0004 הוא; \u0003ומה במקום שאסור לישא וליתן\u0004 מראש חדש אב ואילך — \u0003מותר ליארס, מקום שמותר לישא וליתן — אינו דין שמותר ליארס?!\u0004","ומשום קושי זה \u0003לא תימא\u0004 \u0005[תאמר]\u0006 ש\u0003ר' יוסי אומר כל הנשים יתארסו\u0004 בתוך שלושה חודשים, \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003כל הנשים ינשאו.\u0004"],["ושואלים: אם כך לכל הנשים, שר' יוסי מתיר להינשא מיד, \u0003ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו]\u0006 \u0003לר' יוסי\u0004 טעם זה שצריכה להמתין כדי שיוכלו \u0003להבחין\u0004 בין ילד של ראשון לשל שני, וכל הנוגע בו?","ומשיבים: אמנם \u0003לית ליה\u0004 \u0005[אין לו],\u0006 אינו חושש לכך. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003לעולם\u0004 אפשר לפרש כי \u0003אית ליה\u0004 \u0005[יש לו],\u0006 הוא מקבל הלכה זו, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך, \u0003ר' יוסי אומר: כל ארוסות\u0004 אם היו \u0003גרושות ינשאו.\u0004 שכיון שהיא ארוסה ואין חשש שהיא מעוברת — רשאית להינשא מיד.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003היינו\u0004 \u0005[הרי זו]\u0006 שיטת \u0003ר' יהודה,\u0004 ומה איפוא ההבדל ביניהם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין \u0003נשואה\u0004 הבאה \u0003ליארס. ר' יהודה סבר: נשואה מותרת ליארס,\u0004 כיון שאינה נישאת, אין איפוא חשש שמא תתעבר. \u0003ור' יוסי סבר: נשואה אסורה ליארס,\u0004 שגזרו אירוסין משום נישואין.","\u0003ו\u0004שואלים: האם \u0003סבר ר' יוסי\u0004 כי \u0003נשואה אסורה ליארס? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: כל הנשים יתארסו, חוץ מן האלמנה מפני האיבול\u0004 (אבילות על בעלה), \u0003וכמה\u0004 תמתין בשל ה\u0003איבול שלה — שלשים יום. וכולן לא ינשאו עד שיהו להן שלשה חדשים.\u0004","ושואלים: \u0003האי, מאי קושיא\u0004 \u0005[\u0006ברייתא \u0005זו, מה קושיה]\u0006 יש ממנה לענייננו? \u0003אילימא דקתני\u0004 \u0005[אם תאמר\u0006 ממה \u0005ששנה\u0006 בה\u0005]\u0006 ש\u0003ר' יוסי אומר: כל הנשים יתארסו,\u0004 שכולל גם נשים נשואות — \u0003מי אלימא ממתניתין\u0004 \u0005[האם תקיפה\u0006 וברורה היא יותר \u0005ממשנתנו]\u0006 שגם בה נאמר בלשון זו, \u0003דאוקימנא\u0004 \u0005[שהעמדנו]\u0006 את משמעות הלשון \u0003בארוסות גרושות\u0004 ש\u0003ינשאו,\u0004 ואם כן \u0003הכא נמי\u0004 \u0005[כאן\u0006 בברייתא \u0005גם כן]\u0006 נפרש: \u0003כל ארוסות\u0004 אם היו \u0003גרושות ינשאו,\u0004 ואין כאן קושיה, שבנשואין כולם סבורים שמותר מיד.","\u0003אלא\u0004 הקושי הוא \u0003מסיפא\u0004 \u0005[מן הסוף],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 בו: \u0003וכולן לא ינשאו עד שיהו להן שלשה חדשים.\u0004 ונדייק מכאן: \u0003אינסובי\u0004 \u0005[להינשא]\u0006 \u0003הוא\u0004 ש\u0003לא, הא איתרוסי\u0004 \u0005[הרי להתארס] —\u0006 \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר\u0005]\u0006 אפילו לנשואה!","\u0003אמר רבא: תריץ ואימא הכי\u0004 \u0005[תרץ ואמור כך],\u0006 תקן את הגירסה, \u0003ר' יוסי אומר: כל ארוסות\u0004 אם היו \u0003גרושות ינשאו, חוץ מן\u0004 הארוסה \u0003האלמנה, מפני האיבול. וכמה\u0004 זמן \u0003איבול שלה — שלשים יום. ונשואות לא יתארסו עד שיהא להן שלשה חדשים.\u0004","לגופה של הלכה זו שואלים: \u0003ואלמנה מן האירוסין מי אית\u0004 \u0005[האם יש]\u0006 \u0003לה איבול? והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא בר אמי\u0004 ברייתא זו: מתה \u0003אשתו\u0004 ה\u0003ארוסה\u0004 לו — \u0003לא אונן\u0004 (אינו נוהג במנהגי אבילות שלפני הקבורה) עליה, \u0003ולא מיטמא לה\u0004 אם כהן הוא. \u0003וכן היא לא אוננת ולא מיטמאה לו,\u0004 שאינה מחוייבת להתעסק בקבורתו אם מת. \u0003מתה — אינו יורשה. מת הוא — גובה\u0004 את \u0003כתובתה\u0004 מנכסיו! ואם כן ודאי אין לומר שדיבר ר' יוסי בארוסות אלא בנשואות.","\u0003אלא\u0004 יש לתרץ את קושיית רב חסדא מדוע אוסר ר' יוסי לאלמנה להתארס אף שבאבל על החורבן מותר הדבר, ולומר כי \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין אירוסין בזמן אבילות זו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מראש חדש\u0004 אב \u0003ועד התענית\u0004 בתשעה בו \u0003העם ממעטין מעסקיהן, מלישא ומליתן, מלבנות\u0004 בית חדש \u0003ו\u0004מ\u0003לנטוע\u0004 נטיעה חדשה, \u0003ומליארס ומלישא\u0004 אשה. \u0003שבת\u0004 (שבוע) \u0003שחל תשעה באב בתוכה — אסור לספר ולכבס, ואסור ליארס. ויש אומרים: כל החדש אסור.\u0004 משמע שיש תנא האוסר אירוסין באבילות זו, ולא קשה על ר' יוסי שאוסר אירוסין באבילות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: ממאי\u0004 \u0005[ממה,\u0006 מהיכן\u0005]\u0006 אתה יודע שמה שנאמר שם \u0003ליארס\u0004 כוונתו \u0003ליארס ממש,\u0004 כלומר, עצם האירוסין (הקידושין), \u0003דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא כי \u0003למיעבד\u0004 \u0005[לעשות]\u0006 \u0003סעודת אירוסין הוא\u0004 ש\u0003אסור, הא\u0004 \u0005[הרי]\u0006 \u0003ליארס\u0004 בלבד — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר הדבר\u0005].\u0006","ומקשים עליו: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, מה שאמרו שנמנעים \u0003מלישא\u0004 נשים תצטרך גם כן לפרש \u0003לינשא נמי\u0004 \u0005[גם\u0006 כן\u0005]\u0006 הכוונה \u0003למיעבד\u0004 \u0005[לעשות]\u0006 \u0003סעודת נשואין הוא\u0004 ש\u0003אסור, הא\u0004 \u0005[הרי]\u0006 \u0003לישא\u0004 בלא סעודה \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר הדבר\u0005],\u0006 ובודאי אסור לאבל לישא אשה אפילו בלי סעודה? ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003נשואין בלא סעודה — איכא\u0004 \u0005[יש]\u0006 \u0003שמחה\u0004 בעצם הנישואין, \u0003אלא אירוסין בלא סעודה — מי איכא\u0004 \u0005[האם יש]\u0006 \u0003שמחה\u0004 בכך?","\u0003אלא אמר רב אשי\u0004 תירוץ באופן אחר: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003אבילות חדשה\u0004 שאשה מתאבלת על בעלה שמת, \u0003מאבילות ישנה\u0004 כגון על חורבן הבית, שיש להקל בה בדברים מסויימים. \u0003ושאני\u0004 \u0005[ושונה]\u0006 \u0003אבילות\u0004 של \u0003רבים מאבילות\u0004 פרטית של ה\u0003יחיד.\u0004 שמאחר שהיא חלה רק על היחיד, אפשר להחמיר בה, אבל אין גוזרים להחמיר הרבה על הרבים.","היו \u0003ארבעה אחין נשואין ארבע נשים ומתו\u0004 כמה מן האחים, \u0003אם רצה הגדול שבהם לייבם את\u0004 כל הנשים היבמות \u0003כולן — הרשות בידו.\u0004","והלכה נוספת: \u0003מי שהיה נשוי לשתי נשים ומת\u0004 ולא השאיר בנים — \u0003ביאתה או חליצתה של אחת מהן\u0004 על ידי היבם \u0003פוטרת\u0004 גם את \u0003צרתה,\u0004 ואין הצרה צריכה לייבם ואף לא לחלוץ."],["\u0003היתה אחת\u0004 מן הנשים \u0003כשרה ואחת פסולה\u0004 לכהונה (כגון שקודם שנישאה לאח המת, היתה נשואה לאחר והתגרשה ממנו), \u0003אם היה חולץ — חולץ לפסולה,\u0004 שאם יחלוץ לכשרה יפסלנה לכהונה, \u0003ואם היה מייבם — מייבם לכשרה.\u0004","שנינו במשנה: \"ארבעה אחין נשואים ארבע נשים ומתו\", ותוהים: \u0003ארבעה אחין\u0004 ומתו, \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הרי אם מתו כולם — מי מייבם? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003ארבעה מאחין,\u0004 מתוך כמה אחים, שמתו.","שנינו במשנה שאם רצה האח הגדול לייבם את כולן \u0003הרשות בידו.\u0004 ושואלים: \u0003ושבקי ליה\u0004 \u0005[ו\u0006כי \u0005מניחים\u0006 אנו \u0005לו]\u0006 לייבם ארבע נשים? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 נאמר בענין ייבום: \u0003\"וקראו לו זקני עירו\"\u0004 (דברים כה, ח), ופירשו כוונתו: \u0003הן ולא שלוחן,\u0004 שאין עושים זאת על ידי שליח, אלא בית דין עצמו. \u0003\"ודברו אליו\"\u0004 (שם) ולא נתפרש בכתוב מה מדברים עמו — \u0003מלמד\u0004 הכתוב \u0003שמשיאין\u0004 (נותנים) \u0003לו עצה הוגנת לו.\u0004","\u0003שאם היה הוא ילד\u0004 (צעיר) \u0003והיא זקנה,\u0004 או \u0003הוא זקן והיא ילדה, אומרין לו: מה לך אצל ילדה\u0004 ואתה זקן, \u0003מה לך אצל זקנה\u0004 ואתה צעיר? \u0003כלך\u0004 (לך לך) \u0003אצל שכמותך, ואל תשים קטטה בביתך.\u0004 שכיון שבני הזוג שונים מאד בגילם יגיעו לבסוף לידי קטטה. משמע שאף שמצד הדין הוא רשאי לייבם, מכל מקום אמרה תורה שלא לעשות כן כדי לא ליצור מראש מצב בעייתי. ואף כאן תמוה, מדוע מתיר בית דין לאדם שיקח ארבע נשים יחד, ויהיה לו קושי לספק את צרכי כולן?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא כש\u0003אפשר ליה\u0004 \u0005[לו]\u0006 מבחינה כלכלית לפרנס ארבע נשים. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו טובא נמי\u0004 \u0005[יותר גם כן],\u0006 שאם ביקשו חכמים לנקוט מספר מרובה, מדוע נקטו ארבע ולא מספר גדול יותר, ומשיבים: \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בדרך אגב במשנה זו: \u0003ארבע — אין\u0004 \u0005[כן],\u0006 \u0003טפי\u0004 \u0005[יותר]\u0006 מזו — \u0003לא, כי היכי דנמטייה\u0004 \u0005[כדי שתגיע]\u0006 לכל אשה לפחות פעם אחת \u0003עונה\u0004 של תשמיש \u0003ב\u0004תוך כל \u0003חדש.\u0004 שאם הוא נוהג כתלמיד חכם ומשמש מיטתו פעם בשבוע, הרי הוא יכול לחלק תשמישו בין הנשים, שלפחות פעם אחת בחודש יהיה מצוי אצל כל אחת מהן. ואם נושא יותר מארבע נשים — לא יוכל לספק את כולן מבחינה זו.","שנינו במשנה: \u0003מי שהיה נשוי\u0004 שתי נשים ומת — אין מייבמים את שתי נשיו, אלא מייבם לאחת וחולץ לשניה. ושואלים לגוף ההלכה: \u0003ונייבם לתרוייהו\u0004 \u0005[ושייבם את שתיהן]!\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אשר לא יבנה את בית אחיו\"\u0004 (שם ט), ומדיוק הלשון נלמד: \u0003בית אחד הוא בונה, ואין\u0004 הוא \u0003בונה שני בתים.\u0004 שאשתו של אדם קרויה \"ביתו\", והרי יש לו לבנות בית אחד בלבד.","\u0003ו\u0004שואלים: למדנו שאין מייבמים שתי נשים מבית אחד, אבל מדוע לא \u0003נחלוץ לתרוייהו\u0004 \u0005[לשתיהן]?!\u0006 \u0003אמר מר זוטרא בר טוביה: אמר קרא\u0004 \u0005[הכתוב],\u0006 שאחרי החליצה אומרים: \u0003\"בית חלוץ הנעל\"\u0004 (שם), ונדייק מכאן: \u0003בית אחד הוא חולץ, ואין חולץ שני בתים.\u0004","ושואלים: \u0003ונייבם לחדא ונחלוץ לחדא\u0004 \u0005[וייבם לאחת ויחלוץ לאחת],\u0006 ואז גם בייבום וגם בחליצה יהיה רק בית אחד! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ו\u0003אם לא יחפץ\"\u0004 (שם ז), משמע: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003חפץ — ייבם,\u0004 כלומר, האפשרות בידו לייבם. ומכאן אנחנו למדים כלל: \u0003כל העולה ליבום — עולה לחליצה, וכל שאין עולה לייבום — אין עולה לחליצה.\u0004 וכיון שאינו יכול לייבם את השניה גם אינו חולץ לה.","\u0003ועוד\u0004 טעם: \u0003שלא יאמרו: בית — מקצתו בנוי ומקצתו חלוץ.\u0004 ושואלים: \u0003ויאמרו!\u0004 ומה בכך? ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 היה נשמר תמיד הסדר ש\u0003מייבם\u0004 תחילה \u0003והדר חליץ\u0004 \u0005[ואחר כך חולץ] —\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 לא היה חשש בדבר. \u0003אלא\u0004 יש לחשוש \u0003דלמא חליץ והדר מייבם\u0004 \u0005[שמא\u0006 קודם \u0005יחלוץ ואחר כך ייבם]\u0006 \u0003ו\u0004אם עושה כן \u0003קם ליה\u0004 \u0005[עומד הוא]\u0006 \u0003ב\u0004איסור \u0003\"לא יבנה\",\u0004 שכיון שחלץ לאחת, שוב \"לא יבנה את בית אחיו\" (שם ט).","ושואלים עוד: מאחר שדייקנו מהכתוב שמצות ייבום היא רק באשה אחת \u0003ואימא\u0004 \u0005[ואמור\u0006 כך\u0005]:\u0006 \u0003כי איכא חדא\u0004 \u0005[כאשר יש\u0006 רק אלמנה \u0005אחת] —\u0006 \u0003תתקיים מצות יבום,\u0004 ואולם \u0003כי איכא תרתי\u0004 \u0005[כאשר יש שתים]\u0006 \u0003לא תתקיים\u0004 ולא תחול \u0003מצות יבום\u0004 כלל, אפילו באחת מהן, ותתבטל במקרה זה!","ומשיבים: \u0003אם כן\u0004 דין \u0003צרת ערוה דאסר רחמנא\u0004 \u0005[שאסרה התורה]\u0006 \u0003למה לי? השתא תרתי בעלמא אמרת\u0004 \u0005[עכשיו,\u0006 הרי \u0005שתי\u0006 נשים \u0005סתם\u0006 שאין אחת מהן ערוה \u0005אומר אתה]\u0006 כי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני חליצה ויבום נינהו\u0004 \u0005[הן]\u0006 — \u0003צרת ערוה מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר?","ודוחים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא? אצטריך\u0004 \u0005[נצרך]\u0006 הדבר להיאמר דווקא במקרה זה, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי ה\u0003ערוה אבראי קיימא\u0004 \u0005[בחוץ עומדת],\u0006 שכיון שהיא ערוה עליו ואינו רשאי לשאתה, הרי היא כאילו איננה מצווה כלל, והיא מחוץ לגדר הייבום, ואם כן אין לפניו שתי נשים מבית אחד, אלא רק אשה אחת (הצרה) הראויה לייבום, \u0003ותתייבם צרתה —\u0004 על כן \u0003קא משמע לן דאסירא\u0004 \u0005[השמיע לנו\u0006 הכתוב \u0005ש\u0006היא \u0005אסורה].\u0006","\u0003אלא,\u0004 יש לדחות את הביאור הזה, ולומר: כי \u0003\"יבמתו\" \"יבמתו\"\u0004 שנאמר כמה פעמים בענין — \u0003ריבה\u0004 והוסיף, שגם אם נפלו כמה יבמות לפניו — חלה מצות ייבום.","שנינו במשנה: \u0003היתה אחת\u0004 מן היבמות \u0003כשרה\u0004 לכהונה ואחת פסולה — חולץ לפסולה, או מייבם לכשירה. \u0003אמר רב יוסף: כאן שנה רבי,\u0004 כלומר, כאן לימדנו רבי בדרך אגב, ענין נוסף: \u0003לא ישפוך אדם מי בורו\u0004 שאינו נזקק להם, \u0003ו\u0004באותה עת \u0003אחרים צריכים להם.\u0004 שאף כאן, כיון שאם יחלוץ לכשירה יפסול אותה לכהונה, ומאחר שרצונו לפטור את היבמה, מוטב שיחלוץ לפסולה שלא תיפסל על ידי כך יותר, וישאיר את הכשרה במצב שתוכל להינשא גם לכהן.","\u0003המחזיר גרושתו\u0004 לאחר שנישאה לאחר, ונתאלמנה או נתגרשה, ועבר בכך על לא תעשה, \u0003והנושא\u0004 את \u0003חלוצתו,\u0004 שלאחר שחלץ לאשה חזר ונשאה, \u0003והנושא קרובת חלוצתו — יוציא\u0004 (יגרש) את האשה הזו, \u0003והולד,\u0004 אם נולד להם — \u0003ממזר,\u0004 אלו \u0003דברי ר' עקיבא,\u0004 שלדעתו כל הנולד מנישואין שעובר בהם על מצות לא תעשה, ממזר הוא.","\u0003וחכמים אומרים: אין הולד ממזר. ו\u0004אולם \u0003מודים\u0004 חכמים \u0003בנושא קרובת גרושתו,\u0004 כגון אחות גרושתו בחיי אשתו, או אמה או בתה, אפילו לאחר מותה — \u0003שהולד ממזר.\u0004","שואלים: \u0003ו\u0004האם \u0003סבר ר' עקיבא\u0004 כי \u0003הנושא קרובת חלוצתו הולד ממזר? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש, כאן שנה רבי: אחות גרושה\u0004 אסורה על בעלה \u0003מדברי תורה, אחות חלוצה — מדברי סופרים,\u0004 ואין ממזר מדברי סופרים! ומתרצים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003קרובת גרושתו,\u0004 ולא חלוצתו.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר מטעם אחר, \u0003דקתני סיפא\u0004 \u0005[ששנה\u0006 ב\u0005סופה]\u0006 של המשנה: \u0003ומודים בנושא קרובת גרושתו שהולד ממזר. אי אמרת בשלמא איירי\u0004 \u0005[נניח אם אתה אומר\u0006 ש\u0005עסק]\u0006 \u0003בה\u0004 ר' עקיבא בבעיה זו קודם לכן — \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"ומודים\",\u0004 לומר שאף שחלקו עליו בדברים אחרים, בכך הודו לו. \u0003אלא אי אמרת\u0004 ש\u0003לא איירי\u0004 \u0005[עסק]\u0006 \u0003בה,\u0004 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 מובן הלשון \u0003\"ומודים\"\u0004 כאשר הוא עצמו לא הזכיר נושא זה?","ודוחים: מכאן אין ראיה מכרעת, \u0003ודלמא הא קא משמע לן\u0004 \u0005[ושמא\u0006 דבר \u0005זה השמיע לנו]\u0006 שהם מודים ש\u0003יש ממזר מחייבי כריתות,\u0004 שלא רק בנולד מאיסור שיש בו מיתת בית דין, אלא אף העובר בעריות על איסור כרת — הוולד ממזר. ומקשים: \u0003הא קתני לה לקמן\u0004 \u0005[הרי שנה אותה\u0006 ההלכה \u0005להלן]\u0006 במשנה במפורש: \u0003איזהו ממזר — כל שאר בשר שהוא\u0004 אסור \u0003ב\"לא יבא\",\u0004 שאסור באשה משום קירבת משפחה ביניהם ואפילו יש בכך איסור לא תעשה בלבד — הרי הנולד ממנה הוא ממזר, אלו \u0003דברי ר' עקיבא, ר' שמעון התימני אומר: כל שחייבין עליו כרת בידי שמים. והלכה כדבריו.\u0004 ואם כן הרי נאמרה הלכה זו במפורש, ומדוע היה צורך להזכירה גם כאן?","ודוחים: \u0003ודלמא קסתים לן\u0004 \u0005[ושמא\u0006 במשנה זו \u0005סתם לנו]\u0006 ה\u0003תנא כ\u0004דעת \u0003ר' שמעון התימני\u0004, להודיענו שזו הלכה פסוקה. ומשיבים: אם לשם כך שנה הלכה זו, \u0003אם כן ליתני\u0004 \u0005[שישנה]\u0006 \u0003שאר חייבי כריתות,\u0004 ו\u0003קרובת גרושתו למה לי\u0004 להזכיר במיוחד? \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003איירי\u0004 \u0005[עסק,\u0006 דן\u0005]\u0006 \u0003בה\u0004 ר' עקיבא קודם.","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לעולם לא איירי\u0004 \u0005[עסק]\u0006 \u0003בה,\u0004 אלא \u0003ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 ר' עקיבא \u0003מחזיר גרושתו, ונושא חלוצתו, וקרובת חלוצתו — תני נמי\u0004 \u0005[שנה גם כן]\u0006 בידי חכמים \u0003קרובת גרושתו\u0004 שהיא דומה להן.","\u0003אלא\u0004 אנו חוזרים מהסברה הראשונה ומסבירים כך: \u0003קרובת חלוצתו ל\u0004דעת \u0003ר' עקיבא\u0004 אסורה מדברי תורה, ולכן הוולד \u0003הוי\u0004 \u0005[הינו]\u0006 \u0003ממזר. אמר ר' חייא בר אבא אמר ר' יוחנן: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' עקיבא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"בית חלוץ הנעל\"\u0004 (שם כה, י), \u0003הכתוב קראו\u0004 על כל פנים \u0003\"ביתו\".\u0004 כלומר, החלוצה נחשבת כאשתו (כגרושתו) וכיון שהחלוצה נחשבת כגרושתו, לכן דין קרובת חלוצה כדין קרובת גרושה.","\u0003אמר רב יוסף אמר ר' שמעון בר רבי: הכל מודים במחזיר גרושתו\u0004 לאחר שנישאה לאחר,"],["\u0003שהולד\u0004 על כל פנים \u0003פגום לכהונה,\u0004 שאם נולדה בת, הריהי כחללה ואסורה לכהן. ומסבירים: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005],\u0006 למי התכוונו כשאמרו \u0003הכל מודים —\u0004 הכוונה היא ל\u0003שמעון התימני, דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אמר שמעון התימני: אין ממזר מחייבי לאוין, נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003ממזר לא הוי\u0004 \u0005[איננו],\u0006 \u0003פגום מיהא הוי\u0004 \u0005[על כל פנים הריהו],\u0006","ולומדים דבר זה \u0003מקל וחומר מאלמנה.\u0004 כיצד? \u0003ומה אלמנה לכהן גדול, שאין איסורה שוה בכל\u0004 שהרי האיסור לשאת אלמנה מיוחד רק לאדם אחד, לכהן הגדול, ובכל זאת \u0003בנה\u0004 הנולד ממנו בנישואי עבירה \u0003פגום\u0004 לכהונה והוא חלל — \u0003זו\u0004 הגרושה שהחזירה, \u0003שאיסורה שוה בכל, אינו דין שבנה פגום\u0004 לכהונה?","ומקשים: \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את הראיה הזו, ולומר: \u0003מה לאלמנה — שכן היא עצמה מתחללת,\u0004 ואילו גרושה שהחזירה בעלה איננה מתחללת על ידי חזרתה לבעלה הראשון.","\u0003ועוד: \"היא תועבה\"\u0004 (דברים כד, ד) \u0003כתיב\u0004 \u0005[נאמר]\u0006 במחזיר גרושתו, ולשון \"היא\" באה לצמצם את הדבר וללמד: \u0003ואין בניה תועבין.\u0004","\u0003ועוד, תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 במפורש להיפך: \u0003המחזיר גרושתו, והנושא חלוצתו, והנושא קרובת חלוצתו, ר' עקיבא אומר: אין לו בה קדושין,\u0004 שהקידושין אינם תופסים בה כלל, \u0003ו\u0004ממילא \u0003אינה צריכה הימנו\u0004 (ממנו) \u0003גט, והיא פסולה, וולדה פסול, וכופין אותו להוציא\u0004 (לגרש). \u0003וחכמים אומרים:\u0004 בכל אלה \u0003יש לו בה קדושין, ו\u0004לכן \u0003צריכה הימנו גט\u0004 להתירה לאחרים, \u0003והיא כשרה וולדה כשר.\u0004","ונברר: זה שאמרנו שוולדה כשר, \u0003למאן\u0004 \u0005[למי]\u0006 כשר? \u0003לאו\u0004 \u0005[האם לא]\u0006 שהוא כשר \u0003לכהונה?\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא שכשר \u0003לקהל.\u0004 כלומר, שאיננו ממזר, ומותר לבוא בקהל ה'. ותוהים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מה שנאמר בברייתא \u0003היא כשרה, למאן\u0004 \u0005[למי]\u0006 היא כשרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא כשרה \u0003לקהל,\u0004 שמותר לה להינשא לישראל — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, וכי \u0003משום דזניא\u0004 \u0005[שזנתה]\u0006 \u0003אפסלה\u0004 \u0005[נפסלה]\u0006 \u0003לקהל?!\u0004 שהרי אשה זונה אינה פסולה לכל ישראל. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא שכשירה \u0003ל\u0004\u0003כהונה,\u0004","\u0003ומדהיא\u0004 \u0005[ומ\u0006כיון \u0005שהיא]\u0006 כשירה ומשמעו — \u0003לכהונה, ולדה נמי\u0004 \u0005[גם כן]\u0006 שאמרו שכשר — כשר \u0003לכהונה!\u0004 ודוחים: \u0003מידי איריא\u0004 \u0005[וכי שייכים\u0006 הדברים\u0005]?\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כ\u0006מו \u0005שהוא וזה כ\u0006מו \u0005שהוא]\u0006 ומה שאמרו היא כשירה, כוונתו כשירה אכן לכהונה, אולם וולדה כשר —הכוונה שכשר לקהל.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש, \u0003דקתני רישא\u0004 \u0005[ששנה\u0006 ב\u0005ראשה]\u0006 של ברייתא זו: \u0003היא פסולה וולדה פסול.\u0004 ונברר: \u0003היא פסולה למאן\u0004 \u0005[למי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שפסולה \u0003לקהל,\u0004 וכי \u0003משום דזניא\u0004 \u0005[שזנתה]\u0006 \u0003אפסלה ליה\u0004 \u0005[נפסלה לו]\u0006 \u0003לקהל?! אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא שפסולה \u0003לכהונה.\u0004","ובהמשך נאמר \u0003וולדה פסול, למאן\u0004 \u0005[למי]\u0006 פסול? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 פסול \u0003לכהונה,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 נלמד מכאן כי \u0003לקהל\u0004 הוא \u0003כשר? האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' עקיבא\u0004 עצמו במשנתנו ש\u0003הולד ממזר\u0004 ופסול לבוא בקהל! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן שפסול אף \u0003לקהל,\u0004 שאף שאמרו יחד \"היא פסולה וולדה פסול\" אין מדובר באותו ענין עצמו.","\u0003ומדרישא הא כדאיתא והא כדאיתא\u0004 \u0005[ומ\u0006כיון \u0005ש\u0006ב\u0005ראשה\u0006 של הברייתא הסברנו \u0005זה כ\u0006מו \u0005שהוא וזה כ\u0006מו \u0005שהוא]\u0006 ולא באותו ענין, \u0003סיפא נמי הא כדאיתא והא כדאיתא\u0004 \u0005[סופה גם כן זו כ\u0006מו \u0005שהיא וזו כ\u0006מו \u0005שהיא].\u0006","\u0003ו\u0004מה שהקשינו מדיוק הפסוק \u0003\"היא תועבה\"\u0004 ש\"היא\" בא למעט, כוונתו \u0003נמי\u0004 \u0005[גם כן]\u0006 כך: \u0003היא תועבה ואין צרתה תועבה,\u0004 שאם נפלו שתיהן לייבום, גרושה זו פסולה ואין הצרה פסולה לייבום, \u0003אבל בניה\u0004 אפשר לומר שהם \u0003תועבין.\u0004","\u0003אלא\u0004 הקל וחומר שנאמר לגבי \u0003אלמנה קשיא\u0004 \u0005[\u0006נשאר \u0005קשה]:\u0006 \u0003מה לאלמנה — שכן היא עצמה מתחללת!\u0004","\u0003אלא\u0004 לא כך נאמרו הדברים, \u0003אי אתמר הכי אתמר\u0004 \u0005[אם נאמר כך נאמר]\u0006 הדבר: \u0003אמר רב יוסף אמר ר' שמעון ברבי: הכל מודים בבא על חייבי כריתות שהולד פגום. מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 \u0003הכל מודים,\u0004 זה \u0003ר' יהושע. דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אמר ר' יהושע: אין ממזר מחייבי כריתות,\u0004 אלא מחייבי מיתות בית דין בלבד, \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003ממזר לא הוי\u0004 \u0005[איננו] —\u0006 \u0003פגום מיהא הוי\u0004 \u0005[על כל פנים הריהו],\u0006","ונלמד את הדבר \u0003מקל וחומר מאלמנה: ומה אלמנה לכהן גדול, שאין איסורה שוה בכל — בנה פגום, זו שאיסורה שוה בכל — אינו דין שבנה פגום.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כפי שהקשינו קודם: \u0003מה לאלמנה שכן היא עצמה מתחללת\u0004 — אין זו קושיה, כי \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003כיון שבעלה\u0004 אדם שעבר בכך על איסור כרת, \u0003עשאה זונה,\u0004 ובאמת היא מתחללת מכהונה. ואין פירכא לקל וחומר זה.","כיון שעסקנו בבעיה זו דנים גם בנושא קרוב לה. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הכל מודים בעבד וגוי הבא על בת ישראל שהולד ממזר.\u0004","\u0003מאן\u0004 \u0005[מי]\u0006 זה \u0003\"הכל מודים\",\u0004 כלומר, מי הוא המודה בזה — \u0003שמעון התימני. דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אמר שמעון התימני\u0004 ש\u0003אין ממזר מחייבי לאוין,\u0004 אלא מחייבי כריתות בלבד — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים בילד הנולד"],["\u0003מחייבי לאוין דתפסי בהו\u0004 \u0005[שתופסים בהם]\u0006 \u0003קדושין,\u0004 שלמרות העבירה הקידושין חלים, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003גוי ועבד, כיון\u0004 ש\u0003לא תפסי בהו\u0004 \u0005[תופסים בהם]\u0006 \u0003קדושין, כחייבי כריתות דמי\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003גוי ועבד הבא על בת ישראל — הולד ממזר. ר' שמעון בן יהודה אומר: אין ממזר אלא ממי שאיסורו איסור ערוה, וענוש כרת.\u0004 משמע שהתנא הסבור שממזר הוא רק זה הנולד מחייבי כריתות (והיא שיטת שמעון התימני), סבור שהנולד מגוי ומעבד איננו ממזר!","\u0003אלא אמר רב יוסף: מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 \u0003\"הכל מודים\"\u0004 שאמרו — \u0003רבי\u0004 הוא, ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003רבי אומר\u0004 כי \u0003אין הדברים הללו\u0004 (במשנה להלן יבמות נב, ב) \u0003אמורים אלא לדברי ר' עקיבא, שהיה\u0004 ר' עקיבא \u0003עושה חלוצה כערוה\u0004 לכל דבר, \u0003וליה לא סבירא ליה\u0004 \u0005[והוא\u0006 עצמו \u0005אינו סבור\u0006 כן\u0005]\u0006 אלא כשמעון התימני, מכל מקום, \u0003בגוי ועבד מודה.\u0004 ומניין לנו דבר זה? \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003רב יצחק בר אבודימי\u0004 שאמר \u0003משום\u0004 \u0005[בשם]\u0006 \u0003רבינו\u0004 (רבי): \u0003גוי ועבד הבא על בת ישראל — הולד ממזר.\u0004","ולגופה של הלכה זו מסופר: \u0003ר' אחא שר הבירה ור' תנחום בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא איש כפר עכו פרוק הנהו שבוייתא דאתו\u0004 \u0005[פדו\u0006 את \u0005אלה השבויות שבאו]\u0006 \u0003מארמון לטבריא\u0004 (טבריה). \u0003הוה חדא דאעברא\u0004 \u0005[היתה אחת\u0006 מהן \u0005שהיתה מעוברת]\u0006 \u0003מגוי, ואתו לקמיה\u0004 \u0005[ובאו לפניו]\u0006 לפני \u0003ר' אמי\u0004 לשאול מה יהיה מעמדו של הילד לכשיוולד. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ר' יוחנן ור' אלעזר ור' חנינא דאמרי\u0004 \u0005[שאמרו]\u0006 כולם: \u0003גוי ועבד הבא על בת ישראל — הולד ממזר.\u0004","\u0003אמר רב יוסף\u0004 כששמע סיפור זה: \u0003רבותא למחשב גברי\u0004 \u0005[\u0006וכי \u0005גדולה\u0006 היא \u0005למנות אנשים]!\u0006 כלומר, וכי על ידי כך שמנה כמה חכמים הסבורים כך, מוכח שזו ההלכה?! \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רב ושמואל בבבל, ור' יהושע בן לוי ובר קפרא בארץ ישראל ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003חלופי\u0004 \u0005[מחליפים,\u0006 מוציאים\u0005]\u0006 בענין זה את \u0003בר קפרא ועיילי\u0004 \u0005[ומכניסים]\u0006 במקומו \u0003זקני דרום, דאמרי\u0004 \u0005[שאומרים]\u0006 כולם: \u0003גוי ועבד הבא על בת ישראל — הולד כשר!\u0004","\u0003אלא אמר רב יוסף:\u0004 שיטה זו בהלכה, שיטת \u0003רבי היא,\u0004 שהוא הסבור שהוולד ממזר והלכה כמותו בכל מקום. ועל דעתו סמכו ולא על שיטות האמוראים. \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשמו של \u0003ר' יצחק בר אבודימי,\u0004 שאמר: \u0003משום רבינו\u0004 (רבי) \u0003אמרו: גוי ועבד הבא על בת ישראל — הולד ממזר.\u0004","\u0003ר' יהושע בן לוי אומר: הולד מקולקל\u0004 ופסול. ושואלים: \u0003למאן\u0004 \u0005[למי]\u0006 פסול? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 פסול \u0003לקהל — הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' יהושע\u0004 עצמו כי \u0003הולד כשר! אלא\u0004 הכוונה היא שפסול \u0003לכהונה — דכולהו אמוראי דמכשרי\u0004 \u0005[שכל\u0006 ה\u0005אמוראים שמכשירים]\u0006 את הוולד לבוא בישראל \u0003מודו\u0004 \u0005[מודים]\u0006 בכל זאת \u0003שהולד פגום לכהונה.\u0004","ודבר זה נלמד \u0003מקל וחומר מאלמנה.\u0004 והקל וחומר הזה הוא: \u0003מה אלמנה לכהן גדול, שאין איסורה שוה בכל,\u0004 שאינו חל אלא על הכהן הגדול בלבד, בכל זאת \u0003בנה פגום\u0004 לכהונה, \u0003זו\u0004 הנבעלת לגוי \u0003שאיסורה שוה בכל — אינו דין שבנה פגום.\u0004","ומקשים: \u0003מה לאלמנה לכהן גדול — שכן היא עצמה מתחללת\u0004 על ידי ביאה זו! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בנבעלת לגוי, \u0003כיון שנבעלה\u0004 לגוי — \u0003פסלה.\u0004","ש\u0003אמר ר' יוחנן משום ר' שמעון: מנין לגוי ועבד הבא על הכהנת ו\u0004כן \u0003על הלויה, ו\u0004כן \u0003על הישראלית שפסלוה\u0004 לכהונה — \u0003שנאמר: \"ובת כהן כי תהיה אלמנה וגרושה\u0004 וזרע אין לה ושבה אל בית אביה כנעוריה\u0003\"\u0004 (ויקרא כב, יג), ללמד, שרק אם היתה נשואה ל\u0003מי שיש לו אלמנות וגירושין בה,\u0004 שנישואיהם תופסים, זו היא החוזרת לבית אביה כמקודם, \u0003יצאו גוי ועבד שאין להם אלמנות וגירושין בה,\u0004 שאין כל משמעות הלכתית של נישואין לקשר שביניהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003מאי חזית דסמכת\u0004 \u0005[מה ראית שאתה סומך]\u0006 על דבריו של \u0003רב דימי\u0004 במסורת זו, \u0003סמוך\u0004 על דבריו של \u0003רבין! דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר: ר' נתן ור' יהודה הנשיא מורים בה\u0004 בוולד הנולד מן הגוי — \u0003להיתירא\u0004 \u0005[להיתר].\u0006 \u0003ו\u0004הרי \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 \u0003ר' יהודה הנשיא —\u0004 הלא \u0003רבי\u0004 הוא. משמע שיש סבורים שאף הוא פסק להיתר.","ומעירים, \u0003ואף רב\u0004 היה \u0003מורה בה,\u0004 בהלכה זו, \u0003היתירא\u0004 \u0005[היתר].\u0006 \u0003דההוא דאתא לקמיה\u0004 \u0005[ש\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003רב, אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם לרב: \u0003גוי ועבד הבא על בת ישראל מהו\u0004 דינו של הנולד מביאה זו? ושאלה זו שאל לגבי עצמו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003הולד כשר. אמר ליה\u0004 \u0005[לו]:\u0006 אם סבור אתה כן — \u0003הב לי ברתך\u0004 \u0005[תן לי\u0006 את \u0005בתך]\u0006 לאשה, שאם כשר אני — מדוע לא אשא אותה? אמר לו: \u0003לא יהיבנא\u0004 \u0005[אינני נותן]\u0006 \u0003לך.\u0004","\u0003אמר שימי בר חייא\u0004 נכדו של רב \u0003לרב: אמרי אינשי\u0004 \u0005[אומרים אנשים]\u0006 בפתגם מקובל: \u0003גמלא במדי אקבא רקדא\u0004 \u0005[גמל במדי\u0006 בתוך \u0005קב\u0006 קטן הוא \u0005רוקד].\u0006 שאנשים מספרים לפעמים סיפורי גוזמאות על דבר המתרחש במקום רחוק, אולם: \u0003הא קבא, והא גמלא, והא מדי\u0004 — \u0003ולא רקדא\u0004 \u0005[הרי הקב, והרי הגמל, והרי מדי —\u0006 \u0005ואינו רוקד].\u0006 שאף כאן, במקרה הזה, כאשר העמיד זה את דבריך לנסיון בפועל — אין אתה עומד בדעתך!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 גם \u0003אי ניהוי\u0004 \u0005[אם יהיה]\u0006 אותו אדם גדול \u0003כיהושע בן נון לא יהיבנא ליה ברתי\u0004 \u0005[אינני נותן לו\u0006 את \u0005בתי],\u0006 שאין אני רוצה בו מטעמים אחרים, אבל אין אני משנה את דעתי בהלכה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הוה\u0004 \u0005[אם היה]\u0006 אותו אדם \u0003כיהושע בן נון, אי מר לא יהיב ליה\u0004 \u0005[אם אדוני לא יתן לו\u0006 בתו\u0005]\u0006 — \u0003אחריני יהבי ליה\u0004 \u0005[אחרים יתנו לו\u0006 את בתם\u0005],\u0006 ואולם \u0003האי\u0004 \u0005[\u0006אדם \u0005זה]\u0006 \u0003אי מר לא יהיב ליה\u0004 \u0005[אם אדוני לא יתן לו\u0006 בתו\u0005]\u0006 — \u0003אחריני לא יהבי ליה —\u0004 \u0005[אחרים לא יתנו לו],\u0006 שיחששו לפגם משפחה.","\u0003לא הוה קאזיל מקמיה\u0004 \u0005[הלך מלפניו]\u0006 אותו שואל, שעמד והפציר ברב. \u0003יהיב ביה עיניה ושכיב\u0004 \u0005[נתן בו\u0006 רב את \u0005עיניו ומת]\u0006 אותו אדם. מכל מקום ראינו שרב התיר במקרה זה הלכה למעשה.","ומוסיפים: \u0003ואף רב מתנה מורה בה להיתירא\u0004 \u0005[להיתר],\u0006 \u0003ואף רב יהודה מורה בה להיתירא\u0004 \u0005[להיתר].\u0006 \u0003דכי אתא לקמיה\u0004 \u0005[שכאשר בא\u0006 אדם כזה \u0005לפני]\u0006 \u0003רב יהודה, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל איטמר\u0004 \u0005[לך התחבא],\u0006 כלומר, אל תספר בן מי אתה, כדי שלא יימנעו אנשים מלתת לך את בנותיהם, \u0003או נסיב\u0004 \u0005[תישא\u0006 אשה\u0005]\u0006 \u0003בת מינך\u0004 שגם היא נולדה לעבד או לגוי, משמע שראה אותו ככשר, לכן נתן לו עצה להסתיר את מוצאו, \u0003ו\u0004כן \u0003כי אתא לקמיה\u0004 \u0005[כאשר\u0006 היה \u0005בא לפני]\u0006 \u0003רבא\u0004 מקרה כזה, \u0003אמר ליה\u0004 \u0005[היה אומר לו]:\u0006 \u0003או גלי\u0004 \u0005[גלה]\u0006 למקום שאין מכירים את משפחתך, \u0003או נסיב\u0004 \u0005[שא\u0006 אשה\u0005]\u0006 \u0003בת מינך.\u0004","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003בני\u0004 המקום \u0003בי מיכסי לרבה\u0004 שאלה זו: \u0003מי שחציו עבד וחציו בן חורין, הבא על בת ישראל, מהו\u0004 דינו של הנולד מביאה זו? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003השתא\u0004 \u0005[עכשיו],\u0006 הרי, אם היה אותו עבד \u0003עבד כולו, אמרינן\u0004 \u0005[אומרים אנו]\u0006 שהוולד \u0003כשר — חציו מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהוא כשר?","\u0003אמר רב יוסף: מרא דשמעתא\u0004"],["\u0003מנו\u0004 \u0005[בעליה,\u0006 קובעיה, \u0005של הלכה זו, מי הוא] —\u0006 \u0003רב יהודה,\u0004 שאמרנו שהורה להיתר בבן ישראלית מגוי ומעבד, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה\u0004 עצמו: \u0003מי שחציו עבד וחציו בן חורין הבא על בת ישראל — אותו ולד אין לו תקנה\u0004 לבוא בקהל ישראל!","ודוחים: משם אין להוכיח, \u0003כי איתמר\u0004 \u0005[כאשר נאמר]\u0006 דין זה של \u0003רב יהודה\u0004 הרי זה באופן מסויים, ו\u0003כגון דקדיש\u0004 \u0005[שקידש]\u0006 אותו שהיה חציו עבד \u0003בת ישראל\u0004 ולאחר מכן בא עליה, שעל ידי קידושיו נוצרה בעיה מיוחדת, שהרי הוא חציו בן חורין, ומצד זה יחולו הקידושין באותה אשה, אולם כאשר בא עליה \u0003נמצא צד עבדות שבו משתמש באשת איש —\u0004 ולכן הוולד פסול. אבל אם רק בא עליה בלא קדושין, כיון שהיא פנויה — הוולד כשר.","ומקשים: \u0003והאמרי נהרדעי\u0004 \u0005[והרי אומרים\u0006 חכמי \u0005נהרדעא]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יעקב: לדברי הפוסל\u0004 וולד ישראלית הנולד מן הגוי — \u0003פוסל אפילו בפנויה, לדברי המכשיר — מכשיר אפילו באשת איש\u0004 שבא עליה גוי.","\u0003ושניהם,\u0004 הפוסל והמכשיר, \u0003לא למדוה אלא מ\u0004דין \u0003אשת אב. מאן דפסיל סבר\u0004 \u0005[מי שפוסל סבור]\u0006 כך: \u0003מה אשת אב,\u0004 ש\u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קדושין, הולד\u0004 מביאה כזו \u0003ממזר, אף כל\u0004 אשה ש\u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קדושין הולד ממזר,\u0004 ובכלל זה — בן גוי, שאין קידושין תופסים בגוי.","\u0003ומאן דמכשר סבר\u0004 \u0005[ומי שמכשיר סבור]:\u0006 \u0003מה אשת אב, דלדידיה\u0004 \u0005[שעבורו],\u0006 עבור הבן, \u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קדושין,\u0004 אבל \u0003לאחריני תפסי\u0004 \u0005[לאחרים תופסים],\u0006 \u0003בה קדושין\u0004 אם היא אלמנה או גרושה, ואם בא עליה הוולד ממזר, \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003גוי ועבד דלא תפסי בהו\u0004 \u0005[שאין תופסים בהם]\u0006 \u0003קדושין כלל\u0004 שאין הוולד ממזר. ואם כן אין לחלק לענין זה בין פנויות ונשואות.","\u0003אלא,\u0004 יש להסביר באופן אחר: \u0003כי איתמר\u0004 \u0005[כאשר נאמר]\u0006 בשם \u0003רב יהודה,\u0004 היה זה \u0003כגון שבא\u0004 מי שחציו עבד \u0003על אשת איש,\u0004 שאף שמצד היותו עבד איננו פוסל, אבל הואיל ש\u0003נמצא צד חירות שבו משתמש באשת איש,\u0004 הרי בשל כך הוולד הוא ממזר.","\u0003אמר רבינא, אמר לי רב גזא: איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ר' יוסי בר אבין לאתרין\u0004 \u0005[למקומנו]\u0006 \u0003והוה עובדא\u0004 \u0005[והיה מעשה]\u0006 \u0003בפנויה\u0004 שבא עליה גוי \u0003ואכשר\u0004 \u0005[והכשיר]\u0006 את הוולד, ומקרה אחר היה \u0003ב\u0004גוי שבא על \u0003אשת איש — ופסיל\u0004 \u0005[ופסל]\u0006 ר' יוסי בר אבין את הוולד. \u0003אמר רב ששת: לדידי\u0004 \u0005[לי עצמי]\u0006 \u0003אמר לי רב גזא: לא ר' יוסי בר אבין הוה\u0004 \u0005[היה\u0006 זה\u0005]\u0006 \u0003אלא ר' יוסי בר' זבידא הוה\u0004 \u0005[היה],\u0006 \u0003ואכשר\u0004 \u0005[והכשיר]\u0006 \u0003בין בפנויה בין באשת איש. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה לרבינא: איקלע\u0004 \u0005[הזדמן]\u0006 \u0003אמימר לאתרין\u0004 \u0005[למקומנו]\u0006 \u0003ואכשר\u0004 \u0005[והכשיר]\u0006 את הוולד \u0003בין בפנויה בין באשת איש.\u0004","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003גוי ועבד הבא על בת ישראל — הולד כשר, בין בפנויה בין באשת איש.\u0004","אגב דיון זה בכשרות בן הגוי מן הישראלית, מוסרים כי \u0003רבא אכשריה\u0004 \u0005[הכשיר]\u0006 את \u0003רב מרי בר רחל\u0004 שהיה בנה של ישראלית שבא עליה גוי \u0003ומנייה בפורסי\u0004 \u0005[ומינה אותו\u0006 להיות \u0005בין הממונים]\u0006 של \u0003בבל, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם],\u0006 שמן הכתוב \u0003\"שום תשים עליך מלך\u0004 אשר יבחר ה' אלהיך בו מקרב אחיך תשים עליך מלך\u0003\"\u0004 (דברים יז, טו) למדים, שלא רק מלך, אלא \u0003כל משימות\u0004 (תפקידים ומינויים) \u0003שאתה משים אל יהו אלא מקרב אחיך\u0004 ולא ממוצא גוי — \u0003האי\u0004 \u0005[זה],\u0006 \u0003כיון\u0004 ש\u0003אמו מישראל — \"מקרב אחיך\" קרינן ביה\u0004 \u0005[קוראים אנו בו],\u0006 וכשר.","מסופר: \u0003עבדיה\u0004 \u0005[עבדו]\u0006 של \u0003ר' חייא בר אמי אטבלה לההיא גויה לשם אנתתא\u0004 \u0005[הטביל גויה אחת לשם אשה\u0006 אישות\u0005],\u0006 שהטבילה לשם טהרת נדה. \u0003אמר רב יוסף: יכילנא לאכשורי בה ובברתה\u0004 \u0005[יכול אני להכשיר בה ובבתה]\u0006 שתהיינה שתיהן כשירות לבוא בקהל ישראל.","\u0003בה —\u0004 אני מכשיר שתהיה כגיורת גמורה \u0003כ\u0004דבריו של \u0003רב אסי. ש\u0004\u0003אמר רב אסי\u0004 לגבי אשה שלא היה ברור אם אכן נתגיירה, אבל חיה בתוך עם ישראל ונהגה ככל ישראלית אחרת \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא טבלה לנדותה?\u0004 ומשמע כיון שטבלה לשם טהרה, הרי טבילה זו עולה לה גם לשם גירות.","וכן \u0003בברתה\u0004 \u0005[בבתה]\u0006 אפשר להכשיר מן הטעם ש\u0003גוי\u0004 או \u0003עבד הבא על בת ישראל — הולד כשר.\u0004","ומהו מקור פסק זה של רב אסי — \u0003ההוא\u0004 (אדם מסויים) \u0003דהוו קרו ליה \"בר ארמייתא\"\u0004 \u0005[שהיו קוראים לו \"בן ארמית\",\u0006 גויה\u0005]\u0006 משום שאמו לא טבלה לשם גירות כדין, \u0003אמר רב אסי: מי\u0004 \u0005[האם]\u0006 \u0003לא טבלה לנדותה?\u0004 ומכיון שטבלה — עלתה לה טבילה זו גם לשם גירות. כיוצא בו מסופר: \u0003ההוא\u0004 (אדם מסויים) \u0003דהוו קרו ליה \"בר ארמאה\"\u0004 \u0005[שהיו קוראים לו \"בן הארמי\"\u0006 הגוי\u0005],\u0006 משום שאביו לא טבל כדין לשם גירות. \u0003אמר ר' יהושע בן לוי: מי\u0004 \u0005[האם]\u0006 \u0003לא טבל לקריו?\u0004 וכיון שטבל לשם טהרה מטומאת קריו עלתה לו טבילה זו גם לגירות.","\u0003אמר רב חמא בר גוריא אמר רב: הלוקח\u0004 (הקונה) \u0003עבד מן הגוי\u0004 וכשקונה עבד צריך להטבילו לשם עבדות, שהרי עבד של יהודים חייב גם הוא במצוות מסויימות, \u0003וקדם וטבל לשם בן חורין,\u0004 כלומר, שבטבילתו אמר שהוא רוצה להתגייר, \u0003קנה עצמו\u0004 בטבילה זו להיות \u0003בן חורין\u0004 וישראלי גמור. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הלכה זו —"],["\u0003גוי,\u0004 הלא \u0003גופא לא קני ליה\u0004 \u0005[\u0006את \u0005הגוף\u0006 של העבד \u0005איננו קונה],\u0006 שאנו אומרים שגוי אין לו זכות קניינית בגופו של אדם אחר (גם אם זה עבד) וכל זכותו בעבד אינה אלא ליהנות מעבודתו בלבד, \u0003מאי דקני ליה\u0004 \u0005[מה שקנוי לו]\u0006 \u0003הוא\u0004 מה \u0003דמקני ליה\u0004 \u0005[שמקנה לו]\u0006 \u0003לישראל,\u0004 וכיון שגוף העבד עדיין לא נקנה לקונהו היהודי, אלא רק שיעבוד בלבד הוא שהיה לו בו ולא יותר, \u0003וכיון\u0004 ש\u0003קדם וטבל\u0004 אותו עבד \u0003לשם בן חורין\u0004 — \u0003אפקעיה לשעבודיה\u0004 \u0005[הפקיע את שיעבודו]\u0006 ממנו, על ידי הטבילה שטבל לשם גירות.","ו\u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: הקדש\u0004 שמקדישים חפץ לגבוה, או איסור \u0003חמץ\u0004 שחל על דבר מה, או \u0003שחרור\u0004 של עבד — \u0003מפקיעין\u0004 את הדבר \u0003מידי שעבוד.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב חסדא\u0004 ממה ששנינו בברייתא: \u0003מעשה בבלוריא הגיורת שקדמו עבדיה וטבלו לפניה, ובא מעשה לפני חכמים, ואמרו: קנו\u0004 העבדים את \u0003עצמן\u0004 ונעשו \u0003בני חורין.\u0004 ונדייק: אם טבלו \u0003לפניה,\u0004 לפני שנתגיירה — \u0003אין\u0004 \u0005[כן],\u0006 רק אז הם בני חורין, כיון שלא קנתה את גופם בהיותה גויה, ולא היה לה בהם אלא שיעבוד בלבד, אבל אם היו טובלים \u0003לאחריה — לא!\u0004 שכיון שנתגיירה קנתה אה גופם של עבדיה. מכאן שישראל קונה מגוי קנין הגוף, ולא רק שיעבוד!","\u0003אמר רבא,\u0004 כך יש להבין: אם טבלו \u0003לפניה, בין בסתם\u0004 שטבלו ולא פירשו לשם מה טובלים, \u0003בין\u0004 שטבלו \u0003במפורש\u0004 לשם בני חורין — קנו עצמם להיות בני חורין כישראל. ואם טבלו \u0003לאחריה,\u0004 אם אמרו \u0003במפורש\u0004 שהם טובלים לשם גירות ויהדות — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם טבלו \u0003בסתם לא,\u0004 שיש להניח שטבלו לשם עבדות, ולא לשם שחרור.","\u0003אמר רב אויא: לא שנו אלא בלוקח\u0004 (קונה) עבד \u0003מן הגוי, אבל\u0004 את ה\u0003גוי גופיה קני\u0004 \u0005[עצמו\u0006 הוא \u0005קונה],\u0006 שאם מכר לו הגוי את עצמו, קנה הישראלי את גופו, ולא רק את שיעבודו בלבד.","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וגם מבני התושבים הגרים עמכם מהם תקנו\"\u0004 (ויקרא כה, מה), ולמדים מזה: \u0003אתם קונים מהם\u0004 עבד ואמה, \u0003ולא הם קונים מכם,\u0004 שאין להם זכות וקנין בגופו של העבד העברי שהם קונים, \u0003ו\u0004כן \u0003לא הם קונים זה מזה.\u0004","שנינו שם: \u0003ולא הם קונים מכם.\u0004 ונברר: \u0003למאי\u0004 \u0005[למה\u0006 לאיזה ענין\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003למעשה ידיו\u0004 שאין זכות לגוי לקנות עבד יהודי ולהיות זכאי במעשה ידיו — \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003גוי לא קני ליה\u0004 \u0005[אינו קונה אותו]\u0006 את ה\u0003ישראל למעשה ידיו? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"או לעקר משפחת גר\"\u0004 (שם מז), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"משפחת גר\" — זה הגוי! אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה שלא קונה \u0003לגופיה\u0004 \u0005[את גופו].\u0006 \u0003וקאמר רחמנא\u0004 \u0005[ואמרה תורה]\u0006 באותו אופן \u0003אתם קונים מהם —\u0004 משמע \u0003אפילו גופיה\u0004 \u0005[גופו]\u0006 של האיש קנוי לו לאדוניו היהודי.","\u0003פריך\u0004 \u0005[הקשה]\u0006 על כך \u0003רב אחא: אימא\u0004 \u0005[אמור]\u0006 שהוא קונה את הגוי לא רק \u0003בכספא\u0004 \u0005[בכסף]\u0006 אלא גם על ידי \u0003טבילה\u0004 לשם עבדות, אבל בכסף בלבד אינו קונה אותו קנין גמור ולכן יכול להקדים ולטבול לשם בן חורין! ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה],\u0006 ואין מכאן ראיה.","\u0003אמר שמואל: ו\u0004עצה טובה היא אם רוצה להיות בטוח שלא יטבול העבד לשם שחרור, \u0003צריך לתקפו\u0004 (להחזיקו בכוח) \u0003במים,\u0004 שעושה בו מלאכה בעודו טובל כדי שהטבילה תעלה לשם עבדות ולא לשחרור.","\u0003כי האי\u0004 \u0005[כמו זה]\u0006 המעשה ש\u0003מנימין עבדיה\u0004 \u0005[עבדו]\u0006 של \u0003רב אשי בעא לאטבולי\u0004 \u0005[היה צריך להטביל\u0006 אותו\u0005],\u0006 \u0003מסריה ניהלייהו\u0004 \u0005[מסר אותו להם]\u0006 \u0003לרבינא ולרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003חזו, דמינייכו קבעית ליה\u0004 \u0005[ראו, שמכם אני תובע אותו],\u0006 שאתם צריכים לדאוג שתעשו זאת כראוי, ושלא תגרמו לי נזק. \u0003רמו ליה ארויסא בצואריה\u0004 \u0005[שמו לו\u0006 כעין \u0005רסן בצווארו],\u0006 ובזמן שירד לטבול \u0003ארפו ליה וצמצמו ליה\u0004 \u0005[הירפו אותו ו\u0006אחר כך \u0005מתחו אותו].\u0006","ומסבירים: \u0003ארפו ליה\u0004 \u0005[הירפו אותו]\u0006 תחילה \u0005—\u0006 \u0003כי היכי דלא להוי\u0004 \u0005[כדי שלא תהיה]\u0006 \u0003חציצה\u0004 בטבילה. \u0003צמצמו ליה\u0004 \u0005[מתחו\u0006 וקשרו \u0005אותו]\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לקדים ולימא להו\u0004 \u0005[\u0006יוכל \u0005להקדים ולומר להם]:\u0006 \u0003לשם בן חורין אני טובל. בהדי דדלי רישיה ממיא\u0004 \u0005[כאשר הרים את ראשו מן המים]\u0006 \u0003אנחו ליה זולטא דטינא ארישיה\u0004 \u0005[הניחו לו סל טיט על ראשו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אמטי לבי מרך\u0004 \u0005[לך הבא\u0006 זאת \u0005לבית אדוניך]\u0006 כסימן לעבדות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: חזי מר הני דבי\u0004 \u0005[יראה אדוני אותם\u0006 אנשים \u0005מבית]\u0006 \u0003פפא בר אבא, דיהבי זוזי לאינשי לכרגייהו ומשעבדי בהו\u0004 \u0005[שנותנים כסף\u0006 עבור \u0005אנשים ל\u0006צורך \u0005מיסי המלוכה\u0006 שלא שילמו אותם אנשים ובשל כך אסרו אותם, \u0005ומשתעבדים בהם]\u0006 שיעבדו עבורם תמורת תשלום המיסים ששילמו עבורם. והשאלה היא: \u0003כי נפקי צריכי גיטא דחירותא\u0004 \u0005[כאשר הם\u0006 מסיימים את עבודתם ו\u0005יוצאים,\u0006 האם הם \u0005צריכים\u0006 אז \u0005שטר שחרור],\u0006 \u0003או לא?\u0004 כלומר, האם קנו את האנשים הללו לגופם כעבדים הצריכים שטר שחרור?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איכו שכיבי\u0004 \u0005[אילו הייתי מת]\u0006 \u0003לא אמרי לכו\u0004 \u0005[הייתי אומר לכם]\u0006 \u0003הא מילתא\u0004 \u0005[את הדבר הזה],\u0006 כלומר, טוב עשית ששאלת, ונתת לי הזדמנות לשנות הלכה זו. \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת: מוהרקייהו דהני, בטפסא דמלכא מנח\u0004 \u0005[שטר שיעבוד של אלה,\u0006 של בני המדינה, \u0005באוצרו של המלך\u0006 הוא \u0005מונח]\u0006 וכל בני המדינה הם כעבדים לו, \u0003ומלכא\u0004 \u0005[והמלך]\u0006 \u0003אמר: מאן\u0004 \u0005[מי]\u0006 ש\u0003לא יהיב כרגא\u0004 \u0005[נותן,\u0006 משלם, \u0005מסים]\u0006 \u0003משתעבד למאן דיהיב כרגא\u0004 \u0005[למי שמשלם\u0006 עבורו את ה\u0005מסים],\u0006 משמע, שלמשלם המיסים יש זכות קניינית בגופם של אלה ששילם עבורם, כאילו קנה אותם מן המלך.","מסופר: \u0003ר' חייא בר אבא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום הנקרא \u0003גבלא. חזא\u0004 \u0005[ראה]\u0006 שם \u0003בנות ישראל דמעברן\u0004 \u0005[ש\u0006הן \u0005מעוברות]\u0006 \u0003מגרים שמלו ולא טבלו\u0004 עדיין, \u0003וחזא חמרא\u0004 \u0005[וראה יין]\u0006 של \u0003ישראל דמזגי\u0004 \u0005[שמוזגים]\u0006 \u0003גויים ושתו\u0004 \u0005[ושותים]\u0006 ממנו \u0003ישראל, וחזא\u0004 \u0005[וראה]\u0006 עוד \u0003תורמוסין דשלקי\u0004 \u0005[ששולקים]\u0006 \u0003גויים ואכלי\u0004 \u0005[ואוכלים]\u0006 \u0003ישראל, ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[כלום],\u0006 שלא ראה באלה איסור ממש.","\u0003אתא לקמיה\u0004 \u0005[בא לפניו]\u0006 לפני \u0003ר' יוחנן\u0004 וסיפר לו מה שראה שם. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003צא והכרז על בניהם שהם ממזרים, ועל יינם\u0004 שהוא אסור \u0003משום יין נסך, ועל תורמוסן\u0004 שהוא אסור \u0003משום בישולי גויים, לפי שאינן בני תורה,\u0004 ולכן צריך להחמיר עליהם, כדי שלא יבואו לזלזל באיסור תורה ממש.","ומסבירים: \u0003על בניהן שהם ממזרים —\u0004 בענין זה \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: לעולם אין גר\u0004 נעשה כישראל \u0003עד שימול ויטבול. וכיון\u0004 ש\u0003לא טביל\u0004 \u0005[טבל],\u0006 עדיין \u0003גוי הוא. ואמר רבה בר בר חנה אמר ר' יוחנן: גוי ועבד הבא על בת ישראל\u0004 — \u0003הולד ממזר.\u0004 וילדים אלה שהם בני גויים שלא טבלו, הם ממזרים, לדעת ר' יוחנן.","\u0003ועל יינם משום יין נסך —\u0004 אף שלא נגעו ביין עצמו, \u0003משום\u0004 הפתגם: \u0003\"לך לך, אמרין נזירא\u0004 \u0005[אומרים\u0006 ל\u0005נזיר],\u0006 \u0003סחור סחור\u0004 \u0005[סביב סביב],\u0006 \u0003לכרמא\u0004 \u0005[אל הכרם]\u0006 \u0003לא תקרב\",\u0004 שאף שוודאי אין על הנזיר איסור ללכת בכרם, אלא רק לאכול מן היוצא מן הגפן, מכל מקום צריך לעשות הרחקה כדי שלא יבוא לאכול.","\u0003ועל תורמוסן משום בשולי גויים — לפי שאינן בני תורה.\u0004 ושואלים: נדייק מכאן, \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003בני תורה שרי\u0004 \u0005[\u0006היה \u0005מותר]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שמואל בר רב יצחק משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כל\u0004 דבר \u0003הנאכל כמות שהוא חי,\u0004 שאפשר לאוכלו גם ללא בישול או צליה — אם בישלו אותו ולא עירבו בו דבר טמא, \u0003אין בו משום בשולי גויים. והא\u0004 \u0005[והרי]\u0006 \u0003תורמוס אינו נאכל כמות שהוא חי, ויש בו\u0004 אם כן \u0003משום בשולי גויים!\u0004","ומשיבים: \u0003ר' יוחנן כאידך לישנא סבירא ליה\u0004 \u0005[כלשון אחרת\u0006 באותו ענין \u0005סבור הוא],\u0006 ש\u0003אמר רב שמואל בר רב יצחק משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כל שאין\u0004 הוא דבר חשוב ש\u0003עולה על שולחן מלכים לאכול בו את הפת — אין בו משום בשולי גויים. ו\u0004כיון שתורמוסים אינם חשובים, לכן \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003אינן בני תורה\u0004 ולכן אסר להם, \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003בני תורה — שרי\u0004 \u0005[מותר\u0006 להם\u0005]\u0006 לאכול אותו, שאין זה מאכל חשוב האסור משום בישולי גויים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גר שמל ולא טבל\u0004 לשם גירות, \u0003ר' אליעזר אומר: הרי זה גר, שכן מצינו באבותינו\u0004 אחרי יציאת מצרים \u0003שמלו ולא טבלו. טבל ולא מל, ר' יהושע אומר: הרי זה גר, שכן מצינו באמהות\u0004 באותו דור \u0003שטבלו ולא מלו. וחכמים אומרים:\u0004 בין \u0003טבל ולא מל,\u0004 בין \u0003מל ולא טבל — אין\u0004 הוא נעשה \u0003גר עד שימול ויטבול.\u0004","ושואלים: \u0003ור' יהושע נמי\u0004 \u0005[גם כן]\u0006 \u0003נילף\u0004 \u0005[שילמד]\u0006 \u0003מאבות, ור' אליעזר נמי\u0004 \u0005[גם כן]\u0006 \u0003נילף\u0004 \u0005[שילמד]\u0006 \u0003מאמהות! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין ר' אליעזר לומד מאמהות, משום שהוא סבור ש\u0003אין דנין אפשר משאי אפשר.\u0004 שכיון שבאמהות אין אפשרות של מילה בכלל, אין ללמוד מכאן למקרים שבהן יכולה להיות מילה;","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 המוכיחה שר' אליעזר למד בשיטה זו, ששנינו, \u0003ר' אליעזר אומר: מנין לפסח דורות,\u0004 כלומר, קרבן פסח בכל הדורות, \u0003שאין בא אלא מן החולין,\u0004 ולא ממעשרות או מהקדשים אחרים — \u0003נאמר פסח במצרים, ונאמר פסח בדורות, מה פסח האמור במצרים אין בא אלא מן החולין,\u0004 שהרי עוד לא ניתנה תורה לישראל, ולא היה מושג של הקדש — \u0003אף פסח האמור לדורות אין בא אלא מן החולין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא: וכי דנין\u0004 דבר ש\u0003אפשר משאי אפשר?\u0004 שהרי פסח מצרים נחשב כאי אפשר, שכן במצרים לא היה עדיין מעשר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אליעזר: \u0003אף על פי שאי אפשר — ראיה גדולה היא ונלמד הימנה.\u0004 ואם כן רואים שהוא עצמו סבור שאפשר ללמוד בדרך זו!","\u0003אלא\u0004"],["\u0003בטבל ולא מל כולי עלמא לא פליגי דמהני\u0004 \u0005[הכל,\u0006 גם ר' יהושע וגם ר' אליעזר, \u0005אינם חלוקים ש\u0006הוא \u0005מועיל],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003במל ולא טבל. ר' אליעזר יליף\u0004 \u0005[למד]\u0006 זאת \u0003מאבות, ור' יהושע\u0004 סבור: \u0003באבות נמי\u0004 \u0005[גם כן]\u0006 \u0003טבילה הוה\u0004 \u0005[היתה],\u0006 ולכך אין איפוא ראיה מהם לזה שרק מל ולא טבל.","ושואלים: \u0003מנא ליה\u0004 \u0005[מניין לו]\u0006 לר' יהושע דבר זה? \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006מה \u0005שנאמר]:\u0006 \u0003\"לך אל העם וקדשתם היום ומחר וכבסו שמלתם\"\u0004 (שמות יט, י), ונאמר, שהוא לומד בצורה זו: \u0003ומה\u0004 בכל דיני טהרה \u0003במקום שאין טעון כבוס\u0004 בגדים — \u0003טעון\u0004 מכל מקום \u0003טבילה, מקום שטעון כבוס\u0004 כמפורש בקבלת התורה — \u0003אינו דין שטעון טבילה,\u0004 ומכאן שגם טבלו לפני קבלת התורה.","אולם אפשר להקשות: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 לא דובר שם בכיבוס בגדים לשם טהרה, אלא ל\u0003נקיות בעלמא\u0004 \u0005[בלבד],\u0006 שאמר להם שיכינו את עצמם לקבלת התורה ויהיו נקיים אבל לא לענין טבילת בגדים לשם טהרה?!","\u0003אלא מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ויקח משה את הדם ויזרק על העם\"\u0004 (שם כד, ח), \u0003וגמירי\u0004 \u0005[ולמודים\u0006 אנו\u0005]\u0006 ש\u0003אין הזאה בלא טבילה,\u0004 וכיון שהזה עליהם דם, ודאי טבלו.","ושואלים: \u0003ור' יהושע, טבילה באמהות מנלן\u0004 \u0005[מניין לנו]\u0006 שהיתה? ומשיבים: \u0003סברא היא\u0004 בדבר, ש\u0003אם כן,\u0004 שאתה אומר שלא טבלו, \u0003במה נכנסו תחת כנפי השכינה?\u0004 אלא ודאי היה מעשה של כניסה ובודאי היה זה בטבילה כפי המקובל.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: לעולם אינו גר עד שימול ויטבול.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך ההלכה, ולשם מה היה עליו לפסוק כך? שהרי הדבר נובע מכללי ההלכה: \u0003יחיד ורבים — הלכה כרבים,\u0004 והרי נאמר שזו היא דעת חכמים!","ומשיבים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 האמורים באותה משנה — לא כל חכמי ישראל הם, אלא שיטת \u0003ר' יוסי\u0004 היא.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שבא\u0004 אדם \u0003ואמר מלתי ולא טבלתי — מטבילין אותו, ומה בכך.\u0004 כלומר, שאם כבר מל לשם גירות — הרי זה בלבד מספיק אפילו לא טבל, ואם מילתו היתה לא לשם גירות — הרי הוא טובל עכשיו, וטבילה לבד גם כן מועילה, אלו \u0003דברי ר' יהודה. ר' יוסי אומר:\u0004 אם מילתו שלא לשם גירות היתה — \u0003אין מטבילין,\u0004 ואף אם הטבילו — אינו נעשה בכך גר, שבשביל גירות צריך שתהיה המילה וטבילה לשם גירות.","\u0003לפיכך מטבילין גר בשבת,\u0004 אלו \u0003דברי ר' יהודה,\u0004 שכיון שלדעתו אם כבר מל, הטבילה אינה מעכבת, רשאי הוא לטבול בשבת כדרך שטובל כל אדם מישראל בשבת, כיון שאין בטבילתו שם תיקון. \u0003ור' יוסי אומר: אין מטבילין\u0004 אותו, משום שלדעתו עיקרה של הגירות הוא גם בטבילה, ונמצא שטבילתו היא מעשה של תיקון ושינוי, ואסורה בשבת.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003לפיכך מטבילין גר בשבת.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003כיון\u0004 ש\u0003אמר ר' יהודה\u0004 כי \u0003בחדא סגיא\u0004 \u0005[באחת\u0006 מהן \u0005די],\u0006 במילה או בטבילה, אם כן \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003מל לפנינו,\u0004 כלומר, שהוא נימול כבר — \u0003מטבילין\u0004 אפילו בשבת, אם כן \u0003מאי\u0004 \u0005[מהי]\u0006 התוספת \u0003\"לפיכך\"?\u0004 הלא מסקנה זו מובנת מאליה!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003ל\u0004דעת \u0003ר' יהודה טבילה\u0004 היא באמת \u0003עיקר\u0004 הגירות, ומה שאמר \"מטבילין אנו ומה בכך\" התכוון לומר שאין מעכבים אותו מלטבול, שהרי בכך הוא מתגייר, \u0003ו\u0004לפי הבנה זו \u0003טבילה בשבת לא\u0004 יעשו, \u0003דקא מתקן גברא\u0004 \u0005[ש\u0006הרי \u0005הוא מתקן,\u0006 עושה תיקון, ב\u0005אדם]\u0006 על ידיה כיון שהיא עיקר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלשיטת \u0003ר' יהודה או הא\u0004 \u0005[זה]\u0006 \u0003או הא בעי\u0004 \u0005[זה\u0006 הוא \u0005מצריך],\u0006 שגם טבילה וגם מילה כל אחת לבדה מועילה, ולכן טבילה לאחר מילה אין בה עוד תיקון.","\u0003ר' יוסי אומר: אין מטבילין\u0004 אותו בשבת, ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 ש\u0003כיון\u0004 ש\u0003אמר ר' יוסי\u0004 כי \u0003תרתי בעינן\u0004 \u0005[שני\u0006 דברים \u0005צריכים אנו]\u0006 מילה וטבילה — \u0003תקוני גברא\u0004 \u0005[לתקן אדם]\u0006 \u0003בשבת לא מתקנינן\u0004 \u0005[מתקנים אנו]?\u0006","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003ל\u0004דעת \u0003ר' יוסי\u0004 ה\u0003מילה\u0004 היא \u0003עיקר\u0004 הגירות, \u0003והתם\u0004 \u0005[ושם],\u0006 באותו מקרה שבא הגר כשהוא נימול, \u0003הוא\u0004 שאין הדבר מועיל לו, כיון ש\u0003לא הואי\u0004 \u0005[היתה]\u0006 ה\u0003מילה בפנינו,\u0004 ואיננו יודעים אם מל לשם גירות, \u0003אבל היכא דהויא\u0004 \u0005[היכן,\u0006 במקרה, \u0005שהיתה]\u0006 ה\u0003מילה בפנינו — אימא ליטבול\u0004 \u0005[אמור שיטבול]\u0006 \u0003זה בשבתא\u0004 \u0005[בשבת],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003ר' יוסי תרתי בעי\u0004 \u0005[שני\u0006 דברים הוא \u0005מצריך],\u0006 מילה וטבילה, ושניהם חשובים בשווה.","\u0003אמר רבה: עובדא הוה\u0004 \u0005[מעשה היה]\u0006 \u0003בי\u0004 \u0005[\u0006ב\u0005בית]\u0006 \u0003ר' חייא בר רבי, ורב יוסף מתני\u0004 \u0005[\u0006היה \u0005שונה]\u0006 שהיה שם גם \u0003ר' אושעיא בר רבי, ורב ספרא מתני\u0004 \u0005[\u0006היה \u0005שונה]\u0006 שהיה בנוסף להם גם \u0003ר' אושעיא בר' חייא, דאתא לקמיה\u0004 \u0005[שבא לפניו]\u0006 \u0003גר שמל ולא טבל. אמר ליה\u0004 \u0005[לו]\u0006 לגר: \u0003שהי\u0004 \u0005[שהה]\u0006 \u0003כאן\u0004 איתנו \u0003עד למחר ונטבלינך\u0004 \u0005[ונטביל אותך].\u0006","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ממעשה זה \u0003תלת\u0004 \u0005[שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003גר צריך שלשה\u0004 אנשים שיהיו נוכחים בשעת הטבילה, שיהיו כבית דין, שהרי לדברי רב ספרא היו שם ר' חייא ברבי ור' אושעיא ברבי ור' אושעיא בר' חייא. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003אינו\u0004 נעשה \u0003גר עד שימול ויטבול, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003אין מטבילין גר בלילה\u0004 ולכן אמר לו להמתין למחר. ושואלים: \u0003ונימא\u0004 \u0005[ונאמר]:\u0006 כי \u0003שמע מינה נמי\u0004 \u0005[למד מכן גם כן]\u0006 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לצורך קבלת הגר שיהיו דיינים \u0003מומחין\u0004 (סמוכים), שהרי אותם חכמים שמנה רב ספרא היו מומחים. ודוחים: מכאן אין ראיה, \u0003דלמא\u0004 \u0005[שמא]\u0006 כך היה המעשה, \u0003דאיקלעו\u0004 \u0005[שנזדמנו]\u0006 שלושה אלה אתו, שהיו חכמים, אבל מלכתחילה די גם בהדיוטות.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: גר צריך שלשה\u0004 שיהיו נוכחים בשעת קבלתו לגירות, כי \u0003\"משפט\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 כאמור: \"...ומשפט אחד יהיה לכם ולגר הגר אתכם\" (במדבר טו, טז), ומשפט־דין הוא בשלושה דיינים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מי\u0004 מן הגויים \u0003שבא ואמר \"גר אני\", יכול נקבלנו\u0004 ונחזיקנו כגר — \u0003תלמוד לומר:\u0004 \"וכי יגור \u0003אתך\u0004 גר\" (ויקרא יט, לג), לומר: \u0003במוחזק לך,\u0004 שאנחנו יודעים בו שהוא גר. \u0003בא\u0004 גר \u0003ועדיו עמו\u0004 המעידים עליו שנתגייר כראוי — \u0003מנין\u0004 שהוא נאמן — \u0003תלמוד לומר: \"וכי יגור אתך גר בארצכם\"\u0004 (שם)."],["\u0003אין לי\u0004 שנחשב איש זה לגר \u0003אלא בארץ, בחוץ לארץ מנין? תלמוד לומר: \"אתך\" — בכל מקום שאתך. אם כן מה תלמוד לומר \"בארץ\",\u0004 אם אין הבדל בין הארץ לחוץ לארץ? \u0003בארץ — צריך להביא ראיה\u0004 שגר הוא, \u0003בחוץ לארץ\u0004 אם בא אדם ואמר שהוא גר — \u0003אין צריך להביא ראיה,\u0004 אלו \u0003דברי ר' יהודה. וחכמים אומרים: בין בארץ בין בחוצה לארץ צריך להביא ראיה.\u0004","ושואלים: אמרנו ש\u0003בא הוא ועדיו עמו,\u0004 ואם כן \u0003קרא\u0004 \u0005[כתוב]\u0006 מפורש בזה \u0003למה לי?\u0004 הרי בכל מקום סומכים על העדים! \u0003אמר רב ששת:\u0004 אין מדובר כאן בעדים שהעידו שנתגייר, אלא \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 העדים: \u0003שמענו שנתגייר בבית דין של פלוני. סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 ש\u0003לא ליהמנייהו\u0004 \u0005[נאמין להם]\u0006 עד שיעידו שהם עצמם ראו את הגיור, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב שגם עדות זו מספקת.","שנינו שם: \u0003\"בארץ\" — אין לי אלא בארץ, בחוצה לארץ מנין — תלמוד לומר: \"אתך\" בכל מקום שאתך.\u0004 ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי\u0006 כבר \u0005הוצאת אותו]\u0006 כבר למדת מ\"אתך\" ענין אחר, לומר: במוחזק לך, וכיצד למד אתה מאותו כתוב גם לענין הארץ? ומשיבים: \u0003חדא\u0004 \u0005[\u0006דבר \u0005אחד]\u0006 נלמד ממה שנאמר \u0003\"אתך\" וחדא\u0004 \u0005[ואחד]\u0006 נלמד \u0003מ\u0004מה שנאמר שם \u0003\"עמך\"\u0004 (ויקרא כה, לה).","שנינו שם, \u0003וחכמים אומרים: בין בארץ בין בחוצה לארץ צריך להביא ראיה.\u0004 ושואלים: \u0003ואלא הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"בארץ\"!\u0004","ומשיבים: הביטוי \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמד להיפך: ש\u0003אפילו בארץ מקבלים גרים. דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר\u0006 ש\u0003משום טיבותא\u0004 \u0005[טובתה]\u0006 של \u0003ארץ ישראל קמגיירי\u0004 \u0005[הם מתגיירים]\u0006 ולא לשם שמים, ולא נקבלם, על כן השמיע לנו שמכל מקום מקבלים אותם. ומעירים: \u0003והשתא נמי\u0004 \u0005[ועכשיו,\u0006 בימינו, \u0005גם כן]\u0006 אף על פי \u0003דליכא טיבותא\u0004 \u0005[שאין טוב\u0006 הארץ\u0005]\u0006 שהארץ נדלדלה, \u0003איכא\u0004 \u0005[יש]\u0006 על כל פנים יתרון אחר: \u0003לקט שכחה ופאה ומעשר עני\u0004 שנותנים לעניי ישראל בארץ ישראל, ושמא הרוצה להתגייר מתכוון ליהנות מהם, ויש אולי מקום לומר שלא נגיירו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמקבלים אותו ואין חוששים לכך.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הלכה\u0004 היא ש\u0003בין בארץ בין בחוץ לארץ, צריך להביא ראיה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו הדבר\u0005]\u0006 הלא \u0003יחיד ורבים הלכה כרבים!\u0004 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מסתבר טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יהודה, דקמסייעי ליה קראי\u0004 \u0005[שמסייעים לו הכתובים],\u0006 שהרי נאמר \"בארצכם\", על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת פוסקים כדעת הרבים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"ושפטתם צדק בין איש ובין אחיו ובין גרו\"\u0004 (דברים א, טז), \u0003מכאן אמר ר' יהודה: גר שנתגייר בבית דין\u0004 מתקיים בו \"ושפטתם\" ו\u0003הרי זה גר\u0004 (\"גרו\"), אבל אם נתגייר \u0003בינו לבין עצמו — אינו גר.\u0004","ומסופר: \u0003מעשה באחד שבא לפני ר' יהודה, ואמר לו: נתגיירתי ביני לבין עצמי. אמר לו ר' יהודה: יש לך עדים\u0004 שנתגיירת שלא בפני בית דין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו\u0004 \u0005[לא].\u0006 שאל ר' יהודה: \u0003יש לך בנים? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הן\u0004 \u0005[כן].\u0006 \u0003אמר לו\u0004 \u0005[לו]:\u0006 \u0003נאמן אתה לפסול את עצמך,\u0004 שאתה מעיד שלא גויירת כראוי, וגוי אתה, \u0003ו\u0004אולם \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה נאמן לפסול את בניך.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יהודה\u0004 כי על ה\u0003בנים לא מהימן\u0004 \u0005[אין\u0006 אדם \u0005נאמן]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"\u0004כי את הבכור בן השנואה \u0003יכיר\"\u0004 (שם כא, יז), ופירשוהו: \u0003יכירנו לאחרים.\u0004 כלומר, הוא מעיד ואומר לאחרים שזה בנו הבכור ונאמן. \u0003מכאן אמר ר' יהודה: נאמן אדם לומר \"זה בני בכור\"\u0004 וסומכים עליו בכך, \u0003וכשם שנאמן לומר \"זה בני בכור\"\u0004 וסומכים עליו, \u0003כך נאמן\u0004 אב שהוא כהן \u0003לומר: \"בני זה בן גרושה הוא\", או \"בן חלוצה הוא\"\u0004 ונפסל על ידי כך לכהונה. \u0003וחכמים אומרים: אינו נאמן\u0004 לפסול את בניו. הרי שלשיטת ר' יהודה נאמן אדם לפסול בעדותו את בניו, ומדוע אם כן אמר ר' יהודה לאותו גר שאינו נאמן לפסול את בניו?","\u0003אמר רב נחמן בר יצחק: הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003לדבריך\u0004 הרי \u0003גוי אתה, ואין עדות לגוי\u0004 ומטעם זה אינך יכול להעיד על בניך ולפוסלם. \u0003רבינא אמר: הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003יש לך בנים?\u0004 אמר לו: \u0003הן\u0004 \u0005[כן]\u0006 \u0003יש לך בני בנים?\u0004 אמר לו: \u0003הן. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נאמן אתה לפסול בניך,\u0004 שגזירת הכתוב היא שהאב נאמן על בניו (\"יכיר\"), ואולם, מאחר \u0003ואי\u0004 \u0005[ואין]\u0006 \u0003אתה נאמן לפסול\u0004 את \u0003בני בניך,\u0004 לכן גם על בניו אין מאמינים לו, שאם תאמין לו על בניו, נמצא שאתה פוסל בעדות זו גם את בני בניו.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' יהודה אומר: נאמן אדם לומר על בנו\u0004 ה\u0003קטן\u0004 שהוא פסול \u0003ואין נאמן על בנו\u0004 ה\u0003גדול. ואמר ר' חייא בר אבא אמר ר' יוחנן: לא קטן קטן ממש\u0004 שלא הגיע לבגרות, \u0003ולא גדול גדול ממש\u0004 לענין בגרות. \u0003אלא, קטן ויש לו בנים — זהו גדול\u0004 ואינו נאמן עליו. ולהיפך: בן \u0003גדול ואין לו בנים — זהו קטן.\u0004","ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב נחמן בר יצחק,\u0004 שנאמן על עצמו ולא על בניו אפילו כשאין להם בנים. ושואלים: \u0003והתניא כוותיה\u0004 \u0005[והרי שנינו\u0006 בברייתא בפירוש \u0005כשיטתו]\u0006 של \u0003רבינא!\u0004 ומשיבים: \u0003ההוא,\u0004 הברייתא הזו דיברה \u0003לענין\u0004 המשנה העוסקת ב\u0003\"יכיר\",\u0004 שעל מה שאמרה המשנה שכשם שנאמן להעיד על בכורתו של בנו כך נאמן לומר שהוא בן גרושה \u0003איתמר\u0004 \u0005[נאמר]\u0006 בברייתא שזהו דווקא בקטן שאין לו בנים, כיון שאינו נאמן אלא על בנו ולא על בן בנו. וכל זה דווקא בישראל, אבל הגוי שעדותו אינה עדות, אינו נאמן אפילו על בנו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גר שבא להתגייר בזמן הזה, אומרים לו\u0004 בבית דין: \u0003מה ראית שבאת להתגייר?\u0004 וכי \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה יודע שישראל בזמן הזה דוויים\u0004 (חולים), \u0003דחופים\u0004 על ידי אחרים, \u0003סחופים\u0004 (שפלים) \u0003ומטורפין\u0004 (נדים ממקום למקום), \u0003ויסורין באין עליהם? אם אומר: יודע אני, ואיני כדאי\u0004 אין ראוי לי לזכות להשתתף עם ישראל, אבל רצוני לקבל על עצמי גם את סבלם — \u0003מקבלין אותו מיד.\u0004","\u0003ומודיעין אותו מקצת מצות קלות ומקצת מצות חמורות, ומודיעין אותו\u0004 גם \u0003עון לקט שכחה ופאה ומעשר עני\u0004 שחייב יהיה להפריש, ונענש אם אינו מפרישם. \u0003ומודיעין אותו ענשן של מצות.\u0004 ש\u0003אומרים לו: הוי יודע, שעד שלא באת למדה זו\u0004 ולא התגיירת, אם \u0003אכלת חלב — אי\u0004 \u0005[אין]\u0006 \u0003אתה ענוש כרת,\u0004 שהרי אין איסור לגוי לאכול חלב. \u0003חללת שבת — אי\u0004 \u0005[אין]\u0006 \u0003אתה ענוש סקילה. ו\u0004אילו \u0003עכשיו,\u0004 משנתגיירת, אם \u0003אכלת חלב — הרי אתה ענוש כרת, חללת שבת — הרי אתה ענוש סקילה.\u0004","\u0003וכשם שמודיעין אותו ענשן של מצות כך מודיעין אותו מתן שכרן\u0004 של מצוות לעולם הבא. ש\u0003אומרים לו: הוי יודע שהעולם הבא אינו עשוי אלא לצדיקים\u0004 גמורים, \u0003וישראל בזמן הזה אינם יכולים לקבל\u0004"],["\u0003לא רוב טובה ולא רוב פורענות,\u0004 לפי שעיקר מתן שכר הוא לעתיד לבוא. \u0003ואין מרבין עליו\u0004 באיומים, \u0003ואין מדקדקין עליו\u0004 בפרטי מצוות.","אם \u0003קיבל\u0004 על עצמו — \u0003מלין אותו מיד. נשתיירו בו ציצין\u0004 (חתיכות בשר מן הערלה) \u0003המעכבין את\u0004 כשרות \u0003המילה,\u0004 שלא נימול כהלכה — \u0003חוזרים ומלין אותו\u0004 פעם \u0003שניה. נתרפא\u0004 מן המילה — \u0003מטבילין אותו מיד. ושני תלמידי חכמים עומדים על גביו\u0004 בשעת הטבילה \u0003ומודיעין אותו מקצת מצות קלות ומקצת מצות חמורות. טבל ועלה\u0004 מן הטבילה — \u0003הרי הוא כישראל לכל דבריו.\u0004","\u0003אשה\u0004 שבאה להתגייר — \u0003נשים מושיבות אותה במים עד צוארה, ושני תלמידי חכמים עומדים לה מבחוץ\u0004 שלא יראו בעירומה, \u0003ומודיעין אותה מקצת מצות קלות ומקצת מצות חמורות.\u0004","דין \u0003אחד\u0004 בענין זה ל\u0003גר, ו\u0004דין \u0003אחד\u0004 ל\u0003עבד משוחרר\u0004 כשטובל בזמן שהוא משתחרר מן העבדות, ונעשה כישראל לכל דבר. \u0003ובמקום שנדה טובלת,\u0004 כלומר, רק מקוה הכשר לטבילת נדה, \u0003שם גר ועבד משוחרר טובלין, וכל דבר שחוצץ בטבילה\u0004 של טהרה \u0003חוצץ\u0004 גם בטבילה \u0003בגר ובעבד משוחרר, ובנדה\u0004 להתירה לבעלה.","עד כאן לשון הברייתא, ומעתה מבררים אותה לפרטיה. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003גר שבא להתגייר, אומרים לו\u0004 בית הדין \u0003מה ראית שבאת להתגייר? ומודיעים אותו מקצת מצות קלות ומקצת מצות חמורות.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 עושים כך? — \u0003דאי פריש\u0004 \u0005[שאם\u0006 רוצה \u0005לפרוש] —\u0006 \u0003נפרוש\u0004 \u0005[שיפרוש]\u0006 עכשיו, ואין מדברים על לבו שיתגייר. ש\u0003אמר ר' חלבו: קשים גרים לישראל כספחת\u0004 (מחלת נגע צרעת), \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונלוה הגר עליהם ונספחו על בית יעקב\"\u0004 (ישעיה יד, א), והלשון \"נספחו\" מרמזת על ספחת, ללמדנו שתוספת זו קשה לישראל.","שנינו שם: \u0003ומודיעים אותו,\u0004 את הבא להתגייר, \u0003עון לקט שכחה ופאה ומעשר עני.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מודיעים דווקא מצוות אלה? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 משום ש\u0003בן נח נהרג על פחות משוה פרוטה,\u0004 שאם גזל כלשהו — הריהו חייב מיתה, משום שעבר על אחת ממצוות בני נח, \u0003ולא ניתן להשבון,\u0004 שאין נמחל לו על מה שעבר, גם אם מחזיר את הגזילה, שלגבי גוי אין תיקון לעבירה על ידי השבת הגזילה, לכן יש להודיע לגר אותן מצוות שיש בהן נתינת ממון והפקרת נכסיו לאחרים, כדי שלא יחשוב שאותם עניים המלקטים בשדהו גזלנים הם ויבוא להורגם, כדין בני נח.","שנינו: \u0003ומודיעים אותו\u0004 על \u0003עון שכחה ופאה\u0004 אם לא יפרישן, \u0003ואין מרבים עליו ואין מדקדקים עליו. אמר ר' אלעזר: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — \u0003דכתיב\u0004 \u0005[שנאמר],\u0006 שאחרי שדיברה נעמי עם רות וניסתה להניאה מלבוא עמה, \u0003\"ותרא כי מתאמצת היא ללכת אתה ותחדל לדבר אליה\"\u0004 (רות א, יח).","ואגב כך מבארים מה אמרה נעמי לרות קודם לכן, ולמדים דברים אלה מן התשובות שהשיבה לה רות, \u0003אמרה לה: אסיר לן\u0004 \u0005[אסור לנו]\u0006 לצאת מ\u0003תחום שבת\u0004 — השיבה לה רות: \u0003\"באשר תלכי אלך\"\u0004 (שם טז), ולא יותר מזה. אמרה לה נעמי: \u0003אסיר לן\u0004 \u0005[אסור לנו]\u0006 \u0003יחוד\u0004 עם גברים זרים — השיבה לה רות: \u0003\"\u0004ו\u0003באשר תליני אלין\"\u0004 (שם) באותו אופן.","אמרה לה נעמי: \u0003מפקדינן\u0004 \u0005[מצווים אנו]\u0006 על \u0003שש מאות ושלש עשרה מצות —\u0004 אמרה לה רות: \u0003\"עמך עמי\"\u0004 (שם) לכל המצוות כולן. הוסיפה ואמרה לה נעמי: \u0003אסיר לן\u0004 \u0005[אסורה לנו]\u0006 \u0003עבודה זרה —\u0004 השיבה לה רות: \u0003\"ואלהיך אלהי\"\u0004 (שם). אמרה לה: \u0003ארבע מיתות נמסרו לבית דין\u0004 לענוש את העבריינים — השיבה לה רות: \u0003\"באשר תמותי אמות\"\u0004 (שם). אמרה לה נעמי: \u0003שני קברים נמסרו לבית דין,\u0004 לאלה שנענשו במיתות חמורות ולאלה שנענשו במיתות קלות — השיבה לה רות: \u0003\"ושם אקבר\"\u0004 (שם).","\u0003מיד — \"ותרא כי מתאמצת היא\u0004 ללכת אתה ותחדל לדבר אליה\u0003\"\u0004 (שם יז), שכיון ששמעה רות את עיקרי הדברים וקיבלה עליה — אין צורך יותר למנעה.","שנינו שם: \u0003קיבל\u0004 הגר עליו — \u0003מלין אותו מיד. מאי טעמא\u0004 \u0005[מה טעם]\u0006 מיד — כי \u0003שהויי\u0004 \u0005[השהיית]\u0006 \u0003מצוה לא משהינן\u0004 \u0005[משהים אנו],\u0006 שכיון שגמר בלבו להתגייר — מצוה היא לגיירו מיד.","עוד שנינו שם: \u0003נשתיירו בו ציצין המעכבין\u0004 את כשרות \u0003המילה\u0004 — חוזרים ומלים אותו. \u0003כדתנן\u0004 \u0005[כ\u0006פי \u0005ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אלו הן ציצין\u0004 (חתיכות הבשר) \u0003המעכבין\u0004 את כשרות \u0003המילה — בשר\u0004 ערלה \u0003החופה\u0004 (המכסה) \u0003את רוב העטרה. ו\u0004מי שיש בו ערלה בשיעור זה — \u0003אינו אוכל בתרומה\u0004 אם כהן הוא. \u0003ואמר רב ירמיה בר אבא אמר רב:\u0004 רוב העטרה פירושו \u0003בשר החופה רוב גובהה של העטרה,\u0004 ולא דווקא רוב היקפה.","עוד שנינו: \u0003נתרפא — מטבילין אותו מיד.\u0004 ומדייקים: \u0003נתרפא — אין\u0004 \u0005[כן],\u0006 \u0003לא נתרפא — לא. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003משום דמיא מרזו\u0004 \u0005[שהמים מזיקים]\u0006 ל\u0003מכה,\u0004 לפצע, ולכן ממתינים עד שיתרפא פצע המילה, ואז טובל.","עוד שנינו: \u0003ושני תלמידי חכמים עומדים על גביו\u0004 בשעת הטבילה. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' חייא אמר ר' יוחנן: גר צריך שלשה\u0004 לטבילתו, שיהיו בית דין! ומשיבים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' יוחנן לתנא\u0004 (לחוזר המשניות): \u0003תני\u0004 \u0005[שנה]\u0006 כאן לא שני תלמידי חכמים, אלא \u0003שלשה.\u0004","עוד שנינו: \u0003טבל ועלה — הרי הוא כישראל לכל דבריו.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? — לומר: \u0003דאי הדר ביה\u0004 \u0005[שאם חזר בו]\u0006 לאחר זמן ומתנהג כגוי, \u0003ומקדש בת ישראל,\u0004 אין אנו אומרים שהוא כגוי, ואין כאן קידושין ממש, אלא \u0003ישראל משומד קרינא ביה\u0004 \u0005[קוראים אנו בו]\u0006 ודנים אותו כישראל שחטא, \u0003ו\u0004לכן \u0003קידושיו קידושין\u0004 ואינה נפטרת אלא בגט.","עוד שנינו: \u0003אחד גר ואחד עבד משוחרר. קסלקא דעתך\u0004 \u0005[עלתה על דעתנו]\u0006 לומר מתחילה, שהכוונה היתה לענין \u0003לקבל עליו עול מצות,\u0004 שאף עבד משוחרר צריך שיקבל עליו במפורש עול מצוות כגר. \u0003ורמינהו\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: \u0003במה דברים אמורים\u0004 שצריך שיקבל עליו עול מצוות — \u0003בגר, אבל בעבד משוחרר — אין צריך לקבל\u0004 עליו, אלא מיד עם שחרורו הוא נעשה כישראל!","\u0003אמר רב ששת: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמרו שאין צריך לקבל עליו — כשיטת \u0003ר' שמעון בן אלעזר\u0004 היא, ואילו \u0003הא\u0004 \u0005[זו]\u0006 שצריך לקבל עליו — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדין אשת יפת תואר, שאדם רואה בשבי ולוקח אותה לו לאשה. נאמר שם: \u0003\"ובכתה את אביה ואת אמה\u0004 ירח ימים ואחר כן תבוא עליה ובעלתה והיתה לך לאשה\u0003\"\u0004 (דברים כא, יג), ואומרים: \u0003במה דברים אמורים —\u0004 כ\u0003שלא קבלה עליה\u0004 להתגייר, אלא הוא מכריח אותה לכך. \u0003אבל\u0004 אם \u0003קבלה עליה — מטבילה\u0004 לשם גירות, \u0003ומותר בה מיד.\u0004","\u0003ר' שמעון בן אלעזר אומר: אף על פי שלא קבלה עליה\u0004 יהדות \u0003כופה ומטבילה לשם שפחות,\u0004 שהטבילה לשם שפחה אינה נתונה להסכמתה של הנטבלת, \u0003וחוזר\u0004 אחר כך \u0003ומטבילה לשם שחרור\u0004 בעל כורחה, \u0003ומשחררה,\u0004"],["\u0003ומותר בה מיד,\u0004 מכאן, שלדעתו עבד איננו צריך לקבל על עצמו מצוות בזמן טבילת שחרור, אלא מיד הוא נעשה כישראל, שהרי אותה אשה לא רצתה לקבל על עצמה יהדות ומשמע שעל ידי שחרורה היא נעשית בעל כורחה יהודית.","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון בן אלעזר — דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ו \u0003כל עבד איש מקנת כסף\u0004 ומלתה אותו\" (שמות יב, מד). והוא מדייק כאן: מדוע נאמר \u0003\"עבד איש\"\u0004 ולא נאמר \"עבד\" סתם? וכי הכוונה היא עבד איש \u0003ולא עבד אשה? אלא עבד\u0004 שהוא \u0003איש,\u0004 שהוא אדם מבוגר — \u0003אתה מל בעל כרחו\u0004 (\"ומלתה אותו\"), \u0003(ואין) אתה מל בן איש,\u0004 כלומר, סתם גוי, לגיירו \u0003בעל כרחו.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מבינים הם את הכתוב? \u0003אמר עולא,\u0004 כך הם מבינים: \u0003כשם שאי\u0004 (שאין) \u0003אתה מל בן איש בעל כרחו,\u0004 וצריך אדם להתגייר מרצונו, \u0003כך אי אתה מל עבד איש בעל כרחו.\u0004 ושואלים: \u0003ואלא הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"כל עבד איש\",\u0004 ומה למדים הם מפסוק זה? ומשיבים: הפסוק \u0003ההוא מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003לכ\u0004 דבריו של \u0003שמואל.\u0004","ש\u0003אמר שמואל: המפקיר עבדו — יצא\u0004 על ידי כך \u0003לחירות,\u0004 ונעשה כישראל, \u0003ואין צריך גט\u0004 (שטר) \u0003שחרור, שנאמר\u0004 \"ו \u0003כל עבד איש מקנת כסף\".\u0004 ויש לדייק: וכי דווקא \u0003עבד איש ולא עבד אשה? אלא\u0004 ודאי הכוונה: \u0003עבד שיש לו רשות לרבו עליו\u0004 ושהוא עובד אותו (\"עבד איש\" — עבד של איש) — \u0003קרוי עבד, ושאין רשות לרבו עליו\u0004 שהפקירו — \u0003אין קרוי עבד.\u0004","על כל אותה שיטה של רב ששת שיש כאן מחלוקת בין ר' שמעון בן אלעזר לחכמים אם עבד משוחרר צריך לקבל על עצמו עול מצוות, \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב פפא: אימור דשמעת להו לרבנן\u0004 \u0005[אמור ששמעת אותם את חכמים]\u0006 שמצריכים קבלת מצוות \u0003ביפת תואר,\u0004 ש\u0003לא שייכא\u0004 \u0005[\u0006היתה \u0005שייכת]\u0006 מתחילה \u0003במצות,\u0004 שהרי גויה גמורה היתה, \u0003אבל עבד\u0004 ש\u0003שייך במצות\u0004 בהיותו עבד, שהרי בעבדותו נתחייב בחלק מן המצוות של ישראל, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שכאשר מטבילו לשם שחרור אינו צריך לקבל עליו עול שאר המצוות.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד גר ואחד לוקח\u0004 (קונה) \u0003עבד מן הגוי — צריך\u0004 העבד \u0003לקבל\u0004 עליו עול מצוות. \u0003הא\u0004 \u0005[הרי]\u0006 מכאן תלמד שמי ש\u0003לוקח מישראל — אין צריך לקבל.\u0004","ונברר, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אי\u0004 \u0005[אם]\u0006 תאמר כדעת \u0003ר' שמעון בן אלעזר — האמר\u0004 \u0005[הרי אמר]\u0006 כי \u0003לוקח מן הגוי נמי\u0004 \u0005[גם כן]\u0006 \u0003אין צריך לקבל! אלא לאו\u0004 \u0005[האם לא]\u0006 ברייתא זו כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' שמעון בן אלעזר, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 בדרך הדיוק: ש\u0003לוקח מן הגוי צריך לקבל\u0004 עליו עול מצוות \u0003אבל לוקח\u0004 עבד \u0003מישראל — אין צריך לקבל,\u0004 שכבר קיבל כשנעשה עבד.","ושואלים: \u0003ואלא\u0004 אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מה ששנינו במשנתנו \u0003אחד גר ואחד עבד משוחרר,\u0004 שדינם שווה! ומשיבים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 ששניהם שווים — \u0003לענין טבילה תניא\u0004 \u0005[\u0006היא \u0005שנויה],\u0006 לומר ששניהם חייבים בטבילה, ולא לענין קבלת מצוות, שבענין זה יש ביניהם הבדל.","כיון שהזכרנו את דין אשת יפת תואר, בגלל הקירבה לנושא של גירות, מביאים דברים שנאמרו בהלכה זו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר בענין אשת יפת תואר: \u0003\"וגלחה את ראשה ועשתה את צפרניה\"\u0004 (דברים כא, יב), ונחלקו תנאים בפירושו של ביטוי זה; \u0003ר' אליעזר אומר\u0004 כי פירושו: \u0003תקוץ\u0004 (תקצוץ) את צפרניה, \u0003ר' עקיבא אומר: תגדיל.\u0004","ומסבירים את שיטותיהם, \u0003אמר ר' אליעזר: נאמרה עשיה בראש\u0004 שהיא עושה מעשה בראשה (\"וגלחה את ראשה\") \u0003ונאמרה עשיה בצפרנים, מה להלן,\u0004 בראש, פירושו: \u0003העברה\u0004 וקציצה של השיער — \u0003אף כאן\u0004 הכוונה ל\u0003העברה\u0004 של הצפרניים מן הגוף. \u0003ר' עקיבא אומר: נאמר עשיה בראש ונאמר עשיה בצפרנים, מה להלן\u0004 גילוח השערות נעשה ל\u0003ניוול\u0004 וכיעור — \u0003אף כאן,\u0004 בצפרניים, הכוונה היא ל\u0003ניוול\u0004 על ידי שתגדלן.","\u0003וראיה לדברי ר' אליעזר —\u0004 ממה שנאמר: \u0003\"ומפיבשת בן שאול ירד לקראת המלך\u0004 ו\u0003לא עשה רגליו ולא עשה שפמו\"\u0004 (שמואל ב' יט, כה), ושם על כורחך אתה מבין \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003עשיה\u0004 האמורה שם — \u0003העברה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 באותו ענין, נאמר: \u0003\"ובכתה את אביה ואת אמה\u0004 ירח ימים\u0003\"\u0004 (דברים כא, יג),"],["\u0003ר' אליעזר אומר: \"אביה\" — אביה ממש, \"אמה\" — אמה ממש\u0004, שהיא נפרדת מהם, ובוכה על כך. \u0003ר' עקיבא אומר: \"אביה ואמה\" — זו עבודה זרה,\u0004 ועליה היא בוכה שנאלצת להיפרד ממנה. \u0003וכן הוא אומר: \"אמרים לעץ אבי אתה\u0004 ולאבן את ילידתנו\u0003\"\u0004 (ירמיהו ב, כז).","ומחלוקת נוספת בפירוש הכתובים: מה שנאמר \u0003\"ירח ימים\",\u0004 פירושו: \u0003ירח\u0004 (חודש) בן \u0003שלשים יום. ר' שמעון בן אלעזר אומר: תשעים יום\u0004 היא שוהה. וכך הוא דורש: \u0003\"ירח\" — שלשים\u0004 יום, ו\u0003\"ימים\" — שלשים\u0004 יום נוספים, \u0003\"ואחר כן\" —\u0004 עוד \u0003שלשים\u0004 יום.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: אימא\u0004 \u0005[אמור]\u0006 לפי דרך דרשה זו באופן אחר: \u0003\"ירח\" — שלשים, \"ימים\" — שלשים, \"ואחר כן\" — כי הני\u0004 \u0005[כמו אלה],\u0006 כלומר, עוד שישים יום? ומסכמים, אכן \u0003קשיא\u0004 \u0005[קשה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מקיימין,\u0004 כלומר, מותר להחזיק \u0003עבדים שאינם מלין\u0004 (נימולים), אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: אין מקיימין. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ישמעאל, הרי הוא אומר\u0004 במצוות השבת: \u0003\"וינפש בן אמתך\"\u0004 (שמות כג, יב) ואם אין מקיימים אלא עבד שמל, משמע שכל עבד מקבל על עצמו מצוות השייכות לעבד, והן כוללות כל מצוות לא תעשה, וממילא חייב הוא לשמור את השבת ואין צורך להזהיר על כך לחוד! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' עקיבא: \u0003בלוקח\u0004 (קונה) \u0003עבד\u0004 בערב שבת \u0003בין השמשות ולא הספיק למולו הכתוב מדבר.\u0004","שאף עבד זה אסור להעבידו בשבת, ומעירים: \u0003דכולי עלמא מיהת\u0004 \u0005[\u0006לדעת \u0005הכל על כל פנים]\u0006 \u0003\"וינפש בן אמתך\" בעבד ערל כתיב\u0004 \u0005[\u0006הוא ש\u0005נאמר],\u0006 \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד נובעת משמעות זו מן הכתוב? ומסבירים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"וינפש בן אמתך\" — בעבד ערל הכתוב מדבר. אתה אומר בעבד ערל, או אינו אלא בעבד מהול? כשהוא אומר \"למען ינוח עבדך ואמתך כמוך\"\u0004 (דברים ה, יד), \u0003הרי עבד מהול אמור,\u0004 שהכתוב אומר שהוא כמוך ודומה לך. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"וינפש בן אמתך\" — בעבד ערל.\u0004","\u0003\"והגר\"\u0004 שנאמר באותו פסוק — \u0003זה גר תושב\u0004 שהוא גוי שגר בארץ ישראל ולא קיבל על עצמו יהדות. \u0003אתה אומר\u0004 זה \u0003גר תושב, או אינו אלא גר צדק\u0004 שהוא יהודי לכל דבריו?! \u0003כשהוא אומר \"וגרך אשר בשעריך\"\u0004 (שם ה, יד), \u0003הרי גר צדק אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"והגר\" — זה גר תושב.\u0004","\u0003אמר ר' יהושע בן לוי: הלוקח\u0004 (קונה) \u0003עבד מן הגוי ולא רצה\u0004 העבד \u0003למול — מגלגל עמו,\u0004 כלומר, מחזיק אותו ומשדלו \u0003עד שנים עשר חדש.\u0004 ואם עד תום תקופה זו \u0003לא מל — חוזר ומוכרו לגויים.\u0004","\u0003אמרוה\u0004 \u0005[אמרו אותה]\u0006 את הברייתא הזו \u0003רבנן קמיה\u0004 \u0005[החכמים לפני]\u0006 \u0003רב פפא\u0004 וביררו: \u0003כמאן\u0004 \u0005[כמי\u0006 היא\u0005]\u0006 ברייתא זו — ש\u0003לא כ\u0004דעת \u0003ר' עקיבא. דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כדעת \u0003ר' עקיבא — האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003אין מקיימין\u0004 עבד שלא מל! \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כדעת \u0003ר' עקיבא, הני מילי היכא דלא פסקא למילתיה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005היכן שלא פסק את דבריו],\u0006 שלא קצב לעבד זמן מוגדר של שנים עשר חודש למולו, ובענין זה אמר ר' עקיבא שלא יקיימו, \u0003אבל היכא דפסקא למילתיה\u0004 \u0005[היכן שפסק לדבריו],\u0006 שקצב לו זמן של שנים עשר חודש — \u0003פסקא\u0004 \u0005[פסק],\u0006 שאינו נחשב אלא כשכיר ומותר לו לקיימו כל שנים עשר חודש ומגלגל עמו עד שיסכים, ואם לא הסכים — ימכרנו.","\u0003אמר רב כהנא: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את ההלכה\u0006 הזאת \u0005לפני]\u0006 \u0003רב זביד מנהרדעא, אמר לי: אי הכי\u0004 \u0005[אם כך]\u0006 \u0003כי קאמר ליה\u0004 \u0005[כאשר אמר לו]\u0006 \u0003ר' עקיבא\u0004 לר' ישמעאל שהפסוק המדבר על עבד ערל הוא \u0003בלוקח עבד בין השמשות, לישני ליה הא\u0004 \u0005[שיתרץ לו זאת]\u0006 שאמר רב פפא כמדובר באופן שפסק דבריו, שהוא מצוי יותר מאשר במקרה נדיר זה שהזכיר! ומשיבים: אין זו קושיה, כי \u0003חדא מתרי טעמי קאמר\u0004 \u0005[אחד משני טעמים אמר],\u0006 שבאמת היה יכול להביא דוגמה אחרת שמותר לקיים, והביא בין השאר את זו.","\u0003שלח רבין משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אילעאי, ו\u0004הוסיף: \u0003כל רבותי אמרו לי משמו: איזהו עבד ערל שמותר לקיימו\u0004 בישראל — \u0003זה שלקחו\u0004 (קנה אותו) \u0003רבו על מנת שלא למולו. אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים\u0006 לשמועה זו \u0005לפני]\u0006 \u0003רב פפא: כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 הלכה זו? — ש\u0003לא כ\u0004דעת \u0003ר' עקיבא, דאי\u0004 \u0005[שאם]\u0006 כדעת \u0003ר' עקיבא\u0004 היא — \u0003האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003אין מקיימין\u0004 עבד שאינו נימול! \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' עקיבא,\u0004 אולם \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאמר ר' עקיבא אמורים דווקא \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא אתני בהדיה\u0004 \u0005[התנה אתו]\u0006 העבד מראש שאינו נימול, אז חייב למולו או למוכרו, \u0003אבל היכא דאתני\u0004 \u0005[היכן שהתנה] —\u0006 \u0003אתני\u0004 \u0005[התנה].\u0006","\u0003אמר רב כהנא: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי אותה, את\u0006 ההלכה \u0005לפני]\u0006 \u0003רב זביד מנהרדעא, ואמר לי: אי הכי\u0004 \u0005[אם כך],\u0006 \u0003כי קאמר ליה\u0004 \u0005[כאשר אמר לו]\u0006 \u0003ר' עקיבא\u0004 לר' ישמעאל שעבד ערל יכול להיות רק \u0003בלוקח עבד בין השמשות ולא הספיק למולו — לישני ליה הא\u0004 \u0005[שיתרץ לו זאת]\u0006 שהעבד התנה שלא ימול!","ומשיבים: \u0003וליטעמיך, לישני ליה הך\u0004 \u0005[ולטעמך,\u0006 לשיטתך, \u0005שיתרץ לו\u0006 ר' עקיבא \u0005זו],\u0006 שפסק שלא למול, \u0003אלא\u0004 ודאי \u0003חד מתרי ותלת טעמי קאמר\u0004 \u0005[אחד משנים ושלושה טעמים אמר]\u0006 ולא בא לומר את כולם.","מסופר: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' חנינא בר פפי ור' אמי ור' יצחק נפחא\u0004 \u0005[הנפח]\u0006 \u0003אקילעא\u0004 \u0005[בחצר]\u0006 של \u0003ר' יצחק נפחא, ויתבי וקאמרי\u0004 \u0005[וישבו ואמרו]:\u0006 \u0003עיר אחת היתה בארץ ישראל ולא רצו עבדיה למול, וגלגלו עמהם עד שנים עשר חדש, וחזרו ומכרום לגויים. כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 הלכה זו —","\u0003כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הלוקח עבד מן הגוי ולא רצה\u0004 העבד \u0003למול — מגלגל עמו עד שנים עשר חדש, לא מל — חוזר ומוכרו לגויים. ר' שמעון בן אלעזר אומר: אין משהין אותו\u0004 את העבד שלא נימול \u0003בארץ ישראל, מפני הפסד טהרות.\u0004 שכיון שאינו נימול דינו כגוי, וגזרו חכמים טומאה במגע גוי טמא, ועבד זה שבבית ישראל עלול לנגוע בטהרות ולטמאן. \u0003ובעיר הסמוכה לספר אין משהין אותו כל עיקר, שמא ישמע דבר\u0004 של סוד (כגון בענייני צבא ושמירה) \u0003וילך ויאמר\u0004 דבר זה \u0003לחברו\u0004 ה\u0003גוי,\u0004 שרק עבד שמל, וקיבל על עצמו יהדות במידה מסויימת, אין חוששים לו עוד.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' חנניא בנו של רבן גמליאל אומר: מפני מה גרים בזמן הזה מעונין\u0004 מכל צד, \u0003ויסורין באין עליהן — מפני שלא קיימו שבע מצות בני נח\u0004 בהיותם גויים, והם נענשים על כך כשמגיעים להיות ישראלים. \u0003ר' יוסי אומר:\u0004 טעם זה אינו נכון, כי \u0003גר שנתגייר — כקטן שנולד דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 וכל מה שעשה קודם לכן אינו נחשב לו, \u0003אלא מפני מה מעונין — לפי שאין בקיאין בדקדוקי מצות כישראל,\u0004 ועוברים עבירות מתוך חוסר ידיעה. \u0003אבא חנן אומר משום\u0004 (משמו של) \u0003ר' אלעזר:\u0004 הטעם הוא \u0003לפי שאין עושין מאהבה\u0004 לקדוש ברוך הוא, \u0003אלא מיראה,\u0004 מחשש עונשי גיהנום, וכיון שעשו זאת רק מיראת העונש הם מעונים אחר כך ביסורים.","\u0003אחרים אומרים: מפני ששהו עצמם\u0004 מ\u0003להכנס תחת כנפי השכינה. אמר ר' אבהו ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חנינא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המלמדנו ענין זה — \u0003\"ישלם ה' פעלך ותהי משכרתך שלמה מעם ה' אלהי ישראל אשר באת לחסות\u0004 תחת כנפיו\u0003\"\u0004 (רות ב, יב), כלומר, שתקבל שכר על שמיהרה לחסות תחת כנפי השכינה."],["\u0003איזהו ממזר — כל\u0004 הנולד מ\u0003שאר בשר\u0004 (מי שאסור משום קירבת משפחה) \u0003שהוא ב\"לא יבא\",\u0004 כלומר, שיש איסור לא תעשה על ביאה זו. אלו \u0003דברי ר' עקיבא. שמעון התימני אומר: כל שחייבים עליו כרת בידי שמים,\u0004 הוולד הנולד מביאה כזו, הוא ממזר. \u0003והלכה כדבריו. ור' יהושע אומר: כל שחייבין עליו מיתת בית דין.\u0004","\u0003אמר ר' שמעון בן עזאי: מצאתי מגלת יוחסין בירושלים, וכתוב בה: איש פלוני ממזר מאשת איש,\u0004 והרי זה בא \u0003לקיים\u0004 את \u0003דברי ר' יהושע\u0004 שממזר הוא מאשת איש וכיוצא בה, שהוא איסור שיש בו מיתת בית דין. שאם לא כן — מפני מה פירשו מה טעם ממזר הוא.","ובדיני עריות: \u0003אשתו שמתה — מותר באחותה. גרשה ומתה — מותר באחותה. נשאת לאחר ומתה — מותר באחותה,\u0004 אבל בחייה אסור בכל מקרה באחותה. \u0003יבמתו שמתה — מותר באחותה. חלץ לה ומתה — מותר באחותה. נשאת\u0004 חלוצתו \u0003לאחר ומתה — מותר באחותה,\u0004 אבל בחייה לא ישא את אחותה.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא? — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא יקח איש את אשת אביו ולא יגלה כנף אביו\"\u0004 (דברים כג, א), וכוונתו: \u0003כנף שראה אביו\u0004 באשה שבא עליה — \u0003לא יגלה\u0004 הבן.","\u0003וסבר לה\u0004 \u0005[וסבור\u0006 הוא\u0005]\u0006 בפירוש הכתוב \u0003כר' יהודה,\u0004 ש\u0003אמר: באנוסת אביו הכתוב מדבר\u0004 ולא באשת אביו, \u0003דהויא לה\u0004 \u0005[שהריהי]\u0006 רק \u0003חייבי לאוין,\u0004 שאף לדעת ר' יהודה אין איסור כרת אלא באשת אביו הנשואה לו,","\u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הפסוק \u0003\"לא יבא ממזר בקהל ה'\"\u0004 (שם ג) \u0003אלמא\u0004 \u0005[מכאן]\u0006 כי הנולד \u0003מהני\u0004 \u0005[מאלה],\u0006 מחייבי לאווין, \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ממזר,\u0004 ומכאן למד הלכה כללית, שממזר הוא זה שנולד מאיסור, כגון איסור אנוסת אביו, שהוא איסור לא תעשה.","ומבארים: \u0003ולר' סימאי,\u0004 ש\u0003מרבה\u0004 ומוסיף על הממזרים גם את הנולדים ל\u0003שאר חייבי לאוין, דלאו\u0004 \u0005[שאינן]\u0006 אסורות עליו דווקא מחמת קורבה שהוא איסור \u0003\"שאר\",\u0004 אלא אפילו מחמת איסור אחר, שכל שיש בו לא תעשה — הוולד ממזר, וכגון מחזיר גרושתו לאחר שנישאה לאחר, או הנישאת לאחד משבעה עמים. \u0003ו\u0004כן, \u0003לר' ישבב\u0004 ש\u0003מרבה\u0004 לענין ממזרות \u0003אפילו\u0004 את הנולדים מ\u0003חייבי\u0004 איסור \u0003עשה,\u0004","\u0003נפקא להו\u0004 \u0005[יוצא להם],\u0006 הם לומדים את הדבר \u0003מ\u0004מה שנאמר \u0003\"ולא\u0004 יגלה כנף אביו\u0003\",\u0004 ש־ו' יתירה זו באה ללמד, שלא רק במקרה זה, אלא גם בדומים לו הוולד ממזר.","\u0003ו\u0004אילו \u0003שמעון התימני\u0004 שסבור שממזר הוא רק מחייבי כריתות \u0003סבר לה כרבנן\u0004 \u0005[סבור הוא\u0006 בפירוש הפסוק הזה \u0005כ\u0006דעת \u0005חכמים]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003בשומרת יבם של אביו הכתוב מדבר,\u0004 שאף שאינה אשת אביו, מכל מקום אסורה על הבן, \u0003דהויא לה\u0004 \u0005[שהריהי]\u0006 \u0003חייבי כריתות\u0004 מצד אחר, משום אשת דודו (אחי אביו) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"לא יבא ממזר\". אלמא\u0004 \u0005[מכאן]:\u0006 שהנולד \u0003מחייבי כריתות הוי\u0004 \u0005[הריהו]\u0006 \u0003ממזר.\u0004","\u0003ור' יהושע\u0004 הסובר שממזר הוא זה הנולד מחייבי מיתות בית דין, מה הוא אומר? — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"לא יגלה\u0004 כנף אביו\u0003\"\u0004 בלבד, ומכל שכן שמאשת אביו הוולד ממזר — \u0003\"לא יקח\u0004 את אשת אביו\u0003\"\u0004 וכן \u0003\"ולא יגלה\",\u0004 שניהם \u0003למה לי? אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר]:\u0006 \u0003מ\"לא יקח\" עד \"לא יגלה\",\u0004 כלומר, רק הבא על אשת אביו שהיא הכתובה בכתוב בין \"לא יקח\" ו\"לא יגלה\" (\"לא יקח איש את אשת אביו ולא יגלה כנף אביו\") הוא שבנו מביאה זו \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ממזר,\u0004 אולם \u0003טפי\u0004 \u0005[יותר\u0006 מזה\u0005],\u0006 כלומר, הנולד מאיסורי ביאה אחרים שאינם חמורים כאיסור זה, שאין בהם חיוב מיתת בית דין — \u0003לא הוי\u0004 \u0005[איננו]\u0006 \u0003ממזר.\u0004","\u0003אמר אביי: הכל מודים בבא על הנדה\u0004"],["\u0003ועל הסוטה\u0004 (אשת איש שזנתה תחת בעלה ונאסרה עליו) ובכל זאת בא בעלה עליה — \u0003שאין הולד\u0004 הנולד מביאה כזו \u0003ממזר.\u0004","ומפרשים: \u0003נדה\u0004 מהיכן אנו יודעים שהוולד אינו ממזר? \u0003דהא תפסי\u0004 \u0005[שהרי תופסים]\u0006 \u0003בה קידושין, שנאמר: \"ותהי נדתה עליו\"\u0004 (ויקרא טו, כד), לומר: \u0003אפילו בשעת נדתה תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין,\u0004 שלשון \"ותהי\" מתפרשת כלשון הויה=נישואין.","\u0003סוטה נמי\u0004 \u0005[גם כן]\u0006 לא יהא הנולד ממנה ממזר \u0003דהא תפסי\u0004 \u0005[שהרי תופסים]\u0006 \u0003בה קידושין,\u0004 שהרי הקידושין הראשונים שקידש את האשה לא פקעו עם זנותה, והיא עדיין אשת איש לכל דבר.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הכל מודים בבא על הנדה, ועל הסוטה ועל שומרת יבם\u0004 לפני שנחלצה, \u0003שאין הולד ממזר.\u0004","ומסבירים: \u0003ואביי,\u0004 שלא מנה גם מקרה שלישי זה של \u0003שומרת יבם\u0004 — \u0003מספקא ליה\u0004 \u0005[ספק\u0006 היה \u0005לו\u0006 בה\u0005]\u0006 איך לפסוק, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003רב\u0004 שאין קידושי זר תופסים בה ולכן הוולד ממזר, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003שמואל\u0004 שקידושין תופסים בה והוולד איננו ממזר.","שנינו במשנה: \u0003אמר ר' שמעון בן עזאי\u0004 מצאתי מגילת יוחסין בירושלים כו'. \u0003תני\u0004 \u0005[שנה]\u0006 בברייתא, \u0003שמעון בן עזאי אומר: מצאתי מגלת יוחסין בירושלים, וכתוב בה: איש פלוני ממזר מאשת איש, וכתוב בה: משנת ר' אליעזר בן יעקב קב ונקי,\u0004 כלומר מעטה היא, אבל כל מה שאמר, הוא כהלכה, ופוסקים כמותו בכל מקום. \u0003וכתוב בה\u0004 עוד באותה מגילה: \u0003מנשה,\u0004 מלך ישראל, הוא ש\u0003הרג את ישעיה\u0004 הנביא.","\u0003אמר רבא\u0004 באותו ענין: \u0003מידן דייניה וקטליה\u0004 \u0005[דן אותו והרג אותו],\u0006 כלומר, לא הרגו סתם אלא העמידו לדין שנראה כדין תורה, והרגו. \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003משה רבך אמר: \"כי לא יראני האדם וחי\"\u0004 (שמות לג, כ) \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003אמרת: \"ואראה את ה' ישב על כסא רם ונשא\"\u0004 (ישעיהו ו, א). \u0003משה רבך אמר: \"מי\u0004 גוי גדול אשר לו אלהים קרובים אליו \u0003כה' אלהינו בכל קראנו אליו\"\u0004 (דברים ד, ז) \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003אמרת: \"דרשו ה' בהמצאו\u0004 קראוהו בהיותו קרוב\u0003\"\u0004 (ישעיה נה, ו), משמע שלא בכל עת הוא נמצא. \u0003משה רבך אמר: \"את מספר ימיך אמלא\"\u0004 (שמות כג, כו), משמע שלכל אדם יש שיעור ימים מסויים, \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003אמרת: \"והספתי על ימיך חמש עשרה שנה\"\u0004 (מלכים ב' כ, ו)!","\u0003אמר ישעיה: ידענא ביה דלא מקבל מה דאימא ליה\u0004 \u0005[יודע אני בו שלא יקבל\u0006 את \u0005מה שאומר לו]\u0006 להסביר את דבריי, \u0003ואי אימא ליה אישוייה\u0004 \u0005[ואם אומר לו אעשה אותו]\u0006 \u0003מזיד,\u0004 שלא יקבל דברי ונמצא יהרגני בלי הצדקה, \u0003אמר שם\u0004 של קודש \u0003איבלע בארזא\u0004 \u0005[\u0006ו\u0005נבלע ב\u0006תוך עץ \u0005ארז],\u0006 \u0003אתיוה לארזא ונסרוה\u0004 \u0005[הביאו את הארז\u0006 הזה \u0005וניסרו אותו]\u0006 כדי להורגו שם, \u0003כי מטא להדי פומא\u0004 \u0005[כאשר הגיע\u0006 המסור \u0005אל\u0006 מול \u0005פיו]\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 ישעיהו. ומדוע אירע לו הדבר כך בפיו — \u0003משום\u0004 ש\u0003אמר: \"ובתוך עם טמא שפתים אנכי ישב\"\u0004 (ישעיהו ו, ה), וכיון שקיטרג בפיו על ישראל — בכך נענש.","ושואלים: \u0003מכל מקום קשו קראי אהדדי\u0004 \u0005[\u0006הלא \u0005קשים הכתובים זה על זה]\u0006 ואיך באמת מבינים את הסתירות הללו?","ומפרשים; בענין מה שנאמר \u0003\"ואראה את ה'\"\u0004 יש לפרש \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל הנביאים נסתכלו באספקלריא\u0004 (בכלי ראייה) \u0003שאינה מאירה\u0004 (בהירה), ולכן היה נדמה להם שהם רואים, ואילו \u0003משה רבינו נסתכל באספקלריא המאירה —\u0004 וראה שאין רואים כלל.","ומה שנאמר \u0003\"דרשו ה' בהמצאו\"\u0004 שעומד בסתירה למה שאמר \"כה' אלוהינו בכל קראנו אליו\" — \u0003הא\u0004 \u0005[זה]\u0006 שמובן מדברי ישעיה שלא בכל עת הוא נמצא, הרי זה \u0003ביחיד\u0004 שיש זמנים מסויימים שתפילתו מתקבלת, \u0003הא\u0004 \u0005[זה]\u0006 שנאמר בתורה שה' נמצא \"בכל קראנו אליו\", הרי זה \u0003בצבור,\u0004 שתפילת הציבור מתקבלת תמיד. ושואלים, \u0003ויחיד אימת\u0004 \u0005[מתי]\u0006 ה' נמצא לו? \u0003אמר רב נחמן אמר רבה בר אבוה: אלו עשרה ימים שבין ראש השנה ליום הכפורים,\u0004 שהם ימי רצון ובהם תפילת כל אדם מתקבלת.","מה שאמר ישעיה \"והוספתי על ימיך חמש עשרה שנה\", שהוא מנוגד למשמעות הכתוב \u0003\"את מספר ימיך אמלא\"\u0004 שממנו משמע שימי האדם קצובים — \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בפירושו של פסוק זה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"את מספר ימיך אמלא\",\u0004"]]};
